	private void startReportLookup(String playerName, long generation) {
		if (reportCaseService == null || playerName == null || playerName.trim().isEmpty()) {
			return;
		}

		reportCaseService.requestReports(playerName, reports -> applyReportSummaries(generation, playerName, reports));
	}

	private void applyReportSummaries(long generation, String playerName, List<ReportSummary> reports) {
		if (generation != openGeneration) {
			return;
		}

		final QuickProfileModel current = model;
		if (current == null || current.getDisplayName() == null || !samePlayer(current.getDisplayName(), playerName)) {
			return;
		}

		model = current.toBuilder().reportSummaries(reports != null
				? reports
				: Collections.emptyList()).build();
	}

	private void startEfficiencyLookup(String playerName, long generation) {
		if (efficiencyMetricService == null
				|| !config.wiseOldManMetrics()
				|| (!config.showEhp() && !config.showEhb())
				|| playerName == null
				|| playerName.trim().isEmpty()) {
			return;
		}

		efficiencyMetricService.lookup(playerName)
				.thenAccept(data -> applyEfficiencyMetrics(generation, playerName, data));
	}

	private void applyEfficiencyMetrics(long generation, String playerName, EfficiencyProfileData data) {
		if (generation != openGeneration || !config.wiseOldManMetrics()) {
			return;
		}

		final QuickProfileModel current = model;
		if (current == null || current.getDisplayName() == null || !samePlayer(current.getDisplayName(), playerName)) {
			return;
		}

		model = current.toBuilder().efficientHoursPlayed(data != null
				? data.getEhp()
				: null).efficientHoursBossed(data != null
				? data.getEhb()
				: null).build();
	}

	private void startAutomaticEnrichment(String playerName, long generation) {
		if (playerName == null || playerName.trim().isEmpty()) {
			return;
		}

		final HiscoreEnrichmentService.EnrichmentRequest request = hiscoreEnrichmentService.enrich(playerName);

		applyEnrichment(generation, playerName, request.getInitialState(), request.getInitialData());

		final CompletableFuture<HiscoreEnrichmentCache.CachedProfileEnrichment> future = request.getFuture();
		if (future == null) {
			return;
		}

		future.thenAccept(result -> applyEnrichment(generation, playerName, result.getState(), result.getData()));
	}

	private void applyEnrichment(
			long generation,
			String playerName,
			HiscoreEnrichmentState state,
			HiscoreProfileData data) {
		if (generation != openGeneration) {
			return;
		}

		final QuickProfileModel current = model;
		if (current == null || current.getDisplayName() == null || !samePlayer(current.getDisplayName(), playerName)) {
			return;
		}

		// Keep asynchronous enrichment bound to the context captured when the profile opened.
		enrichmentData = data;

		final PlayerContext playerContext = profileContext;
		final List<ProfileMetricValue> contextMetrics = buildContextMetrics(playerContext, enrichmentData);

		model = current.toBuilder()
				.accountType(resolveAccountType(current.getAccountType(), data))
				.combatLevel(data != null && data.getCombatLevel() != null
						? data.getCombatLevel()
						: current.getCombatLevel())
				.totalLevel(data != null
						? data.getTotalLevel()
						: current.getTotalLevel())
				.contextMetrics(contextMetrics)
				.enrichmentState(state)
				.build();
	}

	private static AccountType resolveAccountType(AccountType current, HiscoreProfileData data) {
		final AccountType enriched = data != null
				? data.getAccountType()
				: AccountType.UNKNOWN;
		return AccountType.prefer(current, enriched);
	}

	private PlayerContext resolveProfileContext(PlayerIdentity identity) {
		if (identity == null) {
			return null;
		}

		// Nearby scene context takes priority.
		if (identity.isNearby()) {
			return playerContextService != null
					? playerContextService.getCurrent()
					: null;
		}

		// Remote Party members may use their own shared context.
		if (identity.getSources() == null
				|| !identity.getSources().contains(PlayerSource.PARTY)
				|| partyContextService == null) {
			return null;
		}

		final PartyContextService.PartyContext partyContext = partyContextService.find(identity.getCanonicalName());
		if (partyContext == null) {
			return null;
		}

		return profileMetricResolver.resolveLocation(
				new PlayerLocation(partyContext.getLocationName(), partyContext.getRegionId()));
	}

	private String displayLocation(String playerName, PlayerIdentity identity, PlayerContext context) {
		// Prefer an explicitly resolved location.
		if (context != null && context.getLocationName() != null && !context.getLocationName().trim().isEmpty()) {
			return context.getLocationName();
		}

		// Region-grid fallback is valid only for the local player.
		if (isLocalPlayerName(playerName)) {
			final PlayerContext localContext = context != null
					? context
					: playerContextService != null
							? playerContextService.getCurrent()
							: null;

			if (localContext != null) {
				if (localContext.getLocationName() != null && !localContext.getLocationName().trim().isEmpty()) {
					return localContext.getLocationName();
				}

				if (localContext.getRegionId() >= 0) {
					return formatRegionGrid(localContext.getRegionId());
				}
			}
		}

		// Nearby players without a mapped location expose only their nearby state.
		if (identity != null && identity.isNearby()) {
			return "Nearby";
		}

		return "Location: Unknown";
	}

	private boolean isLocalPlayerName(String playerName) {
		if (client == null || playerName == null || playerName.trim().isEmpty()) {
			return false;
		}

		final Player localPlayer = client.getLocalPlayer();
		return localPlayer != null && localPlayer.getName() != null && samePlayer(playerName, localPlayer.getName());
	}

	/*
	 * Locations.json stores [regionX, regionY]; region IDs pack that pair as
	 * (regionX << 8) | regionY.
	 */
	private static String formatRegionGrid(int regionId) {
		final int regionX = (regionId >>> 8) & 0xFF;
		final int regionY = regionId & 0xFF;

		return "Region: [" + regionX + ", " + regionY + "]";
	}

	private static String displayChannelName(PlayerIdentity identity, ChatMessageType originatingChatType) {
		// Prefer the resolved shared channel.
		if (identity != null && identity.getChannelName() != null && !identity.getChannelName().trim().isEmpty()) {
			return identity.getChannelName();
		}

		return displayMessageChannel(originatingChatType);
	}

	private static String displayMessageChannel(ChatMessageType chatType) {
		if (chatType == null) {
			return null;
		}

		switch (chatType) {
			case PUBLICCHAT:
			case MODCHAT:
				return "Public";

			case PRIVATECHAT:
			case MODPRIVATECHAT:
			case PRIVATECHATOUT:
				return "Private";

			case FRIENDSCHAT:
				return "Friends Chat";

			case CLAN_CHAT:
			case CLAN_GIM_CHAT:
				return "Clan";

			case CLAN_GUEST_CHAT:
				return "Guest Clan";

			default:
				return null;
		}
	}

	private static String displayChannelRank(PlayerIdentity identity) {
		// Message-derived channels do not provide a channel rank.
		if (identity == null || identity.getChannelName() == null || identity.getChannelName().trim().isEmpty()) {
			return null;
		}

		return identity.getChannelRank();
	}

	private static PlayerSource displayChannelSource(PlayerIdentity identity) {
		// Message-derived channels do not map to a PlayerSource.
		if (identity == null || identity.getChannelName() == null || identity.getChannelName().trim().isEmpty()) {
			return null;
		}

		return identity.getChannelSource();
	}

	private static List<ProfileMetricValue> buildContextMetrics(PlayerContext playerContext, HiscoreProfileData data) {
		if (playerContext == null || data == null || !playerContext.hasMetrics()) {
			return Collections.emptyList();
		}

		final List<ProfileMetricValue> values = new ArrayList<>();
		for (ProfileMetric metric : playerContext.getMetrics()) {
			final Integer value = data.getContextValue(metric.getHiscoreSkillName());
			if (value == null) {
				continue;
			}

			values.add(new ProfileMetricValue(metric.getLabel(), value));
		}

		return Collections.unmodifiableList(values);
	}

	private static boolean samePlayer(String left, String right) {
		return normalize(left).equals(normalize(right));
	}

	private static String normalize(String value) {
		return value == null
				? ""
				: value.trim().replace('\u00A0', ' ').replace('\u202F', ' ').replaceAll("[ _-]+", "")
						.toLowerCase(java.util.Locale.ROOT);
	}

	@lombok.Value
	public static class ProfileContextSnapshot {
		Integer world;
		String locationName;
		String channelName;
		PlayerSource channelSource;

		public static ProfileContextSnapshot empty() {
			return new ProfileContextSnapshot(null, null, null, null);
		}
	}

	private void clearLayoutBounds() {
		cardBounds = null;
		closeButtonBounds = null;
		tagButtonBounds = null;
		noteButtonBounds = null;
		favoriteButtonBounds = null;
		targetButtonBounds = null;
		lookupButtonBounds = null;
		clanLinkBounds = null;
		reportCaseLinkBounds = null;
		tagRemoveBounds.clear();
	}

	private static Rectangle copy(Rectangle rectangle) {
		return rectangle == null
				? null
				: new Rectangle(rectangle);
	}
}

package com.runetags.quickprofile;

import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;

import lombok.extern.slf4j.Slf4j;

import net.runelite.client.util.LinkBrowser;

@Slf4j
public class ClanLookupService {
	private static final String WOM_GROUP_SEARCH_URL = "https://wiseoldman.net/groups?search=";

	public void search(String clanName) {
		if (clanName == null || clanName.trim().isEmpty()) {
			return;
		}

		final String encodedName = URLEncoder.encode(clanName.trim(), StandardCharsets.UTF_8);
		final String url = WOM_GROUP_SEARCH_URL + encodedName;
		LinkBrowser.browse(url);
	}
}

