public final class TagChatboxInput extends ChatboxInput implements KeyListener, MouseListener {
	private static final int LEFT = 16;
	private static final int RIGHT = 16;
	private static final int START_Y = 38;

	private static final int PILL_HEIGHT = 18;
	private static final int PILL_PAD_X = 5;
	private static final int PILL_GAP_X = 5;
	private static final int PILL_GAP_Y = 4;
	private static final int PILL_TEXT_Y_OFFSET = 2;
	private static final int PILL_EDGE_BUFFER = 5;

	private static final Color PILL_BACKGROUND = new Color(55, 55, 55, 140);
	private static final Color PILL_BACKGROUND_HOVER = new Color(30, 30, 30, 140);

	private final ChatboxPanelManager chatboxPanelManager;
	private final ClientThread clientThread;
	private final List<String> selected = new ArrayList<>();
	private final List<TagHitbox> hitboxes = new ArrayList<>();

	private TagHitbox hoveredHitbox;
	private String prompt;
	private Consumer<List<String>> onDone;
	private Runnable onClose;
	private boolean built;

	public TagChatboxInput(ChatboxPanelManager chatboxPanelManager, ClientThread clientThread) {
		this.chatboxPanelManager = chatboxPanelManager;
		this.clientThread = clientThread;
	}

	public TagChatboxInput prompt(String prompt) {
		this.prompt = prompt;
		requestUpdate();
		return this;
	}

	public TagChatboxInput value(List<String> tags) {
		selected.clear();
		if (tags != null) {
			for (String value : tags) {
				final String tag = PlayerTagCatalog.canonical(value);
				if (tag != null && !selected.contains(tag) && selected.size() < PlayerTagCatalog.MAX_TAGS_PER_PLAYER) {
					selected.add(tag);
				}
			}
		}

		requestUpdate();
		return this;
	}

	public TagChatboxInput onDone(Consumer<List<String>> onDone) {
		this.onDone = onDone;
		return this;
	}

	public TagChatboxInput onClose(Runnable onClose) {
		this.onClose = onClose;
		return this;
	}

	public TagChatboxInput build() {
		if (prompt == null) {
			throw new IllegalStateException("prompt must be non-null");
		}

		chatboxPanelManager.openInput(this);
		return this;
	}

	@Override
	protected void open() {
		built = true;
		update();
	}

	@Override
	protected void close() {
		built = false;
		hoveredHitbox = null;
		hitboxes.clear();
		if (onClose != null) {
			onClose.run();
		}
	}

	private void requestUpdate() {
		if (built) {
			clientThread.invoke(this::update);
		}
	}

	private static void setPillColor(Widget background, Color color) {
		if (background == null || color == null) {
			return;
		}

		background.setTextColor(color.getRGB() & 0xFFFFFF);
		background.setOpacity(255 - color.getAlpha());
	}

	private void update() {
		final Widget container = chatboxPanelManager.getContainerWidget();
		if (container == null) {
			return;
		}

		container.deleteAllChildren();
		hitboxes.clear();
		final Widget promptWidget = container.createChild(-1, WidgetType.TEXT);
		promptWidget.setText(prompt);
		promptWidget.setTextColor(0x800000);
		promptWidget.setFontId(FontID.QUILL_8);
		promptWidget.setXPositionMode(WidgetPositionMode.ABSOLUTE_CENTER);
		promptWidget.setOriginalX(0);
		promptWidget.setYPositionMode(WidgetPositionMode.ABSOLUTE_TOP);
		promptWidget.setOriginalY(6);
		promptWidget.setOriginalHeight(24);
		promptWidget.setXTextAlignment(WidgetTextAlignment.CENTER);
		promptWidget.setYTextAlignment(WidgetTextAlignment.CENTER);
		promptWidget.setWidthMode(WidgetSizeMode.MINUS);
		promptWidget.revalidate();
		final Widget probe = container.createChild(-1, WidgetType.RECTANGLE);
		probe.setFontId(FontID.PLAIN_12);
		final FontTypeFace font = probe.getFont();
		probe.setHidden(true);
		if (font == null) {
			return;
		}

		if (selected.size() >= PlayerTagCatalog.MAX_TAGS_PER_PLAYER) {
			final Widget message = container.createChild(-1, WidgetType.TEXT);
			message.setFontId(FontID.BOLD_12);
			message.setText(
					"A maximum of (" + PlayerTagCatalog.MAX_TAGS_PER_PLAYER + ") Tags have already been selected.");
			message.setTextColor(0x282828);
			message.setXPositionMode(WidgetPositionMode.ABSOLUTE_CENTER);
			message.setXTextAlignment(WidgetTextAlignment.CENTER);
			message.setOriginalX(0);
			message.setOriginalY(START_Y + PILL_TEXT_Y_OFFSET);
			message.setOriginalWidth(Math.max(1, container.getWidth() - LEFT - RIGHT));
			message.setOriginalHeight(PILL_HEIGHT);
			message.revalidate();
			return;
		}

		final List<String> available = new ArrayList<>();
		for (String tag : PlayerTagCatalog.ALL) {
			if (!selected.contains(tag)) {
				available.add(tag);
			}
		}

		drawAvailable(container, font, available, START_Y);
	}

	private void drawAvailable(Widget container, FontTypeFace font, List<String> tags, int y) {
		int x = LEFT;
		final int maxX = Math.max(LEFT, container.getWidth() - RIGHT - PILL_EDGE_BUFFER);
		for (String tag : tags) {
			final int width = font.getTextWidth(tag) + (PILL_PAD_X * 2);
			if (x > LEFT && x + width + PILL_GAP_X > maxX) {
				x = LEFT;
				y += PILL_HEIGHT + PILL_GAP_Y;
			}

			final Widget background = container.createChild(-1, WidgetType.RECTANGLE);
			background.setFilled(true);
			setPillColor(background, PILL_BACKGROUND);
			background.setOriginalX(x);
			background.setOriginalY(y);
			background.setOriginalWidth(width);
			background.setOriginalHeight(PILL_HEIGHT);
			background.revalidate();
			final Widget text = container.createChild(-1, WidgetType.TEXT);
			text.setFontId(FontID.PLAIN_12);
			text.setText(Text.escapeJagex(tag));
			text.setTextColor(0xFFFFFF);
			text.setOriginalX(x + PILL_PAD_X);
			text.setOriginalY(y + PILL_TEXT_Y_OFFSET);
			text.setOriginalWidth(width - (PILL_PAD_X * 2));
			text.setOriginalHeight(PILL_HEIGHT);
			text.revalidate();
			hitboxes.add(new TagHitbox(new Rectangle(x, y, width, PILL_HEIGHT), tag, background));
			x += width + PILL_GAP_X;
		}
	}

	@Override
	public void keyPressed(KeyEvent event) {
		if (!chatboxPanelManager.shouldTakeInput()) {
			return;
		}

		if (event.getKeyCode() == KeyEvent.VK_ESCAPE || event.getKeyCode() == KeyEvent.VK_ENTER) {
			event.consume();
			chatboxPanelManager.close();
		}
	}

	@Override
	public void keyTyped(KeyEvent event) {
	}

	@Override
	public void keyReleased(KeyEvent event) {
	}

	@Override
	public MouseEvent mousePressed(MouseEvent event) {
		if (event.getButton() != MouseEvent.BUTTON1) {
			return event;
		}

		final Widget container = chatboxPanelManager.getContainerWidget();
		if (container == null) {
			return event;
		}

		final net.runelite.api.Point canvas = container.getCanvasLocation();
		final Point local = new Point(event.getX() - canvas.getX(), event.getY() - canvas.getY());
		for (TagHitbox hitbox : new ArrayList<>(hitboxes)) {
			if (!hitbox.bounds.contains(local)) {
				continue;
			}

			if (selected.size() >= PlayerTagCatalog.MAX_TAGS_PER_PLAYER) {
				return event;
			}

			selected.add(hitbox.tag);
			if (onDone != null) {
				onDone.accept(Collections.unmodifiableList(new ArrayList<>(selected)));
			}

			event.consume();
			chatboxPanelManager.close();
			return event;
		}

		return event;
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent event) {
		return event;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent event) {
		return event;
	}

	@Override
	public MouseEvent mouseEntered(MouseEvent event) {
		return event;
	}

	@Override
	public MouseEvent mouseExited(MouseEvent event) {
		if (hoveredHitbox != null) {
			setPillColor(hoveredHitbox.background, PILL_BACKGROUND);
			hoveredHitbox = null;
		}

		return event;
	}

	@Override
	public MouseEvent mouseDragged(MouseEvent event) {
		return event;
	}

	@Override
	public MouseEvent mouseMoved(MouseEvent event) {
		final Widget container = chatboxPanelManager.getContainerWidget();
		if (container == null) {
			return event;
		}

		final net.runelite.api.Point canvas = container.getCanvasLocation();
		final Point local = new Point(event.getX() - canvas.getX(), event.getY() - canvas.getY());
		TagHitbox nextHoveredHitbox = null;
		for (TagHitbox hitbox : hitboxes) {
			if (hitbox.bounds.contains(local)) {
				nextHoveredHitbox = hitbox;
				break;
			}
		}

		if (hoveredHitbox == nextHoveredHitbox) {
			return event;
		}

		if (hoveredHitbox != null) {
			setPillColor(hoveredHitbox.background, PILL_BACKGROUND);
		}

		hoveredHitbox = nextHoveredHitbox;
		if (hoveredHitbox != null) {
			setPillColor(hoveredHitbox.background, PILL_BACKGROUND_HOVER);
		}

		return event;
	}

	private static final class TagHitbox {
		private final Rectangle bounds;
		private final String tag;
		private final Widget background;
		private TagHitbox(Rectangle bounds, String tag, Widget background) {
			this.bounds = bounds;
			this.tag = tag;
			this.background = background;
		}
	}
}

package com.runetags.input;

import com.runetags.Configurations;
import com.runetags.config.ChatInteractionMode;
import com.runetags.quickprofile.QuickProfileController;

import java.awt.Point;
import java.awt.Rectangle;
import java.awt.event.MouseEvent;

import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.PostMenuSort;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.util.Text;

/**
 * Adds RuneTags profile actions to player names exposed through raid interfaces.
 */
public class RaidInterfaces extends MouseAdapter {
	private static final String MENU_OPEN_PROFILE = "Open Profile";
	private static final String MENU_KICK = "Kick";
	private static final String MENU_REJECT = "Reject";

	private static final RaidLayout TOA_ACCEPTED =
			new RaidLayout(InterfaceID.ToaPartydetails.MEMBERS_LIST, 13, 1, 2, 10);
	private static final RaidLayout TOA_APPLICANTS =
			new RaidLayout(InterfaceID.ToaPartydetails.APPLICANTS_LIST, 20, 1, 2, 18);
	private static final RaidLayout TOB_ACCEPTED =
			new RaidLayout(InterfaceID.TobPartydetails.CURRENT, 11, 1, 2, 10);
	private static final RaidLayout TOB_APPLICANTS =
			new RaidLayout(InterfaceID.TobPartydetails.APPLICANTS, 20, 1, 2, 18);

	private final Client client;
	private final Configurations config;
	private final QuickProfileController quickProfileController;

	private boolean suppressLeftClick;
	private volatile RaidHit leftClickHit;
	private volatile String nativeApplicantPlayer;

	public RaidInterfaces(Client client, Configurations config, QuickProfileController quickProfileController) {
		this.client = client;
		this.config = config;
		this.quickProfileController = quickProfileController;
	}

	public void onMenuEntryAdded(MenuEntryAdded event) {
		if (event == null
				|| !allowsRightClick()
				|| (event.getType() != MenuAction.CC_OP.getId()
				&& event.getType() != MenuAction.CC_OP_LOW_PRIORITY.getId())) {
			return;
		}

		final int componentId = event.getActionParam1();
		final String anchor = menuAnchor(componentId);
		if (anchor == null) {
			return;
		}

		final String option = event.getOption() != null
				? Text.removeTags(event.getOption())
				: "";
		if (!anchor.equals(option)) {
			return;
		}

		final String playerName = cleanPlayerName(event.getTarget());
		if (isEmptyPlayerName(playerName)) {
			return;
		}

		addProfileMenu(playerName, event.getTarget(), profileMenuIndex(playerName, componentId));
	}

	public void onPostMenuSort(PostMenuSort event) {
		if (client.isMenuOpen() || !allowsLeftClick()) {
			leftClickHit = null;
			return;
		}

		final Point point = currentMousePoint();
		final RaidHit hit = raidPlayerHit(point);

		updateApplicantState(hit);
		if (hit == null || !isProfileClick(hit)) {
			leftClickHit = null;
			return;
		}

		leftClickHit = hit;
		moveProfileToTop(hit, point);
	}

	public void onMenuOpened(MenuOpened event) {
		leftClickHit = null;

		final Point point = currentMousePoint();
		final RaidHit hit = raidPlayerHit(point);
		if (hit == null) {
			return;
		}

		final boolean rightClick = allowsRightClick();
		final String target = rightClick
				? profileMenuTarget(hit.playerName, hit.componentId)
				: null;

		removeProfileMenu(hit.playerName);
		if (!rightClick) {
			return;
		}

		addProfileMenu(hit.playerName, target, profileMenuIndex(hit.playerName, hit.componentId));
	}

	@Override
	public MouseEvent mousePressed(MouseEvent event) {
		suppressLeftClick = false;

		if (event == null || event.getButton() != MouseEvent.BUTTON1 || client.isMenuOpen()) {
			return event;
		}

		final ChatInteractionMode interactionMode = config.chatInteractionMode();
		if (interactionMode == null || !interactionMode.allowsLeftClick()) {
			return event;
		}

		final RaidHit hit = leftClickHit;
		if (hit == null || hit.bounds == null || !hit.bounds.contains(event.getPoint())) {
			return event;
		}

		openProfile(hit.playerName, event.getPoint());
		return consumeLeftClick(event);
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent event) {
		if (event != null && event.getButton() == MouseEvent.BUTTON1 && suppressLeftClick) {
			event.consume();
		}

		return event;
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent event) {
		if (event != null && event.getButton() == MouseEvent.BUTTON1 && suppressLeftClick) {
			suppressLeftClick = false;
			event.consume();
		}

		return event;
	}

	private MouseEvent consumeLeftClick(MouseEvent event) {
		suppressLeftClick = true;
		event.consume();
		return event;
	}

	private RaidHit raidPlayerHit(Point point) {
		RaidHit hit = playerHit(TOB_APPLICANTS, point);
		if (hit != null) {
			return hit;
		}

		hit = playerHit(TOB_ACCEPTED, point);
		if (hit != null) {
			return hit;
		}

		hit = playerHit(TOA_ACCEPTED, point);
		if (hit != null) {
			return hit;
		}

		return playerHit(TOA_APPLICANTS, point);
	}

	private RaidHit playerHit(RaidLayout layout, Point point) {
		if (point == null) {
			return null;
		}

		final Widget list = client.getWidget(layout.componentId);
		if (list == null || list.isSelfHidden()) {
			return null;
		}

		final Widget[] children = list.getDynamicChildren();
		if (children == null) {
			return null;
		}

		for (int base = 0; base + layout.nameOffset < children.length; base += layout.stride) {
			final int offset = hitOffset(layout, children, base, point);
			if (offset < 0) {
				continue;
			}

			final Widget username = children[base + layout.nameOffset];
			if (username == null || username.getType() != WidgetType.TEXT || username.isSelfHidden()) {
				continue;
			}

			final String playerName = cleanPlayerName(username.getText());
			if (isEmptyPlayerName(playerName)) {
				continue;
			}

			final Rectangle bounds = children[base + offset] != null
					? children[base + offset].getBounds()
					: null;

			return new RaidHit(layout.componentId, offset, playerName, bounds);
		}

		return null;
	}

	private static int hitOffset(RaidLayout layout, Widget[] children, int base, Point point) {
		final int nameIndex = base + layout.nameOffset;
		if (nameIndex < children.length && contains(children[nameIndex], point)) {
			return layout.nameOffset;
		}

		final int end = Math.min(base + layout.statsEnd, children.length - 1);
		for (int i = base + layout.statsStart; i <= end; i++) {
			if (contains(children[i], point)) {
				return i - base;
			}
		}

		return -1;
	}

	private static boolean contains(Widget widget, Point point) {
		if (widget == null || widget.isSelfHidden()) {
			return false;
		}

		final Rectangle bounds = widget.getBounds();
		return bounds != null && bounds.contains(point);
	}

	private boolean isProfileClick(RaidHit hit) {
		if (isApplicantComponent(hit.componentId)) {
			final RaidLayout layout = hit.componentId == TOB_APPLICANTS.componentId
					? TOB_APPLICANTS
					: TOA_APPLICANTS;

			if (hit.offset == layout.nameOffset) {
				return true;
			}

			return !hasNativeAction(hit.playerName)
					&& hit.offset >= layout.statsStart
					&& hit.offset <= layout.statsEnd;
		}

		return true;
	}

	private void updateApplicantState(RaidHit hit) {
		if (hit == null || !isApplicantComponent(hit.componentId)) {
			nativeApplicantPlayer = null;
			return;
		}

		nativeApplicantPlayer = hasApplicantAction(hit)
				? hit.playerName
				: null;
	}

	private boolean hasApplicantAction(RaidHit hit) {
		final String anchor = menuAnchor(hit.componentId);
		if (anchor == null) {
			return false;
		}

		for (MenuEntry entry : client.getMenu().getMenuEntries()) {
			if (entry != null
					&& anchor.equals(entry.getOption())
					&& hit.playerName.equalsIgnoreCase(cleanPlayerName(entry.getTarget()))) {
				return true;
			}
		}

		return false;
	}

	private boolean hasNativeAction(String playerName) {
		return nativeApplicantPlayer != null && nativeApplicantPlayer.equalsIgnoreCase(playerName);
	}

	private void moveProfileToTop(RaidHit hit, Point anchorPoint) {
		final MenuEntry[] entries = client.getMenu().getMenuEntries();
		if (entries.length > 0 && isProfileEntry(entries[entries.length - 1], hit.playerName)) {
			final String playerName = hit.playerName;
			entries[entries.length - 1].onClick(entry -> openProfile(playerName, anchorPoint));
			return;
		}

		final String target = profileMenuTarget(hit.playerName, hit.componentId);
		removeProfileMenu(hit.playerName);
		addProfileMenu(hit.playerName, target, -1, anchorPoint);
	}

	private void addProfileMenu(String playerName, String target, int index) {
		addProfileMenu(playerName, target, index, currentMousePoint());
	}

	private void addProfileMenu(String playerName, String target, int index, Point anchorPoint) {
		final String menuTarget = target != null && !target.trim().isEmpty()
				? target
				: playerName;

		client.createMenuEntry(index)
				.setOption(MENU_OPEN_PROFILE)
				.setTarget(menuTarget)
				.setType(MenuAction.RUNELITE)
				.onClick(entry -> openProfile(playerName, anchorPoint));
	}

	private void removeProfileMenu(String playerName) {
		final MenuEntry[] entries = client.getMenu().getMenuEntries();
		int retained = 0;

		for (MenuEntry entry : entries) {
			if (!isProfileEntry(entry, playerName)) {
				retained++;
			}
		}

		if (retained == entries.length) {
			return;
		}

		final MenuEntry[] updated = new MenuEntry[retained];
		int index = 0;
		for (MenuEntry entry : entries) {
			if (!isProfileEntry(entry, playerName)) {
				updated[index++] = entry;
			}
		}

		client.getMenu().setMenuEntries(updated);
	}

	private static boolean isProfileEntry(MenuEntry entry, String playerName) {
		return entry != null && MENU_OPEN_PROFILE.equals(entry.getOption())
				&& playerName.equalsIgnoreCase(cleanPlayerName(entry.getTarget()));
	}

	private int profileMenuIndex(String playerName, int componentId) {
		final String anchor = menuAnchor(componentId);
		if (anchor == null) {
			return -1;
		}

		final MenuEntry[] entries = client.getMenu().getMenuEntries();
		for (int i = 0; i < entries.length; i++) {
			final MenuEntry entry = entries[i];
			if (entry != null
					&& anchor.equals(entry.getOption())
					&& playerName.equalsIgnoreCase(cleanPlayerName(entry.getTarget()))) {
				return i;
			}
		}

		return -1;
	}

	private String profileMenuTarget(String playerName, int componentId) {
		final String anchor = menuAnchor(componentId);

		for (MenuEntry entry : client.getMenu().getMenuEntries()) {
			if (isProfileEntry(entry, playerName)) {
				return entry.getTarget();
			}

			if (anchor != null
					&& entry != null
					&& anchor.equals(entry.getOption())
					&& playerName.equalsIgnoreCase(cleanPlayerName(entry.getTarget()))) {
				return entry.getTarget();
			}
		}

		return playerName;
	}

	private static String menuAnchor(int componentId) {
		if (componentId == TOB_APPLICANTS.componentId || componentId == TOA_APPLICANTS.componentId) {
			return MENU_REJECT;
		}

		if (componentId == TOA_ACCEPTED.componentId) {
			return MENU_KICK;
		}

		return null;
	}

	private static boolean isApplicantComponent(int componentId) {
		return componentId == TOB_APPLICANTS.componentId || componentId == TOA_APPLICANTS.componentId;
	}

	private void openProfile(String playerName, Point anchorPoint) {
		quickProfileController.openPlayer(playerName, anchorPoint);
	}

	private Point currentMousePoint() {
		final net.runelite.api.Point canvasPoint = client.getMouseCanvasPosition();

		return canvasPoint != null
				? new Point(canvasPoint.getX(), canvasPoint.getY())
				: null;
	}

	private boolean allowsLeftClick() {
		final ChatInteractionMode interactionMode = config.chatInteractionMode();
		return interactionMode != null && interactionMode.allowsLeftClick();
	}

	private boolean allowsRightClick() {
		final ChatInteractionMode interactionMode = config.chatInteractionMode();
		return interactionMode != null && interactionMode.allowsRightClick();
	}

	private static boolean isEmptyPlayerName(String value) {
		return value == null || value.isEmpty() || "-".equals(value);
	}

	private static String cleanPlayerName(String value) {
		if (value == null) {
			return "";
		}

		return Text.removeTags(value).replace('\u00A0', ' ').trim();
	}

	private static final class RaidLayout {
		private final int componentId;
		private final int stride;
		private final int nameOffset;
		private final int statsStart;
		private final int statsEnd;

		private RaidLayout(int componentId, int stride, int nameOffset, int statsStart, int statsEnd) {
			this.componentId = componentId;
			this.stride = stride;
			this.nameOffset = nameOffset;
			this.statsStart = statsStart;
			this.statsEnd = statsEnd;
		}
	}

	private static final class RaidHit {
		private final int componentId;
		private final int offset;
		private final String playerName;
		private final Rectangle bounds;

		private RaidHit(int componentId, int offset, String playerName, Rectangle bounds) {
			this.componentId = componentId;
			this.offset = offset;
			this.playerName = playerName;
			this.bounds = bounds != null
					? new Rectangle(bounds)
					: null;
		}
	}
}

package com.runetags.input;

import java.awt.FontMetrics;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Shared normalization and wrapping rules for local player Notes.
 *
 * Explicit newlines remain logical bullet boundaries while ordinary text wraps
 * by pixel width for Quick Profile rendering and Note validation.
 */
public final class NoteTextLayout {
	public static final String BULLET = "\u2022";
	public static final String BULLET_PREFIX = BULLET + " ";

	public static final int MAX_LOGICAL_LINES = 3;
	public static final int MAX_RENDERED_ROWS = 4;

	private NoteTextLayout() {
	}

	public static String normalizeForEditor(String note) {
		if (note == null || note.trim().isEmpty()) {
			return BULLET_PREFIX;
		}

		final String normalized = normalizeLineEndings(note);
		final String[] logicalLines = normalized.split("\\n", -1);
		final List<String> editorLines = new ArrayList<>();
		for (String logicalLine : logicalLines) {
			final String clean = normalizeBulletLine(logicalLine);
			if (clean == null) {
				continue;
			}

			editorLines.add(clean);
		}

		if (editorLines.isEmpty()) {
			return BULLET_PREFIX;
		}

		return String.join("\n", editorLines);
	}

	public static String normalizeForStorage(String editorValue) {
		if (editorValue == null) {
			return null;
		}

		final String normalized = normalizeLineEndings(editorValue);
		final String[] logicalLines = normalized.split("\\n", -1);
		final List<String> storedLines = new ArrayList<>();
		for (String logicalLine : logicalLines) {
			final String clean = normalizeBulletLine(logicalLine);
			if (clean == null || BULLET.equals(clean)) {
				continue;
			}

			storedLines.add(clean);
		}

		if (storedLines.isEmpty()) {
			return null;
		}

		return String.join("\n", storedLines);
	}

	public static int logicalLineCount(String value) {
		if (value == null || value.isEmpty()) {
			return 0;
		}

		final String normalized = normalizeLineEndings(value);
		int count = 1;
		for (int index = 0; index < normalized.length(); ++index) {
			if (normalized.charAt(index) == '\n') {
				++count;
			}
		}

		return count;
	}

	public static int widestLogicalLineWidth(FontMetrics metrics, String text) {
		if (metrics == null || text == null || text.trim().isEmpty()) {
			return 0;
		}

		final String normalized = normalizeLineEndings(text);
		int widest = 0;
		for (String logicalLine : normalized.split("\\n", -1)) {
			widest = Math.max(widest, metrics.stringWidth(logicalLine.trim()));
		}

		return widest;
	}

	public static Result layout(FontMetrics metrics, String text, int maxWidth, int maxRows) {
		if (metrics == null || text == null || maxWidth <= 0 || maxRows <= 0) {
			return Result.empty();
		}

		final String normalized = normalizeLineEndings(text);
		if (normalized.trim().isEmpty()) {
			return Result.empty();
		}

		final List<String> rows = new ArrayList<>();
		boolean overflow = false;
		final String[] logicalLines = normalized.split("\\n", -1);
		outer:
		for (String logicalLine : logicalLines) {
			String remaining = logicalLine.trim();
			if (remaining.isEmpty()) {
				continue;
			}

			while (!remaining.isEmpty()) {
				if (rows.size() >= maxRows) {
					overflow = true;
					break outer;
				}

				if (metrics.stringWidth(remaining) <= maxWidth) {
					rows.add(remaining);
					remaining = "";
					continue;
				}

				final int fittingEnd = largestFittingPrefix(metrics, remaining, maxWidth);
				if (fittingEnd <= 0) {
					overflow = true;
					break outer;
				}

				int breakAt = remaining.lastIndexOf(' ', Math.max(0, fittingEnd - 1));
				if (breakAt <= 0) {
					breakAt = fittingEnd;
				}

				final String row = remaining.substring(0, breakAt).trim();
				if (!row.isEmpty()) {
					rows.add(row);
				}

				remaining = remaining.substring(breakAt).trim();
			}
		}

		return new Result(Collections.unmodifiableList(rows), overflow);
	}

	private static int largestFittingPrefix(FontMetrics metrics, String value, int maxWidth) {
		int low = 1;
		int high = value.length();
		int end = 0;
		while (low <= high) {
			final int middle = (low + high) >>> 1;
			if (metrics.stringWidth(value.substring(0, middle)) <= maxWidth) {
				end = middle;
				low = middle + 1;
			} else {
				high = middle - 1;
			}
		}

		return end;
	}

	private static String normalizeBulletLine(String value) {
		if (value == null) {
			return null;
		}

		String clean = value.trim();
		if (clean.isEmpty()) {
			return null;
		}

		if (clean.charAt(0) == BULLET.charAt(0)) {
			clean = clean.substring(1).trim();
		}

		if (clean.isEmpty()) {
			return BULLET;
		}

		return BULLET_PREFIX + clean;
	}

	private static String normalizeLineEndings(String value) {
		return value.replace("\r\n", "\n").replace('\r', '\n');
	}

	public static final class Result {
		private static final Result EMPTY = new Result(Collections.emptyList(), false);
		private final List<String> rows;
		private final boolean overflow;
		private Result(List<String> rows, boolean overflow) {
			this.rows = rows;
			this.overflow = overflow;
		}

		public static Result empty() {
			return EMPTY;
		}

		public List<String> getRows() {
			return rows;
		}

		public boolean isOverflow() {
			return overflow;
		}
	}
}

package com.runetags.input;

import java.awt.Point;
import java.awt.Rectangle;
import java.awt.Toolkit;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.UnsupportedFlavorException;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.function.Predicate;

import lombok.extern.slf4j.Slf4j;

import net.runelite.api.FontID;
import net.runelite.api.FontTypeFace;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetSizeMode;
import net.runelite.api.widgets.WidgetTextAlignment;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.chatbox.ChatboxInput;
import net.runelite.client.game.chatbox.ChatboxPanelManager;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.MouseListener;
import net.runelite.client.util.Text;

/**
 * Native chatbox editor for RuneTags player Notes.
 *
 * Hard line breaks remain logical bullet boundaries while soft wrapping is handled
 * independently for display. Shift+Enter inserts a bullet line and Enter submits.
 */
@Slf4j
public final class NoteChatboxInput extends ChatboxInput implements KeyListener, MouseListener {
	private static final int CURSOR_FLASH_RATE_MILLIS = 1000;
	private static final int TEXT_Y = 50;

	private static final int EDITOR_LEFT_PADDING = 16;
	private static final int EDITOR_RIGHT_PADDING = 16;
	private static final int BULLET_GUTTER_WIDTH = 10;
	private static final int BULLET_SIZE = 3;
	private static final int BULLET_Y_OFFSET = 3;

	private final ChatboxPanelManager chatboxPanelManager;
	private final ClientThread clientThread;

	private String prompt;
	private int visibleLines = 4;
	private int maxLength = 256;
	private int maxLogicalLines = NoteTextLayout.MAX_LOGICAL_LINES;

	private final StringBuilder value = new StringBuilder();

	private int cursor;
	private Predicate<String> onDone;
	private Runnable onClose;
	private boolean built;

	private volatile List<VisibleRow> visibleRows = Collections.emptyList();

	public NoteChatboxInput(ChatboxPanelManager chatboxPanelManager, ClientThread clientThread) {
		this.chatboxPanelManager = chatboxPanelManager;
		this.clientThread = clientThread;
	}

	public NoteChatboxInput prompt(String prompt) {
		this.prompt = prompt;
		requestUpdate();
		return this;
	}

	public NoteChatboxInput lines(int lines) {
		this.visibleLines = Math.max(1, lines);
		requestUpdate();
		return this;
	}

	public NoteChatboxInput maxLength(int maxLength) {
		this.maxLength = Math.max(1, maxLength);
		return this;
	}

	public NoteChatboxInput maxLogicalLines(int maxLogicalLines) {
		this.maxLogicalLines = Math.max(1, maxLogicalLines);
		return this;
	}

	public NoteChatboxInput value(String initialValue) {
		value.setLength(0);
		final String editorValue = NoteTextLayout.normalizeForEditor(initialValue);
		appendWithinLimit(editorValue);
		if (value.length() == 0) {
			value.append(NoteTextLayout.BULLET_PREFIX);
		}

		cursor = value.length();
		requestUpdate();
		return this;
	}

	public NoteChatboxInput onDone(Predicate<String> onDone) {
		this.onDone = onDone;
		return this;
	}

	public NoteChatboxInput onClose(Runnable onClose) {
		this.onClose = onClose;
		return this;
	}

	public String getValue() {
		return value.toString();
	}

	public NoteChatboxInput build() {
		if (prompt == null) {
			throw new IllegalStateException("prompt must be non-null");
		}

		chatboxPanelManager.openInput(this);
		return this;
	}

	@Override
	protected void open() {
		built = true;
		update();
	}

	@Override
	protected void close() {
		built = false;
		visibleRows = Collections.emptyList();
		if (onClose != null) {
			onClose.run();
		}
	}

	private void requestUpdate() {
		if (built) {
			clientThread.invoke(this::update);
		}
	}

	private void update() {
		final Widget container = chatboxPanelManager.getContainerWidget();
		if (container == null) {
			return;
		}

		container.deleteAllChildren();
		final Widget promptWidget = container.createChild(-1, WidgetType.TEXT);
		promptWidget.setText(prompt);
		promptWidget.setTextColor(0x800000);
		promptWidget.setFontId(FontID.BARBARIAN);
		promptWidget.setXPositionMode(WidgetPositionMode.ABSOLUTE_CENTER);
		promptWidget.setOriginalX(0);
		promptWidget.setYPositionMode(WidgetPositionMode.ABSOLUTE_TOP);
		promptWidget.setOriginalY(8);
		promptWidget.setOriginalHeight(24);
		promptWidget.setXTextAlignment(WidgetTextAlignment.CENTER);
		promptWidget.setYTextAlignment(WidgetTextAlignment.CENTER);
		promptWidget.setWidthMode(WidgetSizeMode.MINUS);
		promptWidget.revalidate();
		drawEditor(container);
	}

	private void drawEditor(Widget container) {
		final Widget cursorWidget = container.createChild(-1, WidgetType.RECTANGLE);
		final long start = System.currentTimeMillis();
		cursorWidget.setOnTimerListener((JavaScriptCallback) event -> {
			final boolean on = (System.currentTimeMillis() - start) % CURSOR_FLASH_RATE_MILLIS
					> CURSOR_FLASH_RATE_MILLIS / 2;
			cursorWidget.setOpacity(on
					? 255
					: 0);
		});
		cursorWidget.setTextColor(0xFFFFFF);
		cursorWidget.setHasListener(true);
		cursorWidget.setFilled(true);
		cursorWidget.setFontId(FontID.PLAIN_12);
		final FontTypeFace font = cursorWidget.getFont();
		if (font == null) {
			visibleRows = Collections.emptyList();
			return;
		}

		final int lineHeight = Math.max(1, font.getBaseline());
		final int width = Math.max(1, container.getWidth());

		/*
		 * Use a stable left-aligned text area with a dedicated bullet gutter. Logical
		 * rows draw a bullet there; soft-wrapped continuation rows share the text X
		 * without drawing another bullet.
		 */
		final int textX = EDITOR_LEFT_PADDING + BULLET_GUTTER_WIDTH;
		final int textAreaWidth = Math.max(1, width - textX - EDITOR_RIGHT_PADDING);
		final List<InputRow> allRows = buildRows(font, textAreaWidth);
		final int cursorRowIndex = findCursorRow(allRows);
		final int viewportStart = viewportStart(allRows.size(), cursorRowIndex);
		final int viewportEnd = Math.min(allRows.size(), viewportStart + visibleLines);
		final List<VisibleRow> rendered = new ArrayList<>();
		int y = TEXT_Y;
		for (int index = viewportStart; index < viewportEnd; ++index) {
			final InputRow row = allRows.get(index);
			final String displayText = row.text;
			final int textWidth = font.getTextWidth(displayText);

			/*
			 * QUILL_8 does not reliably expose the Unicode bullet glyph, so draw the
			 * marker as a small native rectangle in the bullet gutter instead.
			 */
			if (row.bullet) {
				final Widget bulletWidget = container.createChild(-1, WidgetType.RECTANGLE);
				bulletWidget.setTextColor(0x000000);
				bulletWidget.setFilled(true);
				bulletWidget.setOriginalX(EDITOR_LEFT_PADDING + 2);
				bulletWidget.setOriginalY(y + Math.max(1, (lineHeight - BULLET_SIZE) / 2) + BULLET_Y_OFFSET);
				bulletWidget.setOriginalWidth(BULLET_SIZE);
				bulletWidget.setOriginalHeight(BULLET_SIZE);
				bulletWidget.revalidate();
			}

			final Widget textWidget = container.createChild(-1, WidgetType.TEXT);
			textWidget.setFontId(FontID.PLAIN_12);
			textWidget.setText(Text.escapeJagex(displayText));
			textWidget.setOriginalX(textX);
			textWidget.setOriginalY(y);
			textWidget.setOriginalWidth(textAreaWidth);
			textWidget.setOriginalHeight(lineHeight);
			textWidget.revalidate();
			if (index == cursorRowIndex) {
				final int relativeCursor = Math.max(0, Math.min(displayText.length(), cursor - row.start));
				final int cursorX = textX + font.getTextWidth(displayText.substring(0, relativeCursor));
				cursorWidget.setOriginalX(cursorX - 1);
				cursorWidget.setOriginalY(y);
				cursorWidget.setOriginalWidth(2);
				cursorWidget.setOriginalHeight(lineHeight);
				cursorWidget.revalidate();
			}

			// Use the full text area so clicks after visible text place the cursor at the row end.
			rendered.add(new VisibleRow(row, textX, y, textAreaWidth, lineHeight));
			y += lineHeight;
		}

		visibleRows = Collections.unmodifiableList(rendered);
	}

	private List<InputRow> buildRows(FontTypeFace font, int maxWidth) {
		final List<InputRow> rows = new ArrayList<>();
		int logicalStart = 0;
		while (logicalStart <= value.length()) {
			final int newlineIndex = indexOfNewline(logicalStart);
			final int logicalEnd = newlineIndex >= 0
					? newlineIndex
					: value.length();
			final int prefixLength = NoteTextLayout.BULLET_PREFIX.length();
			final boolean hasBullet = logicalEnd - logicalStart >= prefixLength && value
					.substring(logicalStart, logicalStart + prefixLength).equals(NoteTextLayout.BULLET_PREFIX);

			/*
			 * Stored text retains "• ", while QUILL_8 renders only the editable text and
			 * drawEditor() renders the bullet separately.
			 */
			final int contentStart = hasBullet
					? logicalStart + prefixLength
					: logicalStart;
			wrapLogicalLine(rows, font, maxWidth, contentStart, logicalEnd, hasBullet);
			if (newlineIndex < 0) {
				break;
			}

			logicalStart = newlineIndex + 1;
		}

		if (rows.isEmpty()) {
			rows.add(new InputRow(0, 0, "", false));
		}

		return rows;
	}

	private void wrapLogicalLine(
			List<InputRow> output,
			FontTypeFace font,
			int maxWidth,
			int start,
			int end,
			boolean bullet) {
		if (start >= end) {
			output.add(new InputRow(start, end, "", bullet));
			return;
		}

		int rowStart = start;
		boolean firstRow = true;
		while (rowStart < end) {
			int fittingEnd = rowStart;
			int lastSpace = -1;
			for (int index = rowStart; index < end; ++index) {
				final char character = value.charAt(index);
				final String candidate = value.substring(rowStart, index + 1);
				if (font.getTextWidth(candidate) <= maxWidth) {
					fittingEnd = index + 1;
					if (character == ' ') {
						lastSpace = index;
					}

					continue;
				}

				break;
			}

			if (fittingEnd <= rowStart) {
				fittingEnd = Math.min(end, rowStart + 1);
			} else if (fittingEnd < end && lastSpace >= rowStart) {
				/*
				 * Keep the wrapping space in the previous row's source span so every source
				 * position remains owned by rendered geometry.
				 */
				fittingEnd = lastSpace + 1;
			}

			final int rowEnd = fittingEnd;

			/*
			 * Do not trim or skip boundary spaces; every source
			 * character must belong to exactly one InputRow.
			 */
			output.add(new InputRow(rowStart, rowEnd, value.substring(rowStart, rowEnd), firstRow && bullet));
			rowStart = rowEnd;
			firstRow = false;
		}
	}

	private int findCursorRow(List<InputRow> rows) {
		for (int index = 0; index < rows.size(); ++index) {
			final InputRow row = rows.get(index);
			if (row.start == row.end && cursor == row.start) {
				return index;
			}

			if (cursor >= row.start && cursor < row.end) {
				return index;
			}

			if (cursor == row.end) {
				final boolean nextRowStartsHere = index + 1 < rows.size() && rows.get(index + 1).start == cursor;

				/*
				 * At a soft-wrap boundary, assign the cursor to the next row;
				 * at the logical line end, keep it on the current row.
				 */
				if (!nextRowStartsHere) {
					return index;
				}
			}
		}

		return Math.max(0, rows.size() - 1);
	}

	private int viewportStart(int rowCount, int cursorRowIndex) {
		if (rowCount <= visibleLines) {
			return 0;
		}

		return Math.max(0, Math.min(cursorRowIndex - visibleLines + 1, rowCount - visibleLines));
	}

	private int indexOfNewline(int fromIndex) {
		for (int index = fromIndex; index < value.length(); ++index) {
			if (value.charAt(index) == '\n') {
				return index;
			}
		}

		return -1;
	}

	@Override
	public void keyTyped(KeyEvent event) {
		if (!chatboxPanelManager.shouldTakeInput()) {
			return;
		}

		final char character = event.getKeyChar();
		if (character < 32 || character >= 127) {
			return;
		}

		if (value.length() >= maxLength) {
			setTemporaryPrompt("RuneTags Note: max " + maxLength + " characters");
			return;
		}

		value.insert(cursor, character);
		++cursor;
		requestUpdate();
	}

	@Override
	public void keyPressed(KeyEvent event) {
		if (!chatboxPanelManager.shouldTakeInput()) {
			return;
		}

		final int code = event.getKeyCode();
		if (event.isControlDown()) {
			if (code == KeyEvent.VK_V) {
				event.consume();
				pasteClipboard();
			}

			return;
		}

		switch (code) {
			case KeyEvent.VK_ENTER:
				event.consume();
				if (event.isShiftDown()) {
					insertBulletLine();
					return;
				}

				if (onDone != null && !onDone.test(getValue())) {
					return;
				}

				chatboxPanelManager.close();
				return;
			case KeyEvent.VK_ESCAPE:
				event.consume();
				chatboxPanelManager.close();
				return;
			case KeyEvent.VK_BACK_SPACE:
				event.consume();
				backspace();
				return;
			case KeyEvent.VK_DELETE:
				event.consume();
				delete();
				return;
			case KeyEvent.VK_LEFT:
				event.consume();
				final int editableStart = editableLineStart(cursor);
				if (cursor > editableStart) {
					--cursor;
				} else {
					final int logicalStart = logicalLineStart(cursor);
					if (logicalStart > 0) {
						// Cross "\n• " as one structural boundary to the previous logical line.
						cursor = logicalLineEnd(logicalStart - 1);
					}
				}

				requestUpdate();
				return;
			case KeyEvent.VK_RIGHT:
				event.consume();
				final int currentLineEnd = logicalLineEnd(cursor);
				if (cursor < currentLineEnd) {
					++cursor;
				} else if (currentLineEnd < value.length()) {
					// Skip the complete newline + bullet prefix as one structural boundary.
					cursor = editableLineStart(currentLineEnd + 1);
				}

				requestUpdate();
				return;
			case KeyEvent.VK_HOME:
				event.consume();
				cursor = editableLineStart(cursor);
				requestUpdate();
				return;
			case KeyEvent.VK_END:
				event.consume();
				cursor = logicalLineEnd(cursor);
				requestUpdate();
				return;
			case KeyEvent.VK_UP:
				event.consume();
				moveVertical(-1);
				return;
			case KeyEvent.VK_DOWN:
				event.consume();
				moveVertical(1);
				return;
			default:
				return;
		}
	}

	@Override
	public void keyReleased(KeyEvent event) {
	}

	private void insertBulletLine() {
		if (NoteTextLayout.logicalLineCount(getValue()) >= maxLogicalLines) {
			setTemporaryPrompt("RuneTags Note: max " + maxLogicalLines + " bullets");
			return;
		}

		final String insertion = "\n" + NoteTextLayout.BULLET_PREFIX;
		if (value.length() + insertion.length() > maxLength) {
			setTemporaryPrompt("RuneTags Note: max " + maxLength + " characters");
			return;
		}

		value.insert(cursor, insertion);
		cursor += insertion.length();
		requestUpdate();
	}

	private void backspace() {
		if (cursor <= 0) {
			return;
		}

		final int lineStart = logicalLineStart(cursor);
		final int editableStart = editableLineStart(cursor);
		final int lineEnd = logicalLineEnd(cursor);

		/*
		 * On an empty secondary bullet, Backspace removes the complete "\n• "
		 * structure and returns to the previous logical line. The first bullet is
		 * permanent while the editor is open.
		 */
		if (cursor == editableStart && lineStart > 0 && lineEnd == editableStart) {
			value.delete(lineStart - 1, editableStart);
			cursor = lineStart - 1;
			requestUpdate();
			return;
		}

		// Prevent Backspace from entering or deleting the structural bullet prefix.
		if (cursor <= editableStart) {
			return;
		}

		value.deleteCharAt(cursor - 1);
		--cursor;
		requestUpdate();
	}

	private void delete() {
		if (cursor >= value.length()) {
			return;
		}

		final int lineEnd = logicalLineEnd(cursor);

		// Prevent Delete from crossing a logical-line boundary or removing its bullet prefix.
		if (cursor >= lineEnd) {
			return;
		}

		value.deleteCharAt(cursor);
		requestUpdate();
	}

	private int logicalLineStart(int position) {
		int index = Math.max(0, Math.min(position, value.length()));
		while (index > 0 && value.charAt(index - 1) != '\n') {
			--index;
		}

		return index;
	}

	private int editableLineStart(int position) {
		final int lineStart = logicalLineStart(position);
		final int lineEnd = logicalLineEnd(lineStart);
		final int prefixLength = NoteTextLayout.BULLET_PREFIX.length();
		if (lineEnd - lineStart >= prefixLength && value.substring(lineStart, lineStart + prefixLength)
				.equals(NoteTextLayout.BULLET_PREFIX)) {
			return lineStart + prefixLength;
		}

		return lineStart;
	}

	private int logicalLineEnd(int position) {
		int index = Math.max(0, Math.min(position, value.length()));
		while (index < value.length() && value.charAt(index) != '\n') {
			++index;
		}

		return index;
	}

	private void moveVertical(int direction) {
		final List<VisibleRow> rows = visibleRows;
		if (rows.isEmpty()) {
			return;
		}

		int currentIndex = -1;
		for (int index = 0; index < rows.size(); ++index) {
			final InputRow row = rows.get(index).row;
			if (cursor >= row.start && cursor <= row.end) {
				currentIndex = index;
				break;
			}
		}

		if (currentIndex < 0) {
			return;
		}

		final int targetIndex = currentIndex + direction;
		if (targetIndex < 0 || targetIndex >= rows.size()) {
			return;
		}

		final InputRow currentRow = rows.get(currentIndex).row;
		final InputRow targetRow = rows.get(targetIndex).row;
		final int column = Math.max(0, cursor - currentRow.start);
		cursor = Math.min(targetRow.end, targetRow.start + column);
		requestUpdate();
	}

	private void pasteClipboard() {
		try {
			final Object clipboardValue = Toolkit.getDefaultToolkit().getSystemClipboard()
					.getData(DataFlavor.stringFlavor);
			if (clipboardValue == null) {
				return;
			}

			String pasted = clipboardValue.toString().replace("\r\n", " ").replace('\r', ' ').replace('\n', ' ')
					.replace(NoteTextLayout.BULLET, "-");
			final StringBuilder clean = new StringBuilder();
			for (int index = 0; index < pasted.length(); ++index) {
				final char character = pasted.charAt(index);
				if (character >= 32 && character < 127) {
					clean.append(character);
				}
			}

			final int available = Math.max(0, maxLength - value.length());
			if (clean.length() > available) {
				clean.setLength(available);
			}

			if (clean.length() == 0) {
				return;
			}

			value.insert(cursor, clean);
			cursor += clean.length();
			requestUpdate();
		} catch (IOException | UnsupportedFlavorException exception) {
			log.warn("Unable to Read Clipboard for RuneTags Note", exception);
		}
	}

	private void appendWithinLimit(String text) {
		if (text == null || text.isEmpty()) {
			return;
		}

		final int available = Math.max(0, maxLength - value.length());
		value.append(text, 0, Math.min(text.length(), available));
	}

	private void setTemporaryPrompt(String message) {
		prompt = message;
		requestUpdate();
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent mouseEvent) {
		return mouseEvent;
	}

	@Override
	public MouseEvent mousePressed(MouseEvent mouseEvent) {
		if (mouseEvent.getButton() != MouseEvent.BUTTON1) {
			return mouseEvent;
		}

		final Widget container = chatboxPanelManager.getContainerWidget();
		if (container == null) {
			return mouseEvent;
		}

		final net.runelite.api.Point canvasLocation = container.getCanvasLocation();
		final int localX = mouseEvent.getX() - canvasLocation.getX();
		final int localY = mouseEvent.getY() - canvasLocation.getY();
		for (VisibleRow visibleRow : visibleRows) {
			final Rectangle bounds = new Rectangle(
					visibleRow.x, visibleRow.y, Math.max(1, visibleRow.width),
					visibleRow.height);
			if (!bounds.contains(new Point(localX, localY))) {
				continue;
			}

			final Widget probe = container.createChild(-1, WidgetType.RECTANGLE);
			probe.setFontId(FontID.PLAIN_12);
			final FontTypeFace font = probe.getFont();
			probe.setHidden(true);
			if (font == null) {
				break;
			}

			final int relativeX = Math.max(0, localX - visibleRow.x);
			int bestOffset = 0;
			int bestDistance = Integer.MAX_VALUE;
			for (int offset = 0; offset <= visibleRow.row.text.length(); ++offset) {
				final int x = font.getTextWidth(visibleRow.row.text.substring(0, offset));
				final int distance = Math.abs(x - relativeX);
				if (distance < bestDistance) {
					bestDistance = distance;
					bestOffset = offset;
				}
			}

			cursor = Math.min(visibleRow.row.end, visibleRow.row.start + bestOffset);
			requestUpdate();
			break;
		}

		return mouseEvent;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent mouseEvent) {
		return mouseEvent;
	}

	@Override
	public MouseEvent mouseEntered(MouseEvent mouseEvent) {
		return mouseEvent;
	}

	@Override
	public MouseEvent mouseExited(MouseEvent mouseEvent) {
		return mouseEvent;
	}

	@Override
	public MouseEvent mouseDragged(MouseEvent mouseEvent) {
		return mouseEvent;
	}

	@Override
	public MouseEvent mouseMoved(MouseEvent mouseEvent) {
		return mouseEvent;
	}

	private static final class InputRow {
		private final int start;
		private final int end;
		private final String text;
		private final boolean bullet;
		private InputRow(int start, int end, String text, boolean bullet) {
			this.start = start;
			this.end = end;
			this.text = text != null
					? text
					: "";
			this.bullet = bullet;
		}
	}

	private static final class VisibleRow {
		private final InputRow row;
		private final int x;
		private final int y;
		private final int width;
		private final int height;
		private VisibleRow(InputRow row, int x, int y, int width, int height) {
			this.row = row;
			this.x = x;
			this.y = y;
			this.width = width;
			this.height = height;
		}
	}
}

package com.runetags.input;

import com.runetags.Configurations;
import com.runetags.config.ChatInteractionMode;
import com.runetags.quickprofile.QuickProfileController;

import java.awt.Point;
import java.awt.Rectangle;
import java.awt.event.MouseEvent;

import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.PostMenuSort;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.util.Text;

/**
 * Adds RuneTags profile actions to player names exposed through minigame interfaces.
 */
public class MinigameInput extends MouseAdapter {
	private static final String MENU_OPEN_PROFILE = "Open Profile";

	private static final int[] BA_TEAM_NAMES = {
			InterfaceID.BarbassaultScrollPl1.BARBASSAULT_SCROLL_PL1_TN1,
			InterfaceID.BarbassaultScrollPl1.BARBASSAULT_SCROLL_PL1_TN2,
			InterfaceID.BarbassaultScrollPl1.BARBASSAULT_SCROLL_PL1_TN3,
			InterfaceID.BarbassaultScrollPl1.BARBASSAULT_SCROLL_PL1_TN4,
			InterfaceID.BarbassaultScrollPl1.BARBASSAULT_SCROLL_PL1_TN5,
			InterfaceID.BarbassaultScrollPl2.BARBASSAULT_SCROLL_PL2_TN1,
			InterfaceID.BarbassaultScrollPl2.BARBASSAULT_SCROLL_PL2_TN2,
			InterfaceID.BarbassaultScrollPl2.BARBASSAULT_SCROLL_PL2_TN3,
			InterfaceID.BarbassaultScrollPl2.BARBASSAULT_SCROLL_PL2_TN4,
			InterfaceID.BarbassaultScrollPl2.BARBASSAULT_SCROLL_PL2_TN5
	};

	private static final int[] BA_ROLE_NAMES = {
			InterfaceID.MessagescrollHandwriting.MESSAGESCROLL4_HW,
			InterfaceID.MessagescrollHandwriting.MESSAGESCROLL5_HW,
			InterfaceID.MessagescrollHandwriting.MESSAGESCROLL6_HW,
			InterfaceID.MessagescrollHandwriting.MESSAGESCROLL7_HW
	};

	private final Client client;
	private final Configurations config;
	private final QuickProfileController quickProfileController;

	private boolean suppressLeftClick;
	private volatile MinigameHit leftClickHit;

	public MinigameInput(Client client, Configurations config, QuickProfileController quickProfileController) {
		this.client = client;
		this.config = config;
		this.quickProfileController = quickProfileController;
	}

	public void onPostMenuSort(PostMenuSort event) {
		if (client.isMenuOpen() || !allowsLeftClick()) {
			leftClickHit = null;
			return;
		}

		final Point point = currentMousePoint();
		final MinigameHit hit = minigamePlayerHit(point);
		if (hit == null) {
			leftClickHit = null;
			return;
		}

		leftClickHit = hit;
		moveProfileToTop(hit, point);
	}

	public void onMenuOpened(MenuOpened event) {
		leftClickHit = null;

		final Point point = currentMousePoint();
		final MinigameHit hit = minigamePlayerHit(point);
		if (hit == null) {
			return;
		}

		final boolean rightClick = allowsRightClick();
		final String target = rightClick
				? profileMenuTarget(hit.playerName)
				: null;

		removeProfileMenu(hit.playerName);
		if (!rightClick) {
			return;
		}

		addProfileMenu(hit.playerName, target, -1, point);
	}

	@Override
	public MouseEvent mousePressed(MouseEvent event) {
		suppressLeftClick = false;

		if (event == null || event.getButton() != MouseEvent.BUTTON1 || client.isMenuOpen()) {
			return event;
		}

		final ChatInteractionMode interactionMode = config.chatInteractionMode();
		if (interactionMode == null || !interactionMode.allowsLeftClick()) {
			return event;
		}

		final MinigameHit hit = leftClickHit;
		if (hit == null || hit.bounds == null || !hit.bounds.contains(event.getPoint())) {
			return event;
		}

		openProfile(hit.playerName, event.getPoint());
		return consumeLeftClick(event);
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent event) {
		if (event != null && event.getButton() == MouseEvent.BUTTON1 && suppressLeftClick) {
			event.consume();
		}

		return event;
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent event) {
		if (event != null && event.getButton() == MouseEvent.BUTTON1 && suppressLeftClick) {
			suppressLeftClick = false;
			event.consume();
		}

		return event;
	}

	private MouseEvent consumeLeftClick(MouseEvent event) {
		suppressLeftClick = true;
		event.consume();
		return event;
	}

	private MinigameHit minigamePlayerHit(Point point) {
		return barbarianAssaultHit(point);
	}

	private MinigameHit barbarianAssaultHit(Point point) {
		if (point == null) {
			return null;
		}

		for (int componentId : BA_TEAM_NAMES) {
			final MinigameHit hit = barbarianNameHit(componentId, point);
			if (hit != null) {
				return hit;
			}
		}

		for (int componentId : BA_ROLE_NAMES) {
			final MinigameHit hit = barbarianRoleHit(componentId, point);
			if (hit != null) {
				return hit;
			}
		}

		return null;
	}

	private MinigameHit barbarianNameHit(int componentId, Point point) {
		final Widget username = client.getWidget(componentId);
		if (username == null
				|| username.getType() != WidgetType.TEXT
				|| username.isHidden()
				|| !containsVisible(username, point)) {
			return null;
		}

		final String playerName = cleanPlayerName(username.getText());
		if (isEmptyPlayerName(playerName) || "none set".equalsIgnoreCase(playerName)) {
			return null;
		}

		return new MinigameHit(playerName, username.getBounds());
	}

	private MinigameHit barbarianRoleHit(int componentId, Point point) {
		final Widget role = client.getWidget(componentId);
		if (role == null
				|| role.getType() != WidgetType.TEXT
				|| role.isHidden()
				|| !containsVisible(role, point)) {
			return null;
		}

		final String playerName = barbarianRolePlayer(role.getText());
		if (isEmptyPlayerName(playerName)) {
			return null;
		}

		return new MinigameHit(playerName, role.getBounds());
	}

	private static boolean containsVisible(Widget widget, Point point) {
		final Rectangle bounds = widget.getBounds();
		return bounds != null && bounds.contains(point);
	}

	private void moveProfileToTop(MinigameHit hit, Point anchorPoint) {
		final MenuEntry[] entries = client.getMenu().getMenuEntries();
		if (entries.length > 0 && isProfileEntry(entries[entries.length - 1], hit.playerName)) {
			final String playerName = hit.playerName;
			entries[entries.length - 1].onClick(entry -> openProfile(playerName, anchorPoint));
			return;
		}

		final String target = profileMenuTarget(hit.playerName);
		removeProfileMenu(hit.playerName);
		addProfileMenu(hit.playerName, target, -1, anchorPoint);
	}

	private void addProfileMenu(String playerName, String target, int index, Point anchorPoint) {
		final String menuTarget = target != null && !target.trim().isEmpty()
				? target
				: playerName;

		client.createMenuEntry(index)
				.setOption(MENU_OPEN_PROFILE)
				.setTarget(menuTarget)
				.setType(MenuAction.RUNELITE)
				.onClick(entry -> openProfile(playerName, anchorPoint));
	}

	private void removeProfileMenu(String playerName) {
		final MenuEntry[] entries = client.getMenu().getMenuEntries();
		int retained = 0;

		for (MenuEntry entry : entries) {
			if (!isProfileEntry(entry, playerName)) {
				retained++;
			}
		}

		if (retained == entries.length) {
			return;
		}

		final MenuEntry[] updated = new MenuEntry[retained];
		int index = 0;
		for (MenuEntry entry : entries) {
			if (!isProfileEntry(entry, playerName)) {
				updated[index++] = entry;
			}
		}

		client.getMenu().setMenuEntries(updated);
	}

	private static boolean isProfileEntry(MenuEntry entry, String playerName) {
		return entry != null && MENU_OPEN_PROFILE.equals(entry.getOption())
				&& playerName.equalsIgnoreCase(cleanPlayerName(entry.getTarget()));
	}

	private String profileMenuTarget(String playerName) {
		for (MenuEntry entry : client.getMenu().getMenuEntries()) {
			if (isProfileEntry(entry, playerName)) {
				return entry.getTarget();
			}
		}

		return playerName;
	}

	private void openProfile(String playerName, Point anchorPoint) {
		quickProfileController.openPlayer(playerName, anchorPoint);
	}

	private Point currentMousePoint() {
		final net.runelite.api.Point canvasPoint = client.getMouseCanvasPosition();

		return canvasPoint != null
				? new Point(canvasPoint.getX(), canvasPoint.getY())
				: null;
	}

	private boolean allowsLeftClick() {
		final ChatInteractionMode interactionMode = config.chatInteractionMode();
		return interactionMode != null && interactionMode.allowsLeftClick();
	}

	private boolean allowsRightClick() {
		final ChatInteractionMode interactionMode = config.chatInteractionMode();
		return interactionMode != null && interactionMode.allowsRightClick();
	}

	private static String barbarianRolePlayer(String value) {
		final String text = cleanPlayerName(value);
		final int separator = text.lastIndexOf(':');
		if (separator <= 0 || separator >= text.length() - 1) {
			return "";
		}

		final String role = text.substring(separator + 1).trim();
		if (!isBarbarianRole(role)) {
			return "";
		}

		return cleanPlayerName(text.substring(0, separator));
	}

	private static boolean isBarbarianRole(String value) {
		return "Attacker".equalsIgnoreCase(value)
				|| "Collector".equalsIgnoreCase(value)
				|| "Defender".equalsIgnoreCase(value)
				|| "Healer".equalsIgnoreCase(value);
	}

	private static boolean isEmptyPlayerName(String value) {
		return value == null || value.isEmpty() || "-".equals(value);
	}

	private static String cleanPlayerName(String value) {
		if (value == null) {
			return "";
		}

		return Text.removeTags(value).replace('\u00A0', ' ').trim();
	}

	private static final class MinigameHit {
		private final String playerName;
		private final Rectangle bounds;

		private MinigameHit(String playerName, Rectangle bounds) {
			this.playerName = playerName;
			this.bounds = bounds != null
					? new Rectangle(bounds)
					: null;
		}
	}
}

package com.runetags.input;

import com.runetags.Configurations;
import com.runetags.config.ChatInteractionMode;
import com.runetags.quickprofile.QuickProfileController;

import java.awt.Point;
import java.awt.event.MouseEvent;

import lombok.extern.slf4j.Slf4j;

import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.PostMenuSort;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.util.Text;

/**
 * Adds RuneTags profile actions to player names exposed through RuneScape interfaces.
 */
@Slf4j
public class InterfaceInput extends MouseAdapter {
	private static final String MENU_OPEN_PROFILE = "Open Profile";

	private static final String GROUPING_ADD_IGNORE = "Add ignore ";
	private static final String GROUPING_REMOVE_IGNORE = "Remove ignore ";

	private final Client client;
	private final Configurations config;
	private final QuickProfileController quickProfileController;

	private boolean suppressLeftClick;

	public InterfaceInput(Client client, Configurations config, QuickProfileController quickProfileController) {
		this.client = client;
		this.config = config;
		this.quickProfileController = quickProfileController;
	}

	public void onMenuEntryAdded(MenuEntryAdded event) {
		if (event == null || (event.getType() != MenuAction.CC_OP.getId()
				&& event.getType() != MenuAction.CC_OP_LOW_PRIORITY.getId())) {
			return;
		}

		final String option = event.getOption() != null
				? Text.removeTags(event.getOption())
				: "";
		final int componentId = event.getActionParam1();
		final int groupId = WidgetUtil.componentToInterface(componentId);

		if (componentId == InterfaceID.ChatchannelSetup.LIST) {
			if (allowsRightClick() && "Not ranked".equals(option)) {
				addProfileEntry(event, 1);
			}

			return;
		}

		if (componentId == InterfaceID.Grouping.PLAYERLIST) {
			if (isGroupOption(option)) {
				final String playerName = groupingPlayerName(option);
				if (!playerName.isEmpty()) {
					addProfileEntry(event, playerName, -2);
				}
			}

			return;
		}

		if (!isPlayerEntry(groupId, componentId, option)) {
			return;
		}

		addProfileEntry(event, -2);
	}

	public void onPostMenuSort(PostMenuSort event) {
		if (client.isMenuOpen() || !allowsLeftClick()) {
			return;
		}

		final Point point = currentMousePoint();
		final ChatChannelHit chatChannelHit = chatChannelSetup(point);
		if (chatChannelHit != null) {
			moveProfileToTop(chatChannelHit.playerName, point);
			return;
		}

		final Widget clanMember = clanMemberList(point);
		if (clanMember == null) {
			return;
		}

		final String playerName = cleanPlayerName(clanMember.getText());
		if (!playerName.isEmpty()) {
			moveProfileToTop(playerName, point);
		}
	}

	public void onMenuOpened(MenuOpened event) {
		final Point point = currentMousePoint();
		final ChatChannelHit chatChannelHit = chatChannelSetup(point);
		if (chatChannelHit != null) {
			prepareOpenedMenu(chatChannelHit.playerName, point);
			return;
		}

		final Widget clanMember = clanMemberList(point);
		if (clanMember == null) {
			return;
		}

		final String playerName = cleanPlayerName(clanMember.getText());
		if (!playerName.isEmpty()) {
			prepareOpenedMenu(playerName, point);
		}
	}

	@Override
	public MouseEvent mousePressed(MouseEvent event) {
		suppressLeftClick = false;

		if (event == null || event.getButton() != MouseEvent.BUTTON1 || client.isMenuOpen() || !allowsLeftClick()) {
			return event;
		}

		final ChatChannelHit chatChannelHit = chatChannelSetup(event.getPoint());
		if (chatChannelHit != null) {
			suppressLeftClick = true;
			openProfile(chatChannelHit.playerName, event.getPoint());
			event.consume();
			return event;
		}

		final Widget clanMember = clanMemberList(event.getPoint());
		if (clanMember != null) {
			final String playerName = cleanPlayerName(clanMember.getText());
			if (!playerName.isEmpty()) {
				suppressLeftClick = true;
				openProfile(playerName, event.getPoint());
				event.consume();
			}
		}

		return event;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent event) {
		if (event != null && event.getButton() == MouseEvent.BUTTON1 && suppressLeftClick) {
			event.consume();
		}

		return event;
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent event) {
		if (event != null && event.getButton() == MouseEvent.BUTTON1 && suppressLeftClick) {
			suppressLeftClick = false;
			event.consume();
		}

		return event;
	}

	private void addProfileEntry(MenuEntryAdded event, int index) {
		client.createMenuEntry(index)
				.setOption(MENU_OPEN_PROFILE)
				.setTarget(event.getTarget())
				.setType(MenuAction.RUNELITE)
				.setIdentifier(event.getIdentifier())
				.onClick(entry -> openProfile(entry.getTarget()));
	}

	private void addProfileEntry(MenuEntryAdded event, String playerName, int index) {
		client.createMenuEntry(index)
				.setOption(MENU_OPEN_PROFILE)
				.setTarget(playerName)
				.setType(MenuAction.RUNELITE)
				.setIdentifier(event.getIdentifier())
				.onClick(entry -> openProfile(playerName));
	}

	private void addProfileEntry(String playerName, String target, Point anchorPoint, int index) {
		client.createMenuEntry(index)
				.setOption(MENU_OPEN_PROFILE)
				.setTarget(target)
				.setType(MenuAction.RUNELITE)
				.onClick(entry -> openProfile(playerName, anchorPoint));
	}

	private void moveProfileToTop(String playerName, Point anchorPoint) {
		final String target = profileMenuTarget(playerName);
		removeProfileEntry(playerName);
		addProfileEntry(playerName, target, anchorPoint, -1);
	}

	private void prepareOpenedMenu(String playerName, Point anchorPoint) {
		final String target = profileMenuTarget(playerName);
		removeProfileEntry(playerName);
		if (allowsRightClick()) {
			addProfileEntry(playerName, target, anchorPoint, 1);
		}
	}

	private void removeProfileEntry(String playerName) {
		final MenuEntry[] entries = client.getMenu().getMenuEntries();
		int retained = 0;

		for (MenuEntry entry : entries) {
			if (!isProfileEntry(entry, playerName)) {
				retained++;
			}
		}

		if (retained == entries.length) {
			return;
		}

		final MenuEntry[] updated = new MenuEntry[retained];
		int index = 0;
		for (MenuEntry entry : entries) {
			if (!isProfileEntry(entry, playerName)) {
				updated[index++] = entry;
			}
		}

		client.getMenu().setMenuEntries(updated);
	}

	private static boolean isProfileEntry(MenuEntry entry, String playerName) {
		return entry != null && MENU_OPEN_PROFILE.equals(entry.getOption())
				&& playerName.equalsIgnoreCase(cleanPlayerName(entry.getTarget()));
	}

	private String profileMenuTarget(String playerName) {
		for (MenuEntry entry : client.getMenu().getMenuEntries()) {
			if (isProfileEntry(entry, playerName)) {
				return entry.getTarget();
			}
		}

		return playerName;
	}

	private ChatChannelHit chatChannelSetup(Point point) {
		if (point == null) {
			return null;
		}

		final Widget list = client.getWidget(InterfaceID.ChatchannelSetup.LIST);
		if (list == null || list.isSelfHidden()) {
			return null;
		}

		final Widget[] children = list.getDynamicChildren();
		if (children == null) {
			return null;
		}

		for (int i = 0; i + 2 < children.length; i += 4) {
			final Widget rank = children[i + 1];
			final Widget username = children[i + 2];
			if (username == null || username.getType() != WidgetType.TEXT || username.isSelfHidden()) {
				continue;
			}

			final String playerName = cleanPlayerName(username.getText());
			if (playerName.isEmpty()) {
				continue;
			}

			if (username.getBounds().contains(point)) {
				return new ChatChannelHit(playerName);
			}

			if (rank != null && rank.getType() == WidgetType.TEXT && !rank.isSelfHidden()
					&& rank.getBounds().contains(point) && isRankOption(cleanPlayerName(rank.getText()))) {
				return new ChatChannelHit(playerName);
			}
		}

		return null;
	}

	private Widget clanMemberList(Point point) {
		if (point == null) {
			return null;
		}

		final Widget nameList = client.getWidget(InterfaceID.ClansMembers.NAME);
		if (nameList == null || nameList.isSelfHidden()) {
			return null;
		}

		final Widget[] children = nameList.getDynamicChildren();
		if (children == null) {
			return null;
		}

		for (int i = 1; i < children.length; i += 3) {
			final Widget username = children[i];
			if (username == null || username.getType() != WidgetType.TEXT || username.isSelfHidden()
					|| !username.getBounds().contains(point)) {
				continue;
			}

			final String playerName = cleanPlayerName(username.getText());
			if (!playerName.isEmpty()) {
				return username;
			}
		}

		return null;
	}

	private static boolean isPlayerEntry(int groupId, int componentId, String option) {
		if (groupId == InterfaceID.FRIENDS) {
			return "Delete".equals(option);
		}

		if (groupId == InterfaceID.CHATCHANNEL_CURRENT) {
			return isFriendOption(option);
		}

		if (groupId == InterfaceID.IGNORE) {
			return "Delete".equals(option);
		}

		if (componentId == InterfaceID.ClansSidepanel.PLAYERLIST
				|| componentId == InterfaceID.ClansGuestSidepanel.PLAYERLIST) {
			return isFriendOption(option);
		}

		if (groupId == InterfaceID.GIM_SIDEPANEL) {
			return isIronOption(option);
		}

		return false;
	}

	private static boolean isFriendOption(String option) {
		return "Add ignore".equals(option) || "Remove friend".equals(option);
	}

	private static boolean isIronOption(String option) {
		return "Add friend".equals(option) || "Remove friend".equals(option) || "Remove ignore".equals(option);
	}

	private static boolean isGroupOption(String option) {
		return option.startsWith(GROUPING_ADD_IGNORE) || option.startsWith(GROUPING_REMOVE_IGNORE);
	}

	private static boolean isRankOption(String option) {
		return "Not ranked".equals(option)
				|| "Recruit".equals(option)
				|| "Corporal".equals(option)
				|| "Sergeant".equals(option)
				|| "Lieutenant".equals(option)
				|| "Captain".equals(option)
				|| "General".equals(option);
	}

	private static String groupingPlayerName(String option) {
		if (option.startsWith(GROUPING_ADD_IGNORE)) {
			return cleanPlayerName(option.substring(GROUPING_ADD_IGNORE.length()));
		}

		if (option.startsWith(GROUPING_REMOVE_IGNORE)) {
			return cleanPlayerName(option.substring(GROUPING_REMOVE_IGNORE.length()));
		}

		return "";
	}

	private Point currentMousePoint() {
		final net.runelite.api.Point canvasPoint = client.getMouseCanvasPosition();

		return canvasPoint != null
				? new Point(canvasPoint.getX(), canvasPoint.getY())
				: null;
	}

	private boolean allowsLeftClick() {
		final ChatInteractionMode interactionMode = config.chatInteractionMode();
		return interactionMode != null && interactionMode.allowsLeftClick();
	}

	private boolean allowsRightClick() {
		final ChatInteractionMode interactionMode = config.chatInteractionMode();
		return interactionMode != null && interactionMode.allowsRightClick();
	}

	private void openProfile(String target) {
		openProfile(target, currentMousePoint());
	}

	private void openProfile(String target, Point anchorPoint) {
		final String playerName = cleanPlayerName(target);
		if (playerName.isEmpty()) {
			return;
		}

		quickProfileController.openPlayer(playerName, anchorPoint);
	}

	private static final class ChatChannelHit {
		private final String playerName;

		private ChatChannelHit(String playerName) {
			this.playerName = playerName;
		}
	}

	private static String cleanPlayerName(String value) {
		if (value == null) {
			return "";
		}

		return Text.removeTags(value).replace('\u00A0', ' ').trim();
	}
}

package com.runetags.input;

import com.runetags.Configurations;
import com.runetags.chat.ChatHitboxRegistry;
import com.runetags.chat.ReferenceHitbox;
import com.runetags.config.ChatInteractionMode;
import com.runetags.quickprofile.QuickProfileController;
import com.runetags.reference.PlayerReference;
import com.runetags.reference.ReferenceType;
import com.runetags.suggestion.SuggestionService;

import java.awt.Point;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.util.Arrays;
import java.util.Optional;

import lombok.extern.slf4j.Slf4j;

import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

@Slf4j
public class InputListener extends MouseAdapter implements KeyListener {
	private static final String MENU_OPEN_PROFILE = "Open Profile";
	private static final String MENU_TARGET = "Target";
	private static final String MENU_LOOKUP = "Lookup";

	/*
	 * RuneScape's native Report entry identifies a real chat-sender context menu.
	 */
	private static final String NATIVE_MENU_REPORT = "Report";

	private final Client client;
	private final Configurations config;
	private final ChatHitboxRegistry registry;
	private final QuickProfileController quickProfileController;
	private final SuggestionService suggestionService;

	private boolean suppressCurrentLeftClick;
	private boolean suppressCurrentEscape;
	private boolean suppressCurrentSuggestionTyped;

	public InputListener(
			Client client,
			Configurations config,
			ChatHitboxRegistry registry,
			QuickProfileController quickProfileController,
			SuggestionService suggestionService) {
		this.client = client;
		this.config = config;
		this.registry = registry;
		this.quickProfileController = quickProfileController;
		this.suggestionService = suggestionService;
	}

	@Override
	public MouseEvent mousePressed(MouseEvent event) {
		// Close any open QuickCard before the context menu becomes active.
		if (event.getButton() == MouseEvent.BUTTON3) {
			if (quickProfileController.isOpen()) {
				quickProfileController.close();
			}

			return super.mousePressed(event);
		}

		if (event.getButton() != MouseEvent.BUTTON1) {
			return super.mousePressed(event);
		}

		/*
		 * An open RuneScape menu owns the click. Do not route it to an underlying
		 * RuneTags hitbox, and do not consume it because RuneScape must execute the
		 * selected menu action.
		 */
		if (client.isMenuOpen()) {
			suppressCurrentLeftClick = false;
			return super.mousePressed(event);
		}

		final Point point = event.getPoint();
		if (quickProfileController.isOpen()) {
			final String tagToRemove = quickProfileController.tagRemovalAt(point);
			if (tagToRemove != null) {
				quickProfileController.removeTag(tagToRemove);
				suppressCurrentLeftClick = true;
				event.consume();
				return event;
			}

			if (quickProfileController.isCloseButton(point)) {
				quickProfileController.close();
				suppressCurrentLeftClick = true;
				event.consume();
				return event;
			}

			if (quickProfileController.isTagButton(point)) {
				quickProfileController.editTags();
				suppressCurrentLeftClick = true;
				event.consume();
				return event;
			}

			if (quickProfileController.isNoteButton(point)) {
				quickProfileController.editNote();
				suppressCurrentLeftClick = true;
				event.consume();
				return event;
			}

			if (quickProfileController.isFavoriteButton(point)) {
				quickProfileController.toggleFavorite();
				suppressCurrentLeftClick = true;
				event.consume();
				return event;
			}

			if (quickProfileController.isTargetButton(point)) {
				quickProfileController.target();
				suppressCurrentLeftClick = true;
				event.consume();
				return event;
			}

			if (quickProfileController.isLookupButton(point)) {
				quickProfileController.lookup();
				suppressCurrentLeftClick = true;
				event.consume();
				return event;
			}

			if (quickProfileController.isClanLink(point)) {
				quickProfileController.lookupClan();
				suppressCurrentLeftClick = true;
				event.consume();
				return event;
			}

			if (quickProfileController.isReportCaseLink(point)) {
				quickProfileController.openReportCase();
				suppressCurrentLeftClick = true;
				event.consume();
				return event;
			}

			if (quickProfileController.isInsideCard(point)) {
				suppressCurrentLeftClick = true;
				event.consume();
				return event;
			}
		}

		final ChatInteractionMode interactionMode = config.chatInteractionMode();

		// LEFT_CLICK and BOTH permit direct QuickCard activation; RIGHT_CLICK leaves it untouched.
		if (interactionMode != null && interactionMode.allowsLeftClick()) {
			final Optional<ReferenceHitbox> hit = registry.find(point);
			if (hit.isPresent()) {
				quickProfileController.open(hit.get().getReference(), point);
				suppressCurrentLeftClick = true;
				event.consume();
				return event;
			}
		}

		// Clicking outside an open QuickCard closes it.
		if (quickProfileController.isOpen()) {
			quickProfileController.close();
		}

		return super.mousePressed(event);
	}

	/*
	 * Augment RuneScape context menus with RuneTags actions.
	 *
	 * Native sender menus retain their normal actions. MENTION and TAG references
	 * use the RuneTags Open Profile / Target / Lookup menu when right-click
	 * interaction is enabled.
	 */
	public void onMenuOpened(MenuOpened event) {
		// Menu ownership takes priority over an open QuickCard.
		if (quickProfileController.isOpen()) {
			quickProfileController.close();
		}

		final ChatInteractionMode interactionMode = config.chatInteractionMode();

		// RIGHT_CLICK and BOTH permit RuneTags menu actions; LEFT_CLICK preserves the native menu.
		if (interactionMode == null || !interactionMode.allowsRightClick()) {
			return;
		}

		final net.runelite.api.Point mouseCanvasPoint = client.getMouseCanvasPosition();
		if (mouseCanvasPoint == null) {
			return;
		}

		final Point mousePoint = new Point(mouseCanvasPoint.getX(), mouseCanvasPoint.getY());

		/*
		 * RuneTags references take priority over native sender menus.
		 *
		 * A mention inside another player's chat message belongs to the
		 * referenced player, not the sender of the message.
		 */
		final Optional<ReferenceHitbox> hit = registry.find(mousePoint);
		if (hit.isPresent() && handleReferenceMenu(hit.get(), mousePoint)) {
			return;
		}

		// Fall back to RuneScape's native sender menu when no RuneTags reference owns the click.
		if (augmentNativeSenderMenu(event, mousePoint)) {
			return;
		}
	}

	private boolean handleReferenceMenu(ReferenceHitbox referenceHitbox, Point mousePoint) {
		final PlayerReference reference = referenceHitbox.getReference();
		if (reference == null) {
			return false;
		}

		// Sender references stay with RuneScape's native menu.
		if (reference.getType() == ReferenceType.SENDER) {
			return false;
		}

		// Only mentions and tags receive RuneTags menus.
		if (reference.getType() != ReferenceType.MENTION && reference.getType() != ReferenceType.TAG) {
			return false;
		}
		suppressNativeMenu(nativeSenderName());
		final Point anchorPoint = new Point(mousePoint);
		final String target = menuTarget(reference);
		client.createMenuEntry(-1)
				.setOption(MENU_OPEN_PROFILE)
				.setTarget(target)
				.setType(MenuAction.RUNELITE)
				.onClick(entry -> quickProfileController.open(reference, anchorPoint));
		if (config.targetPlayerOption() && quickProfileController.canTarget(reference)) {
			client.createMenuEntry(-2).setOption(MENU_TARGET).setTarget(target).setType(MenuAction.RUNELITE)
					.onClick(entry -> quickProfileController.target(reference));
		}

		client.createMenuEntry(-3).setOption(MENU_LOOKUP).setTarget(target).setType(MenuAction.RUNELITE)
				.onClick(entry -> quickProfileController.lookup(reference));
		return true;
	}

	/*
	 * Remove the native sender actions created for the chat message author.
	 *
	 * A RuneTags mention/tag belongs to the referenced player, not the player
	 * who sent the message containing the reference.
	 */
	private String nativeSenderName() {
		final MenuEntry[] entries = client.getMenuEntries();
		for (MenuEntry entry : entries) {
			if (isNativeChatReportMenuEntry(entry)) {
				return cleanPlayerName(entry.getTarget());
			}
		}

		return "";
	}

	private boolean isNativePlayerMenu(MenuEntry entry, String senderName) {
		if (entry == null) {
			return false;
		}

		final String target = cleanPlayerName(entry.getTarget());
		if (!target.equalsIgnoreCase(senderName)) {
			return false;
		}

		final String option = entry.getOption();
		return "WALK HERE".equalsIgnoreCase(option)
				|| "ADD FRIEND".equalsIgnoreCase(option)
				|| "ADD IGNORE".equalsIgnoreCase(option)
				|| "MESSAGE".equalsIgnoreCase(option)
				|| "LOOKUP".equalsIgnoreCase(option)
				|| "WOM LOOKUP".equalsIgnoreCase(option)
				|| "TCG TRADE REQUEST".equalsIgnoreCase(option)
				|| "REPORT".equalsIgnoreCase(option)
				|| "COPY TO CLIPBOARD".equalsIgnoreCase(option);
	}

	private boolean isNativeMovementMenu(MenuEntry entry) {
		if (entry == null) {
			return false;
		}

		return "WALK HERE".equalsIgnoreCase(entry.getOption());
	}

	private void suppressNativeMenu(String senderName) {
		final MenuEntry[] entries = client.getMenuEntries();
		if (entries == null || entries.length == 0) {
			return;
		}

		final boolean hasSender = senderName != null && !senderName.isEmpty();
		client.setMenuEntries(
				Arrays.stream(entries).filter(entry -> !hasSender || !isNativePlayerMenu(entry, senderName))
						.filter(entry -> !isNativeMovementMenu(entry)).toArray(MenuEntry[]::new));
	}

	@Override
	public void keyPressed(KeyEvent event) {
	// Hotkey or Escape pressing functions
		if (event == null) {
			return;
		}

		if (!quickProfileController.isEditingNote()
				&& !quickProfileController.isEditingTag()
				&& suggestionService != null
				&& suggestionService.handleKeyPressed(event)) {
			if (event.getKeyCode() == KeyEvent.VK_ESCAPE) {
				suppressCurrentEscape = true;
			}

			if (event.getKeyChar() != KeyEvent.CHAR_UNDEFINED) {
				suppressCurrentSuggestionTyped = true;
			}

			return;
		}

		if (event.getKeyCode() != KeyEvent.VK_ESCAPE) {
			return;
		}

		/*
		 * While the Note editor is open, RuneLite's ChatboxTextInput owns ESC.
		 * Let it close normally so QuickProfileController can restore the profile.
		 */
		if (quickProfileController.isEditingNote() || quickProfileController.isEditingTag()) {
			return;
		}

		/*
		 * When a Quick Profile is open, consume ESC after closing the card so
		 * RuneScape does not process the same key press.
		 */
		if (quickProfileController.isOpen()) {
			quickProfileController.close();
			suppressCurrentEscape = true;
			event.consume();
		}
	}

	@Override
	public void keyReleased(KeyEvent event) {
		if (event == null) {
			return;
		}

		if (suppressCurrentSuggestionTyped) {
			event.consume();
		}

		if (event.getKeyCode() == KeyEvent.VK_ESCAPE && suppressCurrentEscape) {
			event.consume();
			suppressCurrentEscape = false;
		}
	}

	@Override
	public void keyTyped(KeyEvent event) {
		if (event == null) {
			return;
		}

		if (suppressCurrentSuggestionTyped) {
			event.consume();
			suppressCurrentSuggestionTyped = false;
		}
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent event) {
		if (event.getButton() == MouseEvent.BUTTON1 && suppressCurrentLeftClick) {
			event.consume();
		}

		return super.mouseReleased(event);
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent event) {
		if (event.getButton() == MouseEvent.BUTTON1 && suppressCurrentLeftClick) {
			event.consume();
			suppressCurrentLeftClick = false;
			return event;
		}

		return super.mouseClicked(event);
	}

	/*
	 * Augment RuneScape sender menus with RuneTags actions when the cursor
	 * is over a native chat sender entry.
	 *
	 * RuneTags-owned mentions and tags are handled separately and replace
	 * conflicting sender actions with their own player context menu.
	 */
	private boolean augmentNativeSenderMenu(MenuOpened event, Point anchorPoint) {
		if (event == null || event.getMenuEntries() == null) {
			return false;
		}

		final MenuEntry[] menuEntries = event.getMenuEntries();
		for (int i = 0; i < menuEntries.length; i++) {
			final MenuEntry entry = menuEntries[i];
			if (!isNativeChatReportMenuEntry(entry)) {
				continue;
			}

			final String playerName = cleanPlayerName(entry.getTarget());
			if (playerName.isEmpty()) {
				return false;
			}

			// Preserve native target markup for display and use the clean name for identity.
			final String nativeTarget = entry.getTarget() != null
					? entry.getTarget()
					: playerName;

			// Retain the right-click point for Quick Profile anchoring.
			final Point profileAnchor = anchorPoint != null
					? new Point(anchorPoint)
					: null;

			/*
			 * Reuse a RuneTags SENDER reference when available to preserve semantic state
			 * such as ChatMessageType. If sender hitboxes are disabled, fall back to a
			 * lightweight reference built from RuneScape's native username.
			 */
			final PlayerReference senderReference = nativeSenderReference(playerName, anchorPoint);

			/*
			 * RuneScape's backing menu order is the reverse of its visual order.
			 * Inserting immediately after Report therefore places Open Profile directly
			 * above Report without moving the other native actions.
			 */
			client.createMenuEntry(i + 1)
					.setOption(MENU_OPEN_PROFILE).setTarget(nativeTarget) .setType(MenuAction.RUNELITE)
					.onClick(menuEntry -> quickProfileController.open(senderReference, profileAnchor));

			// Target stays at the top of the sender menu and resolves when selected.
			if (config.targetPlayerOption() && quickProfileController.canTarget(senderReference)) {
				client.createMenuEntry(-1).setOption(ColorUtil.prependColorTag(MENU_TARGET, config.targetColor()))
						.setTarget(nativeTarget).setType(MenuAction.RUNELITE)
						.onClick(menuEntry -> quickProfileController.target(senderReference));
			}
			return true;
		}
		return false;
	}

	/*
	 * Resolve the PlayerReference used by native sender-menu actions.
	 *
	 * Reuse a SENDER hitbox reference when available so semantic data such as the
	 * originating chat type is retained; otherwise build a minimal reference from
	 * RuneScape's native username.
	 */
	private PlayerReference nativeSenderReference(String playerName, Point mousePoint) {
		if (mousePoint != null) {
			final Optional<ReferenceHitbox> hit = registry.find(mousePoint);
			if (hit.isPresent()) {
				final PlayerReference reference = hit.get().getReference();
				if (reference != null && reference.getType() == ReferenceType.SENDER) {
					return reference;
				}
			}
		}

		return PlayerReference.builder().rawText(playerName).normalizedToken(playerName).lookupName(playerName)
				.startOffset(0).endOffset(playerName.length()).type(ReferenceType.SENDER).locallyResolved(false)
				.identity(null).chatType(null).build();
	}

	/*
	 * Identify RuneScape's native Report action only when
	 * it belongs to a supported player-chat surface.
	 *
	 * RuneTags never creates Report.
	 */
	private boolean isNativeChatReportMenuEntry(MenuEntry entry) {
		return entry != null && entry.getOption() != null && NATIVE_MENU_REPORT.equals(
				Text.removeTags(entry.getOption())) && isSupportedChatMessageEntry(entry.getParam1());
	}

	/*
	 * Confirm that a native menu entry belongs to either the normal chatbox
	 * or split-private-chat surface.
	 */
	private boolean isSupportedChatMessageEntry(int packedWidgetId) {
		final int groupId = WidgetUtil.componentToInterface(packedWidgetId);
		if (groupId == InterfaceID.CHATBOX) {
			return isChatboxMessageEntry(packedWidgetId);
		}

		if (groupId == InterfaceID.PM_CHAT) {
			return isSplitPrivateMessageEntry(packedWidgetId);
		}

		return false;
	}

	/*
	 * Confirm that a native menu entry belongs to a normal chatbox message row.
	 */
	private boolean isChatboxMessageEntry(int packedWidgetId) {
		final int groupId = WidgetUtil.componentToInterface(packedWidgetId);
		final int childId = WidgetUtil.componentToId(packedWidgetId);
		if (groupId != InterfaceID.CHATBOX) {
			return false;
		}

		final Widget widget = client.getWidget(groupId, childId);
		if (widget == null) {
			return false;
		}

		final Widget parent = widget.getParent();
		return parent != null && parent.getId() == InterfaceID.Chatbox.SCROLLAREA;
	}

	/*
	 * Confirm that a native menu entry belongs to one of RuneScape's
	 * split-private-chat message components.
	 */
	private boolean isSplitPrivateMessageEntry(int packedWidgetId) {
		final int groupId = WidgetUtil.componentToInterface(packedWidgetId);
		if (groupId != InterfaceID.PM_CHAT) {
			return false;
		}

		final int childId = WidgetUtil.componentToId(packedWidgetId);
		final Widget widget = client.getWidget(groupId, childId);
		if (widget == null) {
			return false;
		}

		final Widget container = client.getWidget(InterfaceID.PmChat.CONTAINER);
		if (container == null) {
			return false;
		}

		final Widget parent = widget.getParent();
		return widget == container || parent == container || isChildOf(widget, container);
	}

	private static boolean isChildOf(Widget widget, Widget ancestor) {
		if (widget == null || ancestor == null) {
			return false;
		}

		Widget current = widget.getParent();
		while (current != null) {
			if (current == ancestor || current.getId() == ancestor.getId()) {
				return true;
			}

			current = current.getParent();
		}

		return false;
	}

	/*
	 * Convert RuneScape's menu target into a plain player name suitable for
	 * RuneTags identity resolution.
	 */
	private static String cleanPlayerName(String value) {
		if (value == null) {
			return "";
		}

		return Text.removeTags(value).replace('\u00A0', ' ').trim();
	}

	private static String menuTarget(PlayerReference reference) {
		if (reference == null) {
			return "";
		}

		if (reference.getLookupName() != null && !reference.getLookupName().trim().isEmpty()) {
			return reference.getLookupName().trim();
		}

		if (reference.getRawText() != null && !reference.getRawText().trim().isEmpty()) {
			return reference.getRawText().trim();
		}

		return "";
	}
}

package com.runetags.chat;

import com.runetags.mention.LocalMentionMatch;
import com.runetags.reference.PlayerReference;

import java.time.Instant;
import java.util.Collections;
import java.util.List;

import lombok.Builder;
import lombok.Value;

import net.runelite.api.ChatMessageType;

@Value
@Builder
public class TaggedMessage {
	long id;
	ChatMessageType type;

	String originalSender;
	String canonicalSender;
	String originalMessage;

	Instant timestamp;

	@Builder.Default
	List<PlayerReference> references = Collections.emptyList();

	@Builder.Default
	LocalMentionMatch localMentionMatch = LocalMentionMatch.none();
}

package com.runetags.chat;

import com.runetags.reference.PlayerReference;

import java.awt.Rectangle;

import lombok.Value;

@Value
public class ReferenceHitbox {
	long messageId;
	Rectangle bounds;
	PlayerReference reference;
	ReferenceLayoutService.Surface surface;

	public boolean contains(java.awt.Point point) {
		return bounds != null && point != null && bounds.contains(point);
	}
}

package com.runetags.chat;

import com.runetags.player.PlayerDirectory;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Predicate;

import net.runelite.api.ChatLineBuffer;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.MessageNode;
import net.runelite.client.util.Text;

/**
 * Rebuilds RuneTags semantic chat state from RuneScape's existing native buffers.
 *
 * Bootstrap restores TaggedMessage state and authoritative account observations
 * without replaying events, sending notifications, rewriting chat, or creating hitboxes.
 */
public class NativeBootstrapService {
	private final Client client;
	private final PlayerDirectory playerDirectory;
	private final ChatProcessor chatProcessor;
	private final TaggedMessageRepository repository;

	public NativeBootstrapService(
			Client client,
			PlayerDirectory playerDirectory,
			ChatProcessor chatProcessor,
			TaggedMessageRepository repository) {
		this.client = client;
		this.playerDirectory = playerDirectory;
		this.chatProcessor = chatProcessor;
		this.repository = repository;
	}

	/**
	 * Rebuild RuneTags semantic chat state from the current native buffers.
	 *
	 * @param startingMessageId      current RuneTags message ID
	 * @param localPlayerName        current local player's display name
	 * @param supportedTypePredicate RuneTags supported-chat-type predicate
	 * @return the newest RuneTags message ID assigned by this bootstrap
	 */
	public long bootstrap(
			long startingMessageId, String localPlayerName, Predicate<ChatMessageType> supportedTypePredicate) {
		if (supportedTypePredicate == null) {
			return startingMessageId;
		}

		final Map<Integer, ChatLineBuffer> chatLineMap = client.getChatLineMap();
		if (chatLineMap == null || chatLineMap.isEmpty()) {
			return startingMessageId;
		}

		/*
		 * Deduplicate native messages by MessageNode ID before rebuilding semantic state.
		 */
		final Map<Integer, MessageNode> uniqueNodes = new LinkedHashMap<>();

		for (ChatLineBuffer buffer : chatLineMap.values()) {
			if (buffer == null || buffer.getLines() == null) {
				continue;
			}

			for (MessageNode node : buffer.getLines()) {
				if (node == null || node.getType() == null || !supportedTypePredicate.test(node.getType())) {
					continue;
				}

				uniqueNodes.putIfAbsent(node.getId(), node);
			}
		}

		if (uniqueNodes.isEmpty()) {
			return startingMessageId;
		}

		final List<MessageNode> nodes = new ArrayList<>(uniqueNodes.values());

		/*
		 * ChatLineBuffer arrays are newest-first.
		 *
		 * RuneTags' repository is chronological oldest -> newest, so recover
		 * native chronology before processing.
		 *
		 * Native timestamps have second-level precision. MessageNode ID gives
		 * us a deterministic tie-breaker for messages created in the same
		 * second.
		 */
		nodes.sort(Comparator.comparingInt(MessageNode::getTimestamp).thenComparingInt(MessageNode::getId));

		long nextMessageId = startingMessageId;

		for (MessageNode node : nodes) {
			final ChatMessageType type = node.getType();
			final String rawName = node.getName();

			/*
			 * PRIVATECHATOUT identifies the recipient and does not update authoritative
			 * sender-account observations.
			 */
			if (playerDirectory != null && rawName != null && !rawName.trim().isEmpty()
					&& type != ChatMessageType.PRIVATECHATOUT) {
				playerDirectory.observeAccountType(rawName);
			}

			/*
			 * Prefer the native message value and fall back to retained formatted text
			 * when no current value exists.
			 */
			String rawMessage = node.getValue();
			if (rawMessage == null) {
				rawMessage = node.getRuneLiteFormatMessage();
			}
			if (rawMessage == null) {
				rawMessage = "";
			}

			final String semanticMessage = ChatText.toSemanticPlain(rawMessage);
			final String canonicalSender = rawName != null
					? Text.removeTags(rawName)
					: null;
			final TaggedMessage taggedMessage = chatProcessor.process(
				++nextMessageId, type, canonicalSender, semanticMessage, localPlayerName);

			repository.add(taggedMessage);
		}

		return nextMessageId;
	}
}

package com.runetags.chat;

import com.runetags.Configurations;
import com.runetags.config.MentionFont;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

import net.runelite.api.Client;
import net.runelite.api.FontID;
import net.runelite.api.FontTypeFace;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/**
 * Coordinates native row allocation and post-construction mention-font synchronization.
 *
 * Scripts 203 and 4483 share a trailing eleven-value construction payload:
 *
 * size - 10 -> line Widget ID
 * size - 9  -> parent Widget ID
 * size - 8  -> right boundary
 * size - 7  -> left boundary
 * size - 6  -> native vertical value
 *
 * RuneTags measures base and selected wrapping, adjusts only the native vertical
 * allocation, then applies FontId after clientscript reconstruction.
 */
public class FontLayoutService {
	private static final int CHAT_BODY_SCRIPT = 203;
	private static final int CLAN_BODY_SCRIPT = 4483;

	private static final int BODY_GAP = 3;

	private final Client client;
	private final Configurations config;
	private final TaggedMessageRepository repository;
	private final ReferenceLayoutService referenceLayoutService;

	/*
	 * Coalesce supported row reconstructions into one PostClientTick font synchronization.
	 */
	private boolean fontsDirty;

	/*
	 * Cache resolved FontTypeFace values by FontId.
	 */
	private final Map<Integer, FontTypeFace> fontCache = new HashMap<>();

	/*
	 * Semantic occurrences already consumed by the current native reconstruction
	 * batch. This preserves newest-to-newest ownership for repeated sender/body pairs.
	 */
	private final Set<Long> constructedMessageIds = new HashSet<>();

	public FontLayoutService(
			Client client,
			Configurations config,
			TaggedMessageRepository repository,
			ReferenceLayoutService referenceLayoutService) {
		this.client = client;
		this.config = config;
		this.repository = repository;
		this.referenceLayoutService = referenceLayoutService;
	}

	/*
	 * Marks font synchronization pending for the current client tick.
	 */
	public void markFontsDirty() {
		fontsDirty = true;
	}

	/*
	 * Runs one pending font synchronization after clientscript reconstruction.
	 *
	 * @return true when synchronization ran; otherwise false
	 */
	public boolean onPostClientTick() {
		if (!fontsDirty) {
			return false;
		}

		/*
		 * Clear before synchronization so later reconstruction can mark the next pass dirty.
		 */
		fontsDirty = false;

		referenceLayoutService.syncMentionFonts();
		constructedMessageIds.clear();

		return true;
	}

	/*
	 * Intercept only the native row-construction scripts supported by RuneTags.
	 */
	public void onScriptPreFired(ScriptPreFired event) {
		if (event == null || !isSupportedConstructionScript(event.getScriptId())) {
			return;
		}

		if (!fontsDirty) {
			constructedMessageIds.clear();
		}

		/*
		 * Invalidate cached physical row membership before RuneScape rebuilds the
		 * supported chat surface. The next synchronization/layout pass rediscovers
		 * membership while final geometry remains live every render.
		 */
		referenceLayoutService.invalidateRenderedWidgetCaches();

		/*
		 * Supported row reconstruction invalidates RuneTags font ownership and Favorite
		 * sender presentation.
		 */
		markFontsDirty();
		referenceLayoutService.markFavoriteSenderRowsDirty();

		final Object[] objectStack = client.getObjectStack();
		final int objectStackSize = client.getObjectStackSize();

		/*
		 * Use one semantic repository snapshot for the complete construction attempt
		 * so body and message resolution operate on the same retained state.
		 */
		final List<TaggedMessage> messages = repository.snapshot();
		if (messages.isEmpty()) {
			return;
		}

		final String rawBody = findBody(objectStack, objectStackSize, messages);
		if (rawBody == null) {
			return;
		}

		final String semanticBody = ChatText.toSemanticPlain(rawBody);
		if (semanticBody == null || semanticBody.isEmpty()) {
			return;
		}

		/*
		 * Apply mention-font treatment only to TaggedMessages containing a reference
		 * or local-player match.
		 */
		final TaggedMessage taggedMessage = findTaggedMessage(semanticBody, objectStack, objectStackSize, messages);
		if (taggedMessage == null || !hasMentionFontTreatment(taggedMessage)) {
			return;
		}

		final MentionFont mentionFont = config.fontMentions();
		if (mentionFont == null) {
			return;
		}

		final int[] intStack = client.getIntStack();
		final int intStackSize = client.getIntStackSize();

		/*
		 * Both known construction scripts expose the same trailing
		 * eleven-value payload.
		 */
		if (intStack == null || intStackSize < 11 || intStackSize > intStack.length) {
			return;
		}

		final int lineWidgetIndex = intStackSize - 10;
		final int rightBoundaryIndex = intStackSize - 8;
		final int verticalValueIndex = intStackSize - 6;
		final int lineWidgetId = intStack[lineWidgetIndex];
		final int rightBoundary = intStack[rightBoundaryIndex];

		/*
		 * Preserve RuneScape's native vertical value rather than choosing a
		 * surface-specific line height.
		 */
		final int nativeLineHeight = intStack[verticalValueIndex];
		if (nativeLineHeight <= 0) {
			return;
		}

		final Widget lineWidget = client.getWidget(lineWidgetId);
		if (lineWidget == null) {
			return;
		}

		final int currentFontId = lineWidget.getFontId();
		final int baseFontId = currentFontId > 0
				? currentFontId
				: FontID.PLAIN_12;

		final int selectedFontId = MentionFontResolver.fontIdFor(mentionFont, baseFontId);
		if (selectedFontId == baseFontId) {
			return;
		}

		final FontTypeFace baseFont = resolveFont(baseFontId);
		final FontTypeFace selectedFont = resolveFont(selectedFontId);
		if (baseFont == null || selectedFont == null) {
			return;
		}

		final PrefixMeasurement prefix = measurePrefix(event.getScriptId(), baseFont, objectStack, objectStackSize,
				semanticBody, intStack, intStackSize);
		if (prefix == null) {
			return;
		}

		final int bodyX = lineWidget.getOriginalX() + prefix.width + BODY_GAP;
		final int bodyWidth = rightBoundary - bodyX;
		if (bodyWidth <= 0) {
			return;
		}

		/*
		 * Use ReferenceLayoutService's wrapping model for construction compensation.
		 */
		final int baseLines = referenceLayoutService.measureWrappedLineCount(rawBody, baseFont, bodyWidth);
		final int selectedLines = referenceLayoutService.measureWrappedLineCount(rawBody, selectedFont, bodyWidth);
		if (baseLines <= 0 || selectedLines <= 0) {
			return;
		}

		final int desiredHeight = selectedLines * nativeLineHeight;
		final int injectedValue = ceilDiv(desiredHeight, baseLines);
		if (injectedValue <= 0) {
			return;
		}

		/*
		 * Mutate only the pre-construction vertical argument;
		 * RuneScape owns final Widget geometry and positioning.
		 */
		if (intStack[verticalValueIndex] != injectedValue) {
			intStack[verticalValueIndex] = injectedValue;
		}
	}

	private boolean isSupportedConstructionScript(int scriptId) {
		return scriptId == CHAT_BODY_SCRIPT || scriptId == CLAN_BODY_SCRIPT;
	}

	/*
	 * Font treatment belongs only to a message which contains a RuneTags
	 * PlayerReference or matched the local player.
	 *
	 * This mirrors ReferenceLayoutService.applyMentionFont().
	 */
	private boolean hasMentionFontTreatment(TaggedMessage message) {
		if (message == null) {
			return false;
		}

		final boolean hasPlayerReference = message.getReferences() != null && !message.getReferences().isEmpty();
		final boolean hasLocalMention = message.getLocalMentionMatch() != null
				&& message.getLocalMentionMatch().isMatchesLocalPlayer();

		return hasPlayerReference || hasLocalMention;
	}

	/*
	 * Resolve the TaggedMessage represented by this construction call.
	 *
	 * Newest messages are preferred because chat reconstruction is
	 * newest-first and identical body text can legitimately occur multiple
	 * times.
	 *
	 * Player-authored messages require sender/prefix confirmation. Repeated
	 * sender/body pairs are consumed newest-first within one reconstruction batch.
	 */
	private TaggedMessage findTaggedMessage(
			String semanticBody, Object[] objectStack, int objectStackSize, List<TaggedMessage> messages) {
		if (messages == null || messages.isEmpty()) {
			return null;
		}

		TaggedMessage senderlessFallback = null;

		for (int i = messages.size() - 1; i >= 0; i--) {
			final TaggedMessage message = messages.get(i);
			if (message == null || constructedMessageIds.contains(message.getId())
					|| message.getOriginalMessage() == null
					|| !message.getOriginalMessage().equals(semanticBody)) {
				continue;
			}

			final String sender = message.getCanonicalSender();
			if (sender == null || sender.isEmpty()) {
				if (senderlessFallback == null) {
					senderlessFallback = message;
				}
				continue;
			}

			if (prefixContainsSender(objectStack, objectStackSize, semanticBody, sender)) {
				constructedMessageIds.add(message.getId());
				return message;
			}
		}

		if (senderlessFallback != null) {
			constructedMessageIds.add(senderlessFallback.getId());
		}

		return senderlessFallback;
	}

	private boolean prefixContainsSender(Object[] stack, int size, String semanticBody, String sender) {
		if (stack == null || size <= 0 || sender == null || sender.isEmpty()) {
			return false;
		}

		final String comparableSender = comparable(sender);

		final int safeSize = Math.min(size, stack.length);
		for (int i = 0; i < safeSize; i++) {
			final Object value = stack[i];
			if (!(value instanceof String)) {
				continue;
			}

			final String raw = (String) value;
			final String semantic = ChatText.toSemanticPlain(raw);
			if (semantic == null || semantic.equals(semanticBody)) {
				continue;
			}

			final String comparablePrefix = comparable(semantic);
			if (comparablePrefix.contains(comparableSender)) {
				return true;
			}
		}

		return false;
	}

	/*
	 * Locate the rendered body argument on the current script object stack.
	 *
	 * We identify it semantically by matching against RuneTags' retained
	 * TaggedMessageRepository rather than by assuming a fixed object-stack
	 * position.
	 */
	private String findBody(Object[] stack, int size, List<TaggedMessage> messages) {
		if (stack == null || size <= 0 || messages == null || messages.isEmpty()) {
			return null;
		}

		final int safeSize = Math.min(size, stack.length);
		for (int i = safeSize - 1; i >= 0; i--) {
			final Object value = stack[i];
			if (!(value instanceof String)) {
				continue;
			}

			final String raw = (String) value;
			final String semantic = ChatText.toSemanticPlain(raw);
			if (semantic == null || semantic.isEmpty()) {
				continue;
			}

			for (int messageIndex = messages.size() - 1; messageIndex >= 0; messageIndex--) {
				final TaggedMessage message = messages.get(messageIndex);
				if (message == null || message.getOriginalMessage() == null) {
					continue;
				}

				if (message.getOriginalMessage().equals(semantic)) {
					return raw;
				}
			}
		}

		return null;
	}

	/*
	 * Determine the rendered prefix width immediately preceding the body.
	 *
	 * Script 203 supplies one complete prefix String:
	 *
	 * Santa:
	 * [Nerds] Santa:
	 * To Player:
	 *
	 * Script 4483 supplies Clan/Guest-Clan components separately:
	 *
	 * [Clan]
	 * Santa:
	 * body
	 *
	 * plus the small account/channel decoration represented by its leading
	 * dimensions.
	 */
	private PrefixMeasurement measurePrefix(int scriptId, FontTypeFace baseFont, Object[] objectStack,
			int objectStackSize, String semanticBody, int[] intStack, int intStackSize) {
		final List<String> components = findPrefixComponents(objectStack, objectStackSize, semanticBody);
		if (components.isEmpty()) {
			return null;
		}

		if (scriptId == CHAT_BODY_SCRIPT) {
			/*
			 * Script 203 supplies one complete rendered prefix String immediately before
			 * the body. Preserve markup during width measurement.
			 */
			final String rawPrefix = normalizeRawForMeasurement(components.get(components.size() - 1));
			return new PrefixMeasurement(baseFont.getTextWidth(rawPrefix));
		}

		if (scriptId == CLAN_BODY_SCRIPT) {
			final StringBuilder prefixText = new StringBuilder();
			for (int i = 0; i < components.size(); i++) {
				if (i > 0) {
					prefixText.append(' ');
				}

				prefixText.append(normalizeRawForMeasurement(components.get(i)));
			}

			final int textWidth = baseFont.getTextWidth(prefixText.toString());
			int decorationWidth = 0;

			/*
			 * Script 4483's 13 x 13 decoration contributes 12px of rendered horizontal width.
			 */
			final int commonPayloadStart = intStackSize - 11;
			if (commonPayloadStart >= 3) {
				final int widthCandidate = intStack[1];
				final int heightCandidate = intStack[2];
				if (widthCandidate > 0 && widthCandidate <= 32 && heightCandidate > 0 && heightCandidate <= 32) {
					decorationWidth = Math.max(0, widthCandidate - 1);
				}
			}

			return new PrefixMeasurement(textWidth + decorationWidth);
		}

		return null;
	}

	private List<String> findPrefixComponents(Object[] stack, int size, String semanticBody) {
		final List<String> output = new ArrayList<>();

		if (stack == null || size <= 0 || semanticBody == null) {
			return output;
		}

		final int safeSize = Math.min(size, stack.length);
		for (int i = 0; i < safeSize; i++) {
			final Object value = stack[i];
			if (!(value instanceof String)) {
				continue;
			}

			final String raw = (String) value;
			final String semantic = ChatText.toSemanticPlain(raw);
			if (semantic == null) {
				continue;
			}
			if (semantic.equals(semanticBody)) {
				break;
			}

			output.add(raw);
		}

		return output;
	}

	/*
	 * Resolve an actual Jagex FontTypeFace for an arbitrary FontID.
	 *
	 * The chat-input widget is used only as a temporary font probe.
	 * Its original FontId is immediately restored and no revalidation occurs.
	 */
	private FontTypeFace resolveFont(int fontId) {
		final FontTypeFace cached = fontCache.get(fontId);
		if (cached != null) {
			return cached;
		}

		final Widget probe = client.getWidget(InterfaceID.Chatbox.INPUT);
		if (probe == null) {
			return null;
		}

		final int originalFontId = probe.getFontId();
		try {
			probe.setFontId(fontId);

			final FontTypeFace resolved = probe.getFont();
			if (resolved != null) {
				fontCache.put(fontId, resolved);
			}

			return resolved;
		} finally {
			probe.setFontId(originalFontId);
		}
	}

	private int ceilDiv(int numerator, int denominator) {
		if (denominator <= 0) {
			return numerator;
		}

		return (numerator + denominator - 1) / denominator;
	}

	private String normalizeRawForMeasurement(String value) {
		if (value == null) {
			return "";
		}

		return value.replace('\u00A0', ' ').replace('\u202F', ' ');
	}

	private String comparable(String value) {
		if (value == null) {
			return "";
		}

		return value.replace('\u00A0', ' ').replace('\u202F', ' ').toLowerCase();
	}

	private static final class PrefixMeasurement {
		private final int width;

		private PrefixMeasurement(int width) {
			this.width = width;
		}
	}
}

package com.runetags.chat;

import java.awt.Point;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Optional;

public class ChatHitboxRegistry {
	private volatile List<ReferenceHitbox> hitboxes = Collections.emptyList();

	public void replace(List<ReferenceHitbox> newHitboxes) {
		hitboxes = Collections.unmodifiableList(new ArrayList<>(newHitboxes));
	}

	public Optional<ReferenceHitbox> find(Point point) {
		for (ReferenceHitbox hitbox : hitboxes) {
			if (hitbox.contains(point)) {
				return Optional.of(hitbox);
			}
		}

		return Optional.empty();
	}

	public List<ReferenceHitbox> snapshot() {
		return hitboxes;
	}

	public void clear() {
		hitboxes = Collections.emptyList();
	}
}

package com.runetags.chat;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.IdentityHashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.TreeMap;

import net.runelite.api.ChatMessageType;

/**
 * Runtime semantic storage for RuneTags chat messages.
 *
 * Retention is enforced independently per ChatMessageType because RuneScape
 * retains separate histories for different message types. Traffic in one type
 * must not evict a still-retained record from another.
 *
 * The master deque remains globally chronological so snapshot() exposes one
 * ordered semantic stream.
 */
public class TaggedMessageRepository {
	private final int capacityPerType;

	private final Deque<TaggedMessage> messages = new ArrayDeque<>();
	private final Map<ChatMessageType, Integer> countsByType = new EnumMap<>(ChatMessageType.class);
	private final Map<String, List<TaggedMessage>> messagesByBody = new HashMap<>();
	private final Map<String, List<TaggedMessage>> messagesByFoldedBody = new HashMap<>();
	private final Map<TaggedMessage, Long> insertionOrder = new IdentityHashMap<>();

	private long nextInsertionOrder;
	private long revision;

	public TaggedMessageRepository(int capacityPerType) {
		if (capacityPerType < 1) {
			throw new IllegalArgumentException("capacityPerType must be >= 1");
		}
		this.capacityPerType = capacityPerType;
	}

	public synchronized void add(TaggedMessage message) {
		if (message == null) {
			return;
		}

		final ChatMessageType retentionType = retentionType(message);
		messages.addLast(message);
		countsByType.put(retentionType, countsByType.getOrDefault(retentionType, 0) + 1);
		indexMessage(message);
		insertionOrder.put(message, nextInsertionOrder++);
		revision++;

		/*
		 * Evict only the oldest semantic record belonging to this same chat
		 * type.
		 *
		 * Traffic in another channel must never consume this type's retention
		 * allowance.
		 */
		while (countsByType.getOrDefault(retentionType, 0) > capacityPerType) {
			if (!removeOldestOfType(retentionType)) {
				/*
				 * Defensive consistency fallback.
				 *
				 * This should never occur because the count was incremented
				 * together with insertion.
				 */
				countsByType.remove(retentionType);
				break;
			}
		}
	}

	public synchronized Optional<TaggedMessage> get(long id) {
		return messages.stream().filter(message -> message.getId() == id).findFirst();
	}

	public synchronized List<TaggedMessage> snapshot() {
		return Collections.unmodifiableList(new ArrayList<>(messages));
	}

	/*
	 * Returns retained semantic candidates whose bodies can match one of the
	 * currently rendered physical bodies. Results remain newest-first.
	 *
	 * Body indexing narrows the candidate set only; ReferenceLayoutService still
	 * confirms sender ownership before a player-authored row is assigned.
	 * Exact bodies apply to every chat type. Case-folded candidates are private
	 * only, matching ReferenceLayoutService's existing compatibility fallback.
	 */
	public synchronized List<TaggedMessage> snapshotMatchingBodies(
			Set<String> exactBodies, Set<String> foldedBodies, boolean privateOnly) {
		if ((exactBodies == null || exactBodies.isEmpty())
				&& (foldedBodies == null || foldedBodies.isEmpty())) {
			return Collections.emptyList();
		}

		final Map<Long, TaggedMessage> orderedCandidates = new TreeMap<>(Collections.reverseOrder());
		final Set<TaggedMessage> selected = Collections.newSetFromMap(new IdentityHashMap<>());

		if (exactBodies != null) {
			for (String body : exactBodies) {
				addIndexedCandidates(messagesByBody.get(body), privateOnly, false, selected, orderedCandidates);
			}
		}

		if (foldedBodies != null) {
			for (String body : foldedBodies) {
				if (body == null || body.isEmpty()) {
					continue;
				}

				addIndexedCandidates(messagesByFoldedBody.get(body.toLowerCase(Locale.ROOT)), privateOnly, true,
						selected, orderedCandidates);
			}
		}

		return Collections.unmodifiableList(new ArrayList<>(orderedCandidates.values()));
	}

	public synchronized Set<Long> snapshotRetainedIds() {
		final Set<Long> ids = new HashSet<>(messages.size());
		for (TaggedMessage message : messages) {
			if (message != null) {
				ids.add(message.getId());
			}
		}
		return ids;
	}

	public synchronized long getRevision() {
		return revision;
	}

	public synchronized int size() {
		return messages.size();
	}

	public synchronized void clear() {
		if (messages.isEmpty() && countsByType.isEmpty()) {
			return;
		}

		messages.clear();
		countsByType.clear();
		messagesByBody.clear();
		messagesByFoldedBody.clear();
		insertionOrder.clear();
		revision++;
	}

	private void addIndexedCandidates(
			List<TaggedMessage> candidates,
			boolean privateOnly,
			boolean privateFallbackOnly,
			Set<TaggedMessage> selected,
			Map<Long, TaggedMessage> orderedCandidates) {
		if (candidates == null || candidates.isEmpty()) {
			return;
		}

		for (TaggedMessage candidate : candidates) {
			if (candidate == null || !selected.add(candidate)) {
				continue;
			}
			if ((privateOnly || privateFallbackOnly) && !isPrivateMessage(candidate)) {
				continue;
			}

			final Long order = insertionOrder.get(candidate);
			if (order != null) {
				orderedCandidates.put(order, candidate);
			}
		}
	}

	private void indexMessage(TaggedMessage message) {
		final String body = message != null ? message.getOriginalMessage() : null;
		if (body == null || body.isEmpty()) {
			return;
		}

		messagesByBody.computeIfAbsent(body, ignored -> new ArrayList<>()).add(message);
		messagesByFoldedBody.computeIfAbsent(
				body.toLowerCase(Locale.ROOT), ignored -> new ArrayList<>()).add(message);
	}

	private void unindexMessage(TaggedMessage message) {
		final String body = message != null ? message.getOriginalMessage() : null;
		if (body == null || body.isEmpty()) {
			return;
		}

		removeIndexedMessage(messagesByBody, body, message);
		removeIndexedMessage(messagesByFoldedBody, body.toLowerCase(Locale.ROOT), message);
	}

	private static void removeIndexedMessage(
			Map<String, List<TaggedMessage>> index, String key, TaggedMessage message) {
		final List<TaggedMessage> indexed = index.get(key);
		if (indexed == null) {
			return;
		}

		for (Iterator<TaggedMessage> iterator = indexed.iterator(); iterator.hasNext();) {
			if (iterator.next() == message) {
				iterator.remove();
				break;
			}
		}

		if (indexed.isEmpty()) {
			index.remove(key);
		}
	}

	private boolean removeOldestOfType(ChatMessageType type) {
		final Iterator<TaggedMessage> iterator = messages.iterator();
		while (iterator.hasNext()) {
			final TaggedMessage candidate = iterator.next();
			if (retentionType(candidate) != type) {
				continue;
			}
			iterator.remove();
			unindexMessage(candidate);
			insertionOrder.remove(candidate);

			final int remaining = countsByType.getOrDefault(type, 0) - 1;
			if (remaining > 0) {
				countsByType.put(type, remaining);
			} else {
				countsByType.remove(type);
			}
			return true;
		}
		return false;
	}

	private static boolean isPrivateMessage(TaggedMessage message) {
		if (message == null || message.getType() == null) {
			return false;
		}

		final ChatMessageType type = message.getType();
		return type == ChatMessageType.PRIVATECHAT
				|| type == ChatMessageType.MODPRIVATECHAT
				|| type == ChatMessageType.PRIVATECHATOUT;
	}

	private static ChatMessageType retentionType(TaggedMessage message) {
		if (message == null || message.getType() == null) {
			return ChatMessageType.UNKNOWN;
		}
		return message.getType();
	}
}

package com.runetags.chat;

import java.util.Arrays;

import net.runelite.client.util.Text;

/**
 * Maps offsets from RuneTags' plain semantic message back to the raw RuneLite
 * message string, preserving any existing Jagex/RuneLite formatting tags.
 *
 * This lets RuneTags add formatting around exact semantic spans without
 * rebuilding or visibly rewriting the sender's original message.
 */
public final class MessageMarkupMap {
	private static final String AT_TAG = "<at>";

	private final String plain;
	private final int[] plainBoundaryToRaw;

	private MessageMarkupMap(String plain, int[] plainBoundaryToRaw) {
		this.plain = plain;
		this.plainBoundaryToRaw = plainBoundaryToRaw;
	}

	public static MessageMarkupMap create(String raw) {
		if (raw == null) {
			raw = "";
		}

		String expectedPlain = ChatText.toSemanticPlain(raw);
		int[] boundaries = new int[expectedPlain.length() + 1];
		Arrays.fill(boundaries, -1);

		int plainIndex = 0;
		int rawIndex = 0;
		boundaries[0] = 0;

		while (rawIndex < raw.length()) {
			if (raw.startsWith(AT_TAG, rawIndex)) {
				boundaries[plainIndex] = rawIndex;
				plainIndex++;
				rawIndex += AT_TAG.length();
				boundaries[plainIndex] = rawIndex;
				continue;
			}

			char c = raw.charAt(rawIndex);
			if (c == '<') {
				int close = raw.indexOf('>', rawIndex);
				if (close >= 0) {
					// Text.removeTags() removes RuneLite/Jagex markup from the
					// semantic message. Skip the same markup here.
					rawIndex = close + 1;
					continue;
				}
			}

			if (plainIndex < expectedPlain.length()) {
				boundaries[plainIndex] = rawIndex;
				plainIndex++;
				boundaries[plainIndex] = rawIndex + 1;
			}

			rawIndex++;
		}

		// Empty trailing markup can make the final boundary point before the
		// physical end of the raw string. For insertion at the end of visible
		// text we want to remain before trailing tags, which is intentional.
		if (expectedPlain.isEmpty()) {
			boundaries[0] = 0;
		}

		return new MessageMarkupMap(expectedPlain, boundaries);
	}

	public boolean matchesPlain(String semanticPlain) {
		return plain.equals(semanticPlain == null
				? ""
				: semanticPlain);
	}

	public int rawBoundary(int plainOffset) {
		if (plainOffset < 0 || plainOffset >= plainBoundaryToRaw.length) {
			return -1;
		}
		return plainBoundaryToRaw[plainOffset];
	}
}

package com.runetags.chat;

import com.runetags.mention.KnownPlayerMentionParser;
import com.runetags.mention.LocalMentionMatch;
import com.runetags.mention.LocalMentionMatcher;
import com.runetags.mention.TagParser;
import com.runetags.reference.PlayerReference;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

import net.runelite.api.ChatMessageType;

/**
 * Processes semantic chat messages into structured RuneTags message state.
 */
public class ChatProcessor {
	private final TagParser tagParser;
	private final KnownPlayerMentionParser knownPlayerMentionParser;
	private final LocalMentionMatcher localMentionMatcher;

	public ChatProcessor(
			TagParser tagParser,
			KnownPlayerMentionParser knownPlayerMentionParser,
			LocalMentionMatcher localMentionMatcher) {
		this.tagParser = tagParser;
		this.knownPlayerMentionParser = knownPlayerMentionParser;
		this.localMentionMatcher = localMentionMatcher;
	}

	public TaggedMessage process(long id, ChatMessageType type, String sender, String message, String localPlayerName) {
		final List<PlayerReference> references = new ArrayList<>();

		/*
		 * Parse explicit @tags first so their spans are reserved before
		 * ordinary known-player matching.
		 */
		final List<PlayerReference> tags = tagParser.parse(message);
		references.addAll(tags);

		final List<PlayerReference> knownReferences = knownPlayerMentionParser.parse(message, tags);
		references.addAll(knownReferences);

		/*
		 * Attach the originating chat channel to every reference before
		 * final ordering and local-player matching.
		 */
		for (int index = 0; index < references.size(); index++) {
			references.set(index, references.get(index).toBuilder().chatType(type).build());
		}

		references.sort(Comparator.comparingInt(PlayerReference::getStartOffset));

		LocalMentionMatch bestMatch = LocalMentionMatch.none();

		/*
		 * Structured references take priority because they provide the most
		 * specific semantic match.
		 */
		for (PlayerReference reference : references) {
			final LocalMentionMatch candidate = localMentionMatcher.match(reference, localPlayerName);
			if (candidate.isMatchesLocalPlayer()) {
				bestMatch = candidate;
				break;
			}
		}

		/*
		 * If no structured reference matched the local player, check the
		 * complete message for account-name variants and unique highlights.
		 */
		if (!bestMatch.isMatchesLocalPlayer()) {
			final LocalMentionMatch messageMatch = localMentionMatcher.matchMessage(message, localPlayerName);
			if (messageMatch.isMatchesLocalPlayer()) {
				bestMatch = messageMatch;
			}
		}

		return TaggedMessage.builder()
				.id(id)
				.type(type)
				.originalSender(sender)
				.canonicalSender(sender)
				.originalMessage(message)
				.timestamp(Instant.now())
				.references(references)
				.localMentionMatch(bestMatch)
				.build();
	}
}

package com.runetags.chat;

import net.runelite.client.util.Text;

public final class ChatText {
	private ChatText() {
	}

	public static String toSemanticPlain(String raw) {
		if (raw == null || raw.isEmpty()) {
			return "";
		}

		String protectedText = raw.replace("<at>", "\u0001");
		return Text.removeTags(protectedText).replace('\u0001', '@');
	}
}

package com.runetags.chat;

import com.runetags.config.MentionFont;

import net.runelite.api.FontID;

/**
 * Resolves RuneTags mention-font substitutions from the active chat font.
 */
public final class MentionFontResolver {
	private MentionFontResolver() {
	}

	public static int fontIdFor(MentionFont mentionFont, int fontId) {
		if (mentionFont == null) {
			return fontId;
		}

		switch (mentionFont) {
			case BOLD:
				return boldFontId(fontId);
			case NORMAL:
			default:
				return normalFontId(fontId);
		}
	}

	public static int normalFontId(int fontId) {
		switch (fontId) {
			case FontID.BOLD_12:
				return FontID.PLAIN_12;
			case FontID.VERDANA_11_BOLD:
				return FontID.VERDANA_11;
			case FontID.VERDANA_13_BOLD:
				return FontID.VERDANA_13;
			default:
				return fontId;
		}
	}

	public static int boldFontId(int fontId) {
		switch (fontId) {
			case FontID.PLAIN_12:
				return FontID.BOLD_12;
			case FontID.BOLD_12:
				return FontID.BOLD_12;
			case FontID.VERDANA_11:
				return FontID.VERDANA_11_BOLD;
			case FontID.VERDANA_11_BOLD:
				return FontID.VERDANA_11_BOLD;
			case FontID.VERDANA_13:
				return FontID.VERDANA_13_BOLD;
			case FontID.VERDANA_13_BOLD:
				return FontID.VERDANA_13_BOLD;
			default:
				return fontId;
		}
	}
}

package com.runetags.chat;

import com.runetags.Configurations;
import com.runetags.config.ClickablePlayerMode;
import com.runetags.reference.PlayerReference;
import com.runetags.reference.ReferenceType;

public final class ChatInteractionPolicy {
	private ChatInteractionPolicy() {
	}

	public static boolean isClickable(PlayerReference reference, Configurations config) {
		if (reference == null || config == null) {
			return false;
		}

		final ClickablePlayerMode mode = config.clickablePlayers();
		switch (mode) {
			case ALL:
				return true;
			case MENTIONS:
				return reference.getType() == ReferenceType.MENTION || reference.getType() == ReferenceType.TAG;
			case TAGGED_ONLY:
				return reference.getType() == ReferenceType.TAG;
			default:
				return false;
		}
	}
}

package com.runetags.chat;

import com.runetags.Configurations;
import com.runetags.mention.LocalMentionMatch;
import com.runetags.mention.LocalMentionMatcher;
import com.runetags.mention.MatchReason;
import com.runetags.reference.PlayerReference;
import com.runetags.reference.ReferenceType;

import java.awt.Color;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;

import net.runelite.client.chat.ChatColorType;
import net.runelite.client.util.ColorUtil;

/**
 * Applies RuneTags foreground, underline, and shadow markup to semantic message spans.
 *
 * Existing RuneLite/Jagex markup is preserved. Backgrounds are rendered by ChatReferenceOverlay.
 */
public class MessageFormatter {
	private final Configurations config;
	private final LocalMentionMatcher localMentionMatcher;

	public MessageFormatter(Configurations config, LocalMentionMatcher localMentionMatcher) {
		this.config = config;
		this.localMentionMatcher = localMentionMatcher;
	}

	public String format(TaggedMessage message, String rawMessage, String localPlayerName) {
		if (message == null || rawMessage == null) {
			return rawMessage;
		}

		final MessageMarkupMap markupMap = MessageMarkupMap.create(rawMessage);
		if (!markupMap.matchesPlain(message.getOriginalMessage())) {
			/*
			 * Skip formatting when raw and semantic offsets no longer map safely.
			 */
			return rawMessage;
		}

		/*
		 * Local matches include account-name variants and Unique Highlights.
		 * Mention Whole Message applies Self Mention Color to the complete body.
		 */
		final boolean mentionWholeMessage = config.mentionWholeMessage()
				&& config.mentionSelf() && message.getLocalMentionMatch().isMatchesLocalPlayer();

		final String wholeMessageColorTag = mentionWholeMessage
				? ColorUtil.colorTag(config.selfMentionColor())
				: null;

		final List<StyleSpan> spans = new ArrayList<>();

		/*
		 * PlayerReference spans retain their own mention styling when the complete message
		 * uses Self Mention Color.
		 */
		for (PlayerReference reference : message.getReferences()) {
			final LocalMentionMatch localMatch = localMentionMatcher.match(reference, localPlayerName);
			final boolean isSelf = localMatch.isMatchesLocalPlayer();

			/*
			 * Self Mention / Others Mention control foreground color only.
			 * Underline Mentions controls underline only.
			 * Shadow Mentions controls shadow only.
			 */
			final boolean shouldColor = isSelf
					? config.mentionSelf()
					: config.mentionOthers();

			/*
			 * Resolved references keep native <u> markup.
			 * Unresolved tags omit native <u> because their underline is rendered as a dotted overlay.
			 */
			final boolean unresolvedTag = reference.getType() == ReferenceType.TAG && !reference.isLocallyResolved();
			final boolean underline = config.underlineMentions() && !unresolvedTag;

			final Color shadowColor = config.shadowMentions()
					? config.shadowMentionColor()
					: null;

			if (!shouldColor && !underline && shadowColor == null) {
				continue;
			}

			spans.add(new StyleSpan(reference.getStartOffset(), reference.getEndOffset(), shouldColor
					? (isSelf ? config.selfMentionColor()
					: config.otherMentionColor()) : null, underline, shadowColor));
		}

		/*
		 * Add local-token spans not represented by PlayerReference objects.
		 * Whole-message coloring and token decoration remain independent.
		 */
		addLocalMessageHighlightSpans(message, spans);

		/*
		 * Right-to-left insertion keeps the original semantic/raw offsets valid.
		 */
		spans.sort(Comparator.comparingInt(StyleSpan::getStartOffset).reversed());

		String formatted = rawMessage;

		for (StyleSpan span : spans) {
			final int rawStart = markupMap.rawBoundary(span.getStartOffset());
			final int rawEnd = markupMap.rawBoundary(span.getEndOffset());
			if (rawStart < 0 || rawEnd < rawStart || rawEnd > formatted.length()) {
				continue;
			}

			/*
			 * If the complete message is using Self Mention Color, temporarily
			 * styled spans must restore that color afterward.
			 *
			 * Otherwise restore whatever RuneLite/Jagex color was active before
			 * the span.
			 */
			final String restoreColor = wholeMessageColorTag != null
					? wholeMessageColorTag
					: getLastColor(formatted.substring(0, rawStart));
			final String openingColor = span.getColor() != null
					? ColorUtil.colorTag(span.getColor())
					: "";
			final String closingColor = span.getColor() != null
					? restoreColor
					: "";
			final String openingUnderline = span.isUnderline()
					? "<u>"
					: "";
			final String closingUnderline = span.isUnderline()
					? "</u>"
					: "";
			final String openingShadow = span.getShadowColor() != null
					? "<shad=" + String.format("%06x", span.getShadowColor().getRGB() & 0xFFFFFF) + ">"
					: "";
			final String closingShadow = span.getShadowColor() != null
					? "</shad>"
					: "";
			formatted = formatted.substring(0, rawStart)
					+ openingColor
					+ openingShadow
					+ openingUnderline
					+ formatted.substring(rawStart, rawEnd)
					+ closingUnderline
					+ closingShadow
					+ closingColor
					+ formatted.substring(rawEnd);
		}

		/*
		 * Apply the complete-message foreground color last.
		 *
		 * Individual span colors inserted above still override it locally, then
		 * restore back to Self Mention Color.
		 */
		if (wholeMessageColorTag != null) {
			formatted = wholeMessageColorTag + formatted + ColorUtil.CLOSING_COLOR_TAG;
		}

		return formatted;
	}

	/*
	 * Adds styling spans for local matches that do not create PlayerReference identity
	 * or interaction.
	 */
	private void addLocalMessageHighlightSpans(TaggedMessage message, List<StyleSpan> spans) {
		final boolean shouldColor = config.mentionSelf();
		final boolean underline = config.underlineMentions();
		final Color shadowColor = config.shadowMentions()
				? config.shadowMentionColor()
				: null;

		if (!shouldColor && !underline && shadowColor == null) {
			return;
		}

		final LocalMentionMatch localMatch = message.getLocalMentionMatch();
		if (localMatch == null || !localMatch.isMatchesLocalPlayer()) {
			return;
		}

		/*
		 * Skip ACCOUNT_NAME matches already represented by PlayerReference.
		 * Normalized account variants and Unique Highlights remain eligible.
		 */
		if (localMatch.getReason() != MatchReason.NORMALIZED_ACCOUNT_NAME
				&& localMatch.getReason() != MatchReason.UNIQUE_HIGHLIGHT) {
			return;
		}

		final String token = localMatch.getMatchedToken();
		if (token == null || token.trim().isEmpty()) {
			return;
		}

		final String messageText = message.getOriginalMessage();
		if (messageText == null || messageText.isEmpty()) {
			return;
		}

		final String loweredMessage = messageText.toLowerCase(Locale.ROOT);
		final String loweredToken = token.toLowerCase(Locale.ROOT);

		int from = 0;

		while (from <= loweredMessage.length() - loweredToken.length()) {
			final int start = loweredMessage.indexOf(loweredToken, from);
			if (start < 0) {
				break;
			}
			final int end = start + loweredToken.length();
			if (hasBoundaries(loweredMessage, start, end) && !overlapsExistingSpan(start, end, spans)) {
				spans.add(new StyleSpan(start, end, shouldColor
					? config.selfMentionColor()
					: null, underline, shadowColor));
			}

			from = start + 1;
		}
	}

	private static boolean overlapsExistingSpan(int start, int end, List<StyleSpan> spans) {
		for (StyleSpan span : spans) {
			if (start < span.getEndOffset() && end > span.getStartOffset()) {
				return true;
			}
		}

		return false;
	}

	private static boolean hasBoundaries(String text, int start, int end) {
		final boolean leftBoundary = start == 0 || !isNameChar(text.charAt(start - 1));
		final boolean rightBoundary = end == text.length() || !isNameChar(text.charAt(end));
		return leftBoundary && rightBoundary;
	}

	private static boolean isNameChar(char c) {
		return Character.isLetterOrDigit(c) || c == '_' || c == '-';
	}

	/*
	 * Determine which chat color was active before RuneTags temporarily
	 * changed the foreground of a span.
	 */
	private static String getLastColor(String text) {
		if (text == null || text.isEmpty()) {
			return normalColorTag();
		}

		final int colorStart = text.lastIndexOf("<col=");
		final int colorEnd = text.lastIndexOf("</col>");
		if (colorEnd > colorStart) {
			return normalColorTag();
		}
		if (colorStart < 0) {
			return normalColorTag();
		}

		final int tagEnd = text.indexOf('>', colorStart);
		if (tagEnd < 0) {
			return normalColorTag();
		}

		return text.substring(colorStart, tagEnd + 1);
	}

	private static String normalColorTag() {
		return "<col" + ChatColorType.NORMAL + ">";
	}

	/*
	 * Formatting span with no PlayerReference identity or interaction.
	 */
	private static final class StyleSpan {
		private final int startOffset;
		private final int endOffset;
		private final Color color;
		private final boolean underline;
		private final Color shadowColor;

		private StyleSpan(int startOffset, int endOffset, Color color, boolean underline, Color shadowColor) {
			this.startOffset = startOffset;
			this.endOffset = endOffset;
			this.color = color;
			this.underline = underline;
			this.shadowColor = shadowColor;
		}

		private int getStartOffset() {
			return startOffset;
		}

		private int getEndOffset() {
			return endOffset;
		}

		private Color getColor() {
			return color;
		}

		private boolean isUnderline() {
			return underline;
		}

		private Color getShadowColor() {
			return shadowColor;
		}
	}
}

package com.runetags.chat;

import com.runetags.Configurations;
import com.runetags.config.MentionFont;
import com.runetags.mention.LocalMentionMatch;
import com.runetags.mention.MatchReason;
import com.runetags.records.LocalPlayerRecordService;
import com.runetags.reference.PlayerReference;
import com.runetags.reference.ReferenceType;

import java.awt.Color;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.FontTypeFace;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetTextAlignment;

/**
 * Maps semantic chat references and local-highlight spans onto rendered chat Widgets.
 *
 * CHATBOX and SPLIT_PRIVATE are independent physical surfaces, and one TaggedMessage
 * may resolve on both. Width and wrapping use each Widget's live Jagex FontTypeFace.
 */
public class ReferenceLayoutService {
	/**
	 * Physical surface on which RuneScape rendered a chat reference.
	 *
	 * This is deliberately separate from ChatMessageType.
	 *
	 * For example, PRIVATECHAT may render:
	 *
	 * - on CHATBOX,
	 * - on SPLIT_PRIVATE,
	 * - or on both simultaneously.
	 */
	public enum Surface {
		CHATBOX, SPLIT_PRIVATE
	}

	/**
	 * Complete presentation geometry produced by one shared chat-layout pass.
	 *
	 * Clickable reference/sender hitboxes and non-clickable local-highlight
	 * rectangles deliberately share the same semantic -> physical Widget
	 * association.
	 */
	public static final class LayoutResult {
		private final List<ReferenceHitbox> hitboxes;
		private final List<LocalHighlight> localHighlights;

		private LayoutResult(List<ReferenceHitbox> hitboxes, List<LocalHighlight> localHighlights) {
			this.hitboxes = hitboxes;
			this.localHighlights = localHighlights;
		}

		public List<ReferenceHitbox> getHitboxes() {
			return hitboxes;
		}

		public List<LocalHighlight> getLocalHighlights() {
			return localHighlights;
		}
	}

	/*
	 * One non-clickable physical overlay rectangle for a local alias or normalized-self match.
	 */
	public static final class LocalHighlight {
		private final long messageId;
		private final Rectangle bounds;
		private final Surface surface;

		private LocalHighlight(long messageId, Rectangle bounds, Surface surface) {
			this.messageId = messageId;
			this.bounds = bounds;
			this.surface = surface;
		}

		public long getMessageId() {
			return messageId;
		}

		public Rectangle getBounds() {
			return bounds;
		}

		public Surface getSurface() {
			return surface;
		}
	}

	private static final int MAX_WIDGET_DEPTH = 4;
	private static final int CHATBOX_X_PENDING = Integer.MIN_VALUE;

	/*
	 * One physical line produced by RuneScape's wrapped text widget.
	 *
	 * start/end are semantic plain-text offsets into the complete
	 * widget text. Width is the rendered width of this individual
	 * visual line.
	 */
	private static final class WrappedLine {
		private final int start;
		private final int end;
		private final int width;

		private WrappedLine(int start, int end, int width) {
			this.start = start;
			this.end = end;
			this.width = width;
		}
	}

	/*
	 * Pass-local semantic text and bounds snapshot for one rendered Widget.
	 *
	 * Cached bounds drive indexing only. Final ownership and output geometry still
	 * revalidate against the live Widget so reconstruction races remain observable.
	 */
	private static final class RenderedTextWidget {
		private final Widget widget;
		private final String rawText;
		private final String semanticText;
		private final Rectangle bounds;

		private RenderedTextWidget(Widget widget, String rawText, String semanticText, Rectangle bounds) {
			this.widget = widget;
			this.rawText = rawText;
			this.semanticText = semanticText;
			this.bounds = bounds;
		}
	}

	/*
	 * Exact physical CHATBOX sender widget and the sender's semantic start
	 * offset inside that widget.
	 */
	private static final class RenderedSenderMatch {
		private final RenderedTextWidget rendered;
		private final int semanticStart;

		private RenderedSenderMatch(RenderedTextWidget rendered, int semanticStart) {
			this.rendered = rendered;
			this.semanticStart = semanticStart;
		}
	}

	/*
	 * Native sender text ownership for one Widget currently colored by
	 * RuneTags. Both original and applied strings are retained so a recycled
	 * Widget is never restored over newer RuneScape content.
	 */
	private static final class FavoriteSenderTextState {
		private final String originalText;
		private final String appliedText;

		private FavoriteSenderTextState(String originalText, String appliedText) {
			this.originalText = originalText;
			this.appliedText = appliedText;
		}
	}

	/*
	 * Font ownership for one physical Widget modified by RuneTags.
	 *
	 * Restoration is permitted only while the Widget still contains the exact
	 * FontId RuneTags applied. A different current FontId means another owner has
	 * replaced the presentation and the stale original must not be restored.
	 */
	private static final class MentionFontState {
		private final int originalFontId;
		private final int appliedFontId;

		private MentionFontState(int originalFontId, int appliedFontId) {
			this.originalFontId = originalFontId;
			this.appliedFontId = appliedFontId;
		}
	}

	/*
	 * Indexes semantic text while preserving native candidate order.
	 *
	 * Geometry, visibility, and FontTypeFace remain live reads.
	 */
	private static final class RenderedBodyIndex {
		private final Map<String, List<RenderedTextWidget>> bodyIndex = new HashMap<>();
		private final Map<String, List<RenderedTextWidget>> caseFoldedBodyIndex = new HashMap<>();
		private final List<RenderedTextWidget> whitespaceBodies = new ArrayList<>();
		private final Set<String> exactBodies = new HashSet<>();
		private final Set<String> foldedBodies = new HashSet<>();

		private RenderedBodyIndex(List<RenderedTextWidget> widgets) {
			if (widgets == null) {
				return;
			}

			for (RenderedTextWidget rendered : widgets) {
				if (rendered == null) {
					continue;
				}

				final String semantic = rendered.semanticText;
				if (semantic == null || semantic.isEmpty()) {
					continue;
				}

				exactBodies.add(semantic);
				if (semantic.trim().isEmpty()) {
					whitespaceBodies.add(rendered);
					continue;
				}

				bodyIndex.computeIfAbsent(semantic, ignored -> new ArrayList<>()).add(rendered);

				final String folded = semantic.toLowerCase(Locale.ROOT);
				foldedBodies.add(folded);
				caseFoldedBodyIndex.computeIfAbsent(folded, ignored -> new ArrayList<>()).add(rendered);
			}
		}

		private List<RenderedTextWidget> candidates(String semanticBody) {
			if (semanticBody == null || semanticBody.isEmpty()) {
				return Collections.emptyList();
			}
			if (semanticBody.trim().isEmpty()) {
				return whitespaceBodies;
			}

			final List<RenderedTextWidget> candidates = bodyIndex.get(semanticBody);
			return candidates != null
					? candidates
					: Collections.emptyList();
		}

		private List<RenderedTextWidget> candidatesIgnoreCase(String semanticBody) {
			if (semanticBody == null || semanticBody.isEmpty() || semanticBody.trim().isEmpty()) {
				return Collections.emptyList();
			}

			final List<RenderedTextWidget> candidates = caseFoldedBodyIndex.get(semanticBody.toLowerCase(Locale.ROOT));
			return candidates != null
					? candidates
					: Collections.emptyList();
		}

		private Set<String> exactBodies() {
			return exactBodies;
		}

		private Set<String> foldedBodies() {
			return foldedBodies;
		}
	}

	/*
	 * Stable physical row identity used by RuneScape/Big Bold Chat independently
	 * from the transient canvas Y coordinate.
	 */
	private static final class RowKey {
		private final int originalY;
		private final int relativeY;

		private RowKey(int originalY, int relativeY) {
			this.originalY = originalY;
			this.relativeY = relativeY;
		}

		@SuppressWarnings("deprecation")
		private static RowKey of(Widget widget) {
			return widget != null
					? new RowKey(widget.getOriginalY(), widget.getRelativeY())
					: null;
		}

		@Override
		public boolean equals(Object other) {
			if (this == other) {
				return true;
			}
			if (!(other instanceof RowKey)) {
				return false;
			}

			final RowKey rowKey = (RowKey) other;
			return originalY == rowKey.originalY && relativeY == rowKey.relativeY;
		}

		@Override
		public int hashCode() {
			int result = originalY;
			result = 31 * result + relativeY;
			return result;
		}
	}

	/*
	 * Accepted CHATBOX body ownership and content-space Y for one semantic message.
	 */
	private static final class ChatboxBodyState {
		private final RowKey rowKey;
		private final int contentY;

		private ChatboxBodyState(RowKey rowKey, int contentY) {
			this.rowKey = rowKey;
			this.contentY = contentY;
		}

	}


	/*
	 * One reusable text-bearing Widget discovered beneath a chat surface.
	 *
	 * Membership is stable across ordinary render frames. Raw/semantic text remains
	 * mutable because RuneScape recycles the same Widget for newer chat rows.
	 */
	private static final class CachedRenderedWidget {
		private final Widget widget;
		private String rawText;
		private String semanticText;

		private CachedRenderedWidget(Widget widget) {
			this.widget = widget;
		}
	}

	/*
	 * Cross-frame text-Widget membership cache for one physical chat surface.
	 *
	 * Native reconstruction and repository revision changes both force rediscovery,
	 * while bounds, hidden state, RowKey, and final geometry remain live every pass.
	 */
	private static final class RenderedSurfaceCache {
		private Widget root;
		private final List<CachedRenderedWidget> widgets = new ArrayList<>();
		private int topologySignature;
		private long repositoryRevision = Long.MIN_VALUE;
		private boolean dirty = true;
	}

	/*
	 * Every indexed candidate is revalidated against live bounds before it can confirm message ownership.
	 */
	private static final class RenderedRowIndex {
		private final Map<Integer, List<RenderedTextWidget>> rowIndex = new HashMap<>();

		private RenderedRowIndex(List<RenderedTextWidget> widgets) {
			if (widgets == null) {
				return;
			}

			for (RenderedTextWidget rendered : widgets) {
				if (rendered == null || rendered.widget == null || rendered.bounds == null) {
					continue;
				}

				rowIndex.computeIfAbsent(rendered.bounds.y, ignored -> new ArrayList<>()).add(rendered);
			}
		}

		private List<RenderedTextWidget> candidates(int y) {
			final List<RenderedTextWidget> candidates = rowIndex.get(y);
			return candidates != null
					? candidates
					: Collections.emptyList();
		}
	}

	private final Client client;
	private final Configurations config;
	private final TaggedMessageRepository repository;
	private final LocalPlayerRecordService localPlayerRecordService;

	private final Map<Widget, MentionFontState> mentionFontStates = new IdentityHashMap<>();
	private final Map<Widget, FavoriteSenderTextState> favoriteSenderTextStates = new IdentityHashMap<>();

	/*
	 * A reconstructed CHATBOX body can briefly expose recycled horizontal or
	 * canvas geometry before RuneScape finishes positioning the row.
	 *
	 * X changes are confirmed across consecutive layout passes while rendering
	 * continues from the last accepted X. Y correction applies only while the
	 * physical row identity itself remains unchanged.
	 */
	private final Map<Long, Integer> acceptedChatboxBodyX = new HashMap<>();
	private final Map<Long, Integer> pendingChatboxBodyX = new HashMap<>();
	private final Map<Long, ChatboxBodyState> acceptedChatboxBodyRows = new HashMap<>();

	private final RenderedSurfaceCache chatboxRenderedSurfaceCache = new RenderedSurfaceCache();
	private final RenderedSurfaceCache splitPrivateRenderedSurfaceCache = new RenderedSurfaceCache();
	private long lastGeometryPruneRevision = Long.MIN_VALUE;


	private boolean favoriteSenderRowsDirty = true;
	private long lastFavoriteRevision = Long.MIN_VALUE;
	private boolean lastFavoritesEnabled;
	private int lastFavoriteColorRgb = Integer.MIN_VALUE;

	public ReferenceLayoutService(
			Client client,
			Configurations config,
			TaggedMessageRepository repository,
			LocalPlayerRecordService localPlayerRecordService) {
		this.client = client;
		this.config = config;
		this.repository = repository;
		this.localPlayerRecordService = localPlayerRecordService;
	}

	/*
	 * Native chat reconstruction can replace or recycle descendants while preserving
	 * the same surface root. Invalidate membership before the construction script runs
	 * so the next synchronization/layout pass rediscovers the physical row Widgets.
	 */
	public void invalidateRenderedWidgetCaches() {
		chatboxRenderedSurfaceCache.dirty = true;
		splitPrivateRenderedSurfaceCache.dirty = true;
	}

	/*
	 * Synchronizes configured mention fonts against final post-construction chat Widgets.
	 *
	 * RuneTags-owned font state is restored before current message ownership is resolved
	 * and reapplied.
	 */
	public void syncMentionFonts() {
		/*
		 * Physical Widget instances are recycled by RuneScape. Always restore
		 * native ownership before resolving the current live rows.
		 */
		restoreAllOriginalFonts();

		/*
		 * Dirty synchronization also repairs native expanded-name styling, including NORMAL mode.
		 */
		final List<TaggedMessage> messages = new ArrayList<>(repository.snapshot());
		Collections.reverse(messages);

		syncSurfaceFonts(client.getWidget(InterfaceID.PmChat.CONTAINER), Surface.SPLIT_PRIVATE, messages);
		syncSurfaceFonts(client.getWidget(InterfaceID.Chatbox.SCROLLAREA), Surface.CHATBOX, messages);
	}

	/*
	 * Mark normal-chatbox sender presentation dirty after native row
	 * reconstruction. FontLayoutService calls this alongside font dirtiness
	 * so Favorite color ownership follows the same settled PostClientTick cadence.
	 */
	public void markFavoriteSenderRowsDirty() {
		favoriteSenderRowsDirty = true;
	}

	/*
	 * Synchronize Favorite sender-name colors only when either native rows,
	 * Favorite state, or the Favorites config changed.
	 *
	 * This cheap gate is safe to call every PostClientTick. The expensive
	 * semantic/widget association runs only when presentation is actually dirty.
	 */
	public void syncFavoriteSenderColorsIfNeeded() {
		final long favoriteRevision = localPlayerRecordService != null
				? localPlayerRecordService.getFavoriteRevision()
				: 0L;

		final boolean favoritesEnabled = config.showFavorites();
		final Color favoriteColor = configuredFavoriteColor();
		final int favoriteColorRgb = favoriteColor.getRGB();

		if (!favoriteSenderRowsDirty
				&& favoriteRevision == lastFavoriteRevision
				&& favoritesEnabled == lastFavoritesEnabled
				&& favoriteColorRgb == lastFavoriteColorRgb) {
			return;
		}

		syncFavoriteSenderColors(favoritesEnabled);

		favoriteSenderRowsDirty = false;
		lastFavoriteRevision = favoriteRevision;
		lastFavoritesEnabled = favoritesEnabled;
		lastFavoriteColorRgb = favoriteColorRgb;
	}

	/*
	 * Restore every native sender Widget currently owned by Favorite styling.
	 *
	 * The applied text is compared before restoration. RuneScape can recycle a
	 * Widget for a newer row at any time; if that has already happened, RuneTags
	 * must never write the stale original text back over the new message.
	 */
	public void restoreFavoriteSenderColors() {
		restoreOriginalFavoriteSenderTexts();

		favoriteSenderRowsDirty = true;
		lastFavoriteRevision = Long.MIN_VALUE;
		lastFavoritesEnabled = false;
		lastFavoriteColorRgb = Integer.MIN_VALUE;
	}

	private void syncFavoriteSenderColors(boolean favoritesEnabled) {
		restoreOriginalFavoriteSenderTexts();

		if (!favoritesEnabled || localPlayerRecordService == null) {
			return;
		}

		final List<TaggedMessage> messages = new ArrayList<>(repository.snapshot());
		if (messages.isEmpty()) {
			return;
		}

		Collections.reverse(messages);

		final Widget chatbox = client.getWidget(InterfaceID.Chatbox.SCROLLAREA);
		if (chatbox == null || chatbox.isHidden()) {
			return;
		}

		final List<RenderedTextWidget> textWidgets = new ArrayList<>();

		/*
		 * Use a null viewport just like font synchronization. Retained off-screen
		 * rows can later scroll into view without native reconstruction, so their
		 * Favorite sender color must already be correct.
		 */
		collectRenderedTextWidgets(chatbox, Surface.CHATBOX, null, textWidgets);
		if (textWidgets.isEmpty()) {
			return;
		}

		final RenderedBodyIndex bodyIndex = new RenderedBodyIndex(textWidgets);
		final RenderedRowIndex rowIndex = new RenderedRowIndex(textWidgets);
		final Set<Widget> usedBodyWidgets = Collections.newSetFromMap(new IdentityHashMap<>());

		for (TaggedMessage message : messages) {
			if (message == null || message.getCanonicalSender() == null
					|| message.getCanonicalSender().trim().isEmpty()) {
				continue;
			}

			/*
			 * Reserve body ownership for every retained message before applying Favorite styling.
			 * This prevents duplicate bodies from being claimed by the wrong message.
			 */
			final RenderedTextWidget messageWidget = findRenderedWidgetForMessageIndexedForFont(
					message, textWidgets, bodyIndex, rowIndex, usedBodyWidgets);
			if (messageWidget == null || messageWidget.widget == null) {
				continue;
			}

			usedBodyWidgets.add(messageWidget.widget);

			if (!localPlayerRecordService.isFavorite(message.getCanonicalSender())) {
				continue;
			}

			final RenderedSenderMatch senderMatch = findChatboxSender(
					messageWidget, message.getCanonicalSender(), textWidgets, rowIndex);
			if (senderMatch == null) {
				continue;
			}

			applyFavoriteSenderColor(senderMatch, message.getCanonicalSender());
		}
	}

	private void applyFavoriteSenderColor(RenderedSenderMatch senderMatch, String sender) {
		if (senderMatch == null || senderMatch.rendered == null || senderMatch.rendered.widget == null
				|| sender == null || sender.isEmpty()) {
			return;
		}

		final String rawText = senderMatch.rendered.rawText;
		final String semanticText = senderMatch.rendered.semanticText;
		if (rawText == null || semanticText == null) {
			return;
		}

		final int semanticEnd = senderMatch.semanticStart + sender.length();
		if (semanticEnd > semanticText.length()) {
			return;
		}

		final MessageMarkupMap map = MessageMarkupMap.create(rawText);
		if (!map.matchesPlain(semanticText)) {
			return;
		}

		final int rawStart = map.rawBoundary(senderMatch.semanticStart);
		final int rawEnd = map.rawBoundary(semanticEnd);
		if (rawStart < 0 || rawEnd <= rawStart || rawEnd > rawText.length()) {
			return;
		}

		final String appliedText = rawText.substring(0, rawStart)
				+ "<col="
				+ colorHex(configuredFavoriteColor())
				+ ">"
				+ rawText.substring(rawStart, rawEnd)
				+ "</col>"
				+ rawText.substring(rawEnd);

		if (appliedText.equals(rawText)) {
			return;
		}

		senderMatch.rendered.widget.setText(appliedText);
		favoriteSenderTextStates.put(senderMatch.rendered.widget, new FavoriteSenderTextState(rawText, appliedText));
	}

	private Color configuredFavoriteColor() {
		final Color configured = config.favoriteColor();
		return configured != null
				? configured
				: new Color(255, 205, 70);
	}

	private void restoreOriginalFavoriteSenderTexts() {
		if (favoriteSenderTextStates.isEmpty()) {
			return;
		}

		for (Map.Entry<Widget, FavoriteSenderTextState> entry : favoriteSenderTextStates.entrySet()) {
			final Widget widget = entry.getKey();
			final FavoriteSenderTextState state = entry.getValue();
			if (widget == null || state == null || state.appliedText == null) {
				continue;
			}

			final String currentText = widget.getText();
			if (state.appliedText.equals(currentText)) {
				widget.setText(state.originalText);
			}
		}

		favoriteSenderTextStates.clear();
	}

	/*
	 * Reconciles RuneScape's expanded player-name wrapper with RuneTags mention styling.
	 *
	 * Only wrapper markup is changed; visible text and the native restore color are preserved.
	 */
	private void repairExpandedReferenceStyles(Widget messageWidget, TaggedMessage message) {
		if (messageWidget == null || message == null
				|| message.getReferences() == null || message.getReferences().isEmpty()) {
			return;
		}

		final String rawWidgetText = messageWidget.getText();
		if (rawWidgetText == null || rawWidgetText.isEmpty()) {
			return;
		}

		final String semanticWidgetText = ChatText.toSemanticPlain(rawWidgetText);
		final String originalMessage = message.getOriginalMessage();
		if (semanticWidgetText == null || originalMessage == null || originalMessage.isEmpty()) {
			return;
		}

		int messageStart = semanticWidgetText.indexOf(originalMessage);
		if (messageStart < 0 && isPrivateMessage(message)) {
			messageStart = indexOfIgnoreCase(semanticWidgetText, originalMessage);
		}
		if (messageStart < 0) {
			return;
		}

		final String localPlayerName = client.getLocalPlayer() != null
				? client.getLocalPlayer().getName()
				: null;

		String repaired = rawWidgetText;

		for (PlayerReference reference : message.getReferences()) {
			if (reference == null) {
				continue;
			}

			final int semanticStart = messageStart + reference.getStartOffset();
			final int semanticEnd = messageStart + reference.getEndOffset();
			if (semanticStart < 0 || semanticEnd <= semanticStart || semanticEnd > semanticWidgetText.length()) {
				continue;
			}

			String renderedToken = semanticWidgetText.substring(semanticStart, semanticEnd);
			if (renderedToken.startsWith("@")) {
				renderedToken = renderedToken.substring(1);
			}
			if (renderedToken.isEmpty()) {
				continue;
			}

			final boolean isSelf = samePlayerName(reference.getLookupName(), localPlayerName)
					|| samePlayerName(renderedToken, localPlayerName);
			final boolean shouldColor = isSelf
					? config.mentionSelf()
					: config.mentionOthers();
			final Color desiredColor = isSelf
					? config.selfMentionColor()
					: config.otherMentionColor();

			/*
			 * Rewrite only the expanded player-name wrapper and preserve its native restore color.
			 */
			final Pattern expandedNamePattern = Pattern.compile(
					"<col=([0-9a-fA-F]{6})><u>(" + Pattern.quote(renderedToken) + ")</u><col=([0-9a-fA-F]{6})>",
					Pattern.CASE_INSENSITIVE);

			final Matcher matcher = expandedNamePattern.matcher(repaired);
			if (!matcher.find()) {
				continue;
			}

			final String openingColor = shouldColor && desiredColor != null
					? colorHex(desiredColor)
					: matcher.group(1);
			final String displayedName = matcher.group(2);
			final String restoreColor = matcher.group(3);
			final String replacement = "<col=" + openingColor + ">" + (config.underlineMentions()
					? "<u>"
					: "") + displayedName + (config.underlineMentions()
					? "</u>"
					: "") + "<col=" + restoreColor + ">";

			repaired = matcher.replaceFirst(Matcher.quoteReplacement(replacement));
		}

		if (!repaired.equals(rawWidgetText)) {
			messageWidget.setText(repaired);
		}
	}

	private static String colorHex(Color color) {
		return String.format(Locale.ROOT, "%06x", color.getRGB() & 0xFFFFFF);
	}

	private static boolean samePlayerName(String left, String right) {
		if (left == null || right == null) {
			return false;
		}

		return playerNameKey(left).equals(playerNameKey(right));
	}

	private static String playerNameKey(String value) {
		return value.replace('\u00A0', ' ')
				.replace('_', ' ').trim().toLowerCase(Locale.ROOT);
	}

	/*
	 * Restore every physical chat font currently owned by RuneTags.
	 *
	 * Used when the plugin is shutting down so RuneScape is never left displaying
	 * a RuneTags FontId after the plugin has been disabled.
	 */
	public void restoreMentionFonts() {
		restoreAllOriginalFonts();
	}

	/*
	 * Resolves message ownership for one surface, repairs expanded reference styling,
	 * and applies the configured mention font.
	 */
	private void syncSurfaceFonts(Widget surfaceWidget, Surface surface, List<TaggedMessage> messages) {
		if (surfaceWidget == null || surfaceWidget.isHidden() || messages == null || messages.isEmpty()) {
			return;
		}

		final List<RenderedTextWidget> textWidgets = new ArrayList<>();
		collectRenderedTextWidgets(surfaceWidget, surface, null, textWidgets);

		final RenderedBodyIndex bodyIndex = new RenderedBodyIndex(textWidgets);
		final RenderedRowIndex rowIndex = new RenderedRowIndex(textWidgets);
		if (textWidgets.isEmpty()) {
			return;
		}

		final Set<Widget> usedWidgets = Collections.newSetFromMap(new IdentityHashMap<>());
		for (TaggedMessage message : messages) {
			if (message == null) {
				continue;
			}

			if (surface == Surface.SPLIT_PRIVATE && !isPrivateMessage(message)) {
				continue;
			}

			final RenderedTextWidget messageWidget =
					findRenderedWidgetForMessageIndexedForFont(message, textWidgets, bodyIndex, rowIndex, usedWidgets);
			if (messageWidget == null || messageWidget.widget == null) {
				continue;
			}

			usedWidgets.add(messageWidget.widget);
			repairExpandedReferenceStyles(messageWidget.widget, message);
			applyMentionFont(messageWidget.widget, message);
		}
	}

	/*
	 * Resolves font ownership from the pass-local body index.
	 *
	 * Exact body matching is primary. Sender confirmation and private case-folded fallback
	 * disambiguate candidates. Candidate geometry is always revalidated live.
	 */
	private RenderedTextWidget findRenderedWidgetForMessageIndexedForFont(
			TaggedMessage message, List<RenderedTextWidget> widgets, RenderedBodyIndex bodyIndex,
			RenderedRowIndex rowIndex, Set<Widget> usedWidgets) {
		if (message == null || widgets == null || bodyIndex == null || rowIndex == null || usedWidgets == null) {
			return null;
		}

		final String needle = message.getOriginalMessage();
		if (needle == null || needle.isEmpty()) {
			return null;
		}

		final RenderedTextWidget exactMatch = selectRenderedFontBodyCandidate(
				message, bodyIndex.candidates(needle), rowIndex, widgets, usedWidgets);
		if (exactMatch != null || !isPrivateMessage(message)) {
			return exactMatch;
		}

		return selectRenderedFontBodyCandidate(
				message, bodyIndex.candidatesIgnoreCase(needle), rowIndex, widgets, usedWidgets);
	}

	/*
	 * Selects one unused body candidate using sender-confirmed ownership.
	 *
	 * Body-only fallback is retained only for semantic records without a sender.
	 */
	private RenderedTextWidget selectRenderedFontBodyCandidate(
			TaggedMessage message, List<RenderedTextWidget> candidates,
			RenderedRowIndex rowIndex, List<RenderedTextWidget> allWidgets, Set<Widget> usedWidgets) {
		if (message == null || candidates == null || candidates.isEmpty()
				|| rowIndex == null || allWidgets == null || usedWidgets == null) {
			return null;
		}

		final String sender = message.getCanonicalSender();
		final boolean senderKnown = sender != null && !sender.isEmpty();
		RenderedTextWidget bodyFallback = null;

		for (RenderedTextWidget rendered : candidates) {
			if (rendered == null || rendered.widget == null
					|| usedWidgets.contains(rendered.widget) || rendered.widget.isHidden()) {
				continue;
			}

			if (!senderKnown && bodyFallback == null) {
				bodyFallback = rendered;
			}

			if (senderKnown && hasRenderedSenderOnRow(rendered, message, rowIndex, allWidgets)) {
				return rendered;
			}
		}

		/*
		 * Player-authored rows require sender confirmation. Body-only ownership is
		 * reserved for semantic records which genuinely have no sender.
		 */
		return senderKnown
				? null
				: bodyFallback;
	}

	/*
	 * Rebuilds reference and local-highlight geometry for both physical chat surfaces.
	 *
	 * A TaggedMessage may resolve independently on CHATBOX and SPLIT_PRIVATE.
	 */
	public LayoutResult layout() {

		final List<ReferenceHitbox> hitboxes = new ArrayList<>();
		final List<LocalHighlight> localHighlights = new ArrayList<>();

		pruneGeometryStateIfRepositoryChanged();

		if (repository.size() == 0) {
			return new LayoutResult(hitboxes, localHighlights);
		}

		final boolean includeLocalHighlights = shouldLayoutLocalHighlights();

		/*
		 * Split Private and normal CHATBOX remain independent physical surfaces.
		 *
		 * One TaggedMessage may legitimately resolve on both.
		 */
		layoutSurface(client.getWidget(InterfaceID.PmChat.CONTAINER), Surface.SPLIT_PRIVATE, hitboxes, localHighlights, includeLocalHighlights);
		layoutSurface(client.getWidget(InterfaceID.Chatbox.SCROLLAREA), Surface.CHATBOX, hitboxes, localHighlights, includeLocalHighlights);

		return new LayoutResult(hitboxes, localHighlights);
	}

	/*
	 * Layout semantic messages against one physical RuneScape chat surface.
	 *
	 * Visible body text seeds the optimized path. Repeated sender/body history can
	 * promote the pass to complete-surface correlation when off-screen ownership
	 * must be preserved. Widget ownership remains unique within this surface pass.
	 */
	private void layoutSurface(Widget surfaceWidget, Surface surface, List<ReferenceHitbox> output,
			List<LocalHighlight> localHighlights, boolean includeLocalHighlights) {
		if (surfaceWidget == null || surfaceWidget.isHidden()) {
			return;
		}

		Rectangle visibleBounds = null;
		if (surface == Surface.CHATBOX) {
			visibleBounds = surfaceWidget.getBounds();
			if (visibleBounds == null || visibleBounds.width <= 0 || visibleBounds.height <= 0) {
				return;
			}
		}

		/*
		 * Keep the optimized visible-row path for ordinary CHATBOX traffic.
		 *
		 * If retained history contains repeated sender/body occurrences which are
		 * not all visible, expand this pass to the complete physical surface so a
		 * newer off-screen occurrence cannot claim an older visible row.
		 */
		final List<RenderedTextWidget> textWidgets = new ArrayList<>();
		collectRenderedTextWidgets(surfaceWidget, surface, visibleBounds, textWidgets);
		if (textWidgets.isEmpty()) {
			return;
		}

		RenderedBodyIndex bodyIndex = new RenderedBodyIndex(textWidgets);
		RenderedRowIndex rowIndex = new RenderedRowIndex(textWidgets);
		List<TaggedMessage> messages = repository.snapshotMatchingBodies(
				bodyIndex.exactBodies(), bodyIndex.foldedBodies(), surface == Surface.SPLIT_PRIVATE);
		if (messages.isEmpty()) {
			return;
		}

		if (surface == Surface.CHATBOX && needsCompleteChatboxCorrelation(messages, bodyIndex, rowIndex, textWidgets)) {
			textWidgets.clear();
			collectRenderedTextWidgets(surfaceWidget, surface, null, textWidgets);
			if (textWidgets.isEmpty()) {
				return;
			}

			bodyIndex = new RenderedBodyIndex(textWidgets);
			rowIndex = new RenderedRowIndex(textWidgets);
			messages = repository.snapshotMatchingBodies(bodyIndex.exactBodies(), bodyIndex.foldedBodies(), false);
			if (messages.isEmpty()) {
				return;
			}
		}

		final Set<Widget> usedWidgets = Collections.newSetFromMap(new IdentityHashMap<>());

		for (TaggedMessage message : messages) {
			if (message == null) {
				continue;
			}

			final RenderedTextWidget messageWidget = findRenderedWidgetForMessage(
					message, textWidgets, bodyIndex, rowIndex, usedWidgets, surface);
			if (messageWidget == null || !isLiveRenderedCandidate(messageWidget)) {
				continue;
			}

			/*
			 * Reserve semantic ownership before deciding whether this row contributes
			 * visible geometry.
			 */
			usedWidgets.add(messageWidget.widget);

			if (!isVisibleForLayout(messageWidget, surface, visibleBounds)) {
				continue;
			}

			/*
			 * Sender interaction belongs to the physical sender Widget, not to the
			 * body's transient X/Y stabilization state.
			 */
			layoutSender(messageWidget, message, surface, textWidgets, rowIndex, output);

			final int horizontalOffset;
			final int verticalOffset;
			if (surface == Surface.CHATBOX) {
				horizontalOffset = resolveChatboxBodyXOffset(message, messageWidget);
				if (horizontalOffset == CHATBOX_X_PENDING) {
					continue;
				}

				verticalOffset = resolveChatboxBodyYOffset(message, messageWidget, surfaceWidget);
			} else {
				horizontalOffset = 0;
				verticalOffset = 0;
			}

			layoutMessage(messageWidget, message, surface, output, horizontalOffset, verticalOffset);

			if (includeLocalHighlights) {
				layoutLocalHighlight(messageWidget, message, surface, localHighlights, horizontalOffset, verticalOffset);
			}
		}
	}

	private boolean needsCompleteChatboxCorrelation(
			List<TaggedMessage> messages,
			RenderedBodyIndex bodyIndex,
			RenderedRowIndex rowIndex,
			List<RenderedTextWidget> textWidgets) {
		if (messages == null || messages.isEmpty() || bodyIndex == null
				|| rowIndex == null || textWidgets == null || textWidgets.isEmpty()) {
			return false;
		}

		final Map<String, Integer> semanticCounts = new HashMap<>();
		final Map<String, TaggedMessage> representatives = new HashMap<>();

		for (TaggedMessage message : messages) {
			if (message == null || message.getOriginalMessage() == null) {
				continue;
			}

			final String sender = message.getCanonicalSender();
			if (sender == null || sender.isEmpty()) {
				continue;
			}

			final String key = senderBodyKey(message);
			semanticCounts.put(key, semanticCounts.getOrDefault(key, 0) + 1);
			representatives.putIfAbsent(key, message);
		}

		for (Map.Entry<String, Integer> entry : semanticCounts.entrySet()) {
			if (entry.getValue() < 2) {
				continue;
			}

			final TaggedMessage representative = representatives.get(entry.getKey());
			if (representative == null) {
				continue;
			}

			List<RenderedTextWidget> candidates = bodyIndex.candidates(representative.getOriginalMessage());
			if (candidates.isEmpty() && isPrivateMessage(representative)) {
				candidates = bodyIndex.candidatesIgnoreCase(representative.getOriginalMessage());
			}

			int physicalCount = 0;
			for (RenderedTextWidget candidate : candidates) {
				if (hasRenderedSenderOnRow(candidate, representative, rowIndex, textWidgets)) {
					physicalCount++;
				}
			}

			if (physicalCount < entry.getValue()) {
				return true;
			}
		}

		return false;
	}

	private static String senderBodyKey(TaggedMessage message) {
		final String sender = message != null && message.getCanonicalSender() != null
				? playerNameKey(message.getCanonicalSender())
				: "";
		final String body = message != null && message.getOriginalMessage() != null
				? message.getOriginalMessage()
				: "";
		final String bodyKey = isPrivateMessage(message)
				? body.toLowerCase(Locale.ROOT)
				: body;
		return sender + '\u0000' + bodyKey;
	}

	private static boolean isVisibleForLayout(
			RenderedTextWidget rendered, Surface surface, Rectangle visibleBounds) {
		if (rendered == null || rendered.widget == null || rendered.widget.isHidden()) {
			return false;
		}

		if (surface != Surface.CHATBOX || visibleBounds == null) {
			return true;
		}

		final Rectangle bounds = rendered.widget.getBounds();
		return bounds != null && bounds.width > 0 && bounds.height > 0 && visibleBounds.intersects(bounds);
	}


	private static boolean isLiveRenderedCandidate(RenderedTextWidget rendered) {
		if (rendered == null || rendered.widget == null || rendered.widget.isHidden()) {
			return false;
		}

		final Rectangle bounds = rendered.widget.getBounds();
		return bounds != null && bounds.width > 0 && bounds.height > 0;
	}

	private void pruneGeometryStateIfRepositoryChanged() {
		final long revision = repository.getRevision();
		if (revision == lastGeometryPruneRevision) {
			return;
		}

		pruneChatboxBodyXState(repository.snapshotRetainedIds());
		lastGeometryPruneRevision = revision;
	}



	/*
	 * Apply the configured mention font to one owned physical message Widget.
	 *
	 * The selected appearance is resolved relative to the live base font. Known
	 * normal/bold companions are substituted while unrelated font families remain
	 * unchanged.
	 */
	private void applyMentionFont(Widget messageWidget, TaggedMessage message) {
		if (messageWidget == null || message == null) {
			return;
		}

		final boolean hasPlayerReference = message.getReferences() != null && !message.getReferences().isEmpty();
		final boolean hasLocalMention = message.getLocalMentionMatch() != null && message.getLocalMentionMatch()
				.isMatchesLocalPlayer();

		if (!hasPlayerReference && !hasLocalMention) {
			restoreOriginalFont(messageWidget);
			return;
		}

		final MentionFont mentionFont = config.fontMentions();
		if (mentionFont == null) {
			restoreOriginalFont(messageWidget);
			return;
		}

		final int currentFontId = messageWidget.getFontId();
		final MentionFontState state = mentionFontStates.get(messageWidget);
		final int baseFontId;
		if (state != null && currentFontId == state.appliedFontId) {
			baseFontId = state.originalFontId;
		} else {
			/*
			 * A different current FontId means RuneScape or another plugin replaced
			 * our previous presentation. Abandon stale ownership and treat the new
			 * live FontId as the active base.
			 */
			mentionFontStates.remove(messageWidget);
			baseFontId = currentFontId;
		}

		final int fontId = MentionFontResolver.fontIdFor(mentionFont, baseFontId);
		if (fontId == baseFontId) {
			return;
		}
		if (currentFontId != fontId) {
			messageWidget.setFontId(fontId);
		}

		mentionFontStates.put(messageWidget, new MentionFontState(baseFontId, fontId));
	}

	/*
	 * Restore one font still owned by RuneTags.
	 *
	 * If another owner has already changed the Widget's FontId,
	 * discard our stale ownership without writing the old value back.
	 */
	private void restoreOriginalFont(Widget widget) {
		if (widget == null) {
			return;
		}

		final MentionFontState state = mentionFontStates.remove(widget);
		if (state == null || widget.getFontId() != state.appliedFontId) {
			return;
		}

		if (state.originalFontId != state.appliedFontId) {
			widget.setFontId(state.originalFontId);
		}
	}

	/*
	 * Restore every physical Widget whose current font is still owned by RuneTags.
	 *
	 * Widgets changed by RuneScape or another plugin are deliberately left alone.
	 */
	private void restoreAllOriginalFonts() {
		if (mentionFontStates.isEmpty()) {
			return;
		}

		final Map<Widget, MentionFontState> fontsToRestore = new IdentityHashMap<>(mentionFontStates);
		mentionFontStates.clear();

		for (Map.Entry<Widget, MentionFontState> entry : fontsToRestore.entrySet()) {
			final Widget widget = entry.getKey();
			final MentionFontState state = entry.getValue();
			if (widget == null || state == null || widget.getFontId() != state.appliedFontId) {
				continue;
			}

			if (state.originalFontId != state.appliedFontId) {
				widget.setFontId(state.originalFontId);
			}
		}
	}

	private RenderedTextWidget findRenderedWidgetForMessage(TaggedMessage message, List<RenderedTextWidget> widgets,
			RenderedBodyIndex bodyIndex, RenderedRowIndex rowIndex, Set<Widget> usedWidgets, Surface surface) {
		if (message == null || widgets == null || bodyIndex == null || rowIndex == null || usedWidgets == null) {
			return null;
		}

		final String needle = message.getOriginalMessage();
		if (needle == null || needle.isEmpty()) {
			return null;
		}

		final List<RenderedTextWidget> exactCandidates = bodyIndex.candidates(needle);
		final RenderedTextWidget exactMatch = selectRenderedBodyCandidate(
				message, exactCandidates, rowIndex, widgets, usedWidgets);
		if (exactMatch != null || !isPrivateMessage(message) || needle.trim().isEmpty()) {
			return exactMatch;
		}

		/*
		 * Private-only compatibility fallback.
		 *
		 * The case-folded index narrows lookup to Widgets whose complete semantic
		 * body differs only by character case. Candidate order remains native
		 * collection order, and normal sender-confirmed/body-fallback selection is
		 * reused unchanged.
		 */
		final List<RenderedTextWidget> foldedCandidates = bodyIndex.candidatesIgnoreCase(needle);
		final RenderedTextWidget foldedMatch = selectRenderedBodyCandidate(
				message, foldedCandidates, rowIndex, widgets, usedWidgets);
		return foldedMatch;
	}

	/*
	 * Select one unused exact-body candidate using sender-confirmed ownership.
	 *
	 * Player-authored rows never fall back to body text alone.
	 */
	private RenderedTextWidget selectRenderedBodyCandidate(
			TaggedMessage message, List<RenderedTextWidget> candidates,
			RenderedRowIndex rowIndex, List<RenderedTextWidget> allWidgets, Set<Widget> usedWidgets) {
		if (message == null || candidates == null || candidates.isEmpty() || rowIndex == null
				|| allWidgets == null || usedWidgets == null) {
			return null;
		}

		final String sender = message.getCanonicalSender();
		final boolean senderKnown = sender != null && !sender.isEmpty();
		RenderedTextWidget bodyFallback = null;

		for (RenderedTextWidget rendered : candidates) {
			if (rendered == null || rendered.widget == null
					|| usedWidgets.contains(rendered.widget) || rendered.widget.isHidden()) {
				continue;
			}

			if (!senderKnown && bodyFallback == null) {
				bodyFallback = rendered;
			}

			if (senderKnown && hasRenderedSenderOnRow(rendered, message, rowIndex, allWidgets)) {
				return rendered;
			}
		}

		/*
		 * Never let a later player-authored message claim another sender's row only
		 * because the visible body text is identical.
		 */
		return senderKnown
				? null
				: bodyFallback;
	}

	/*
	 * Confirm sender ownership using same-row candidates when possible.
	 *
	 * The indexed path uses pass-local bounds and revalidates only a sender match.
	 * If that cannot confirm ownership, the complete semantic Widget list remains
	 * the live reconstruction fallback.
	 */
	private boolean hasRenderedSenderOnRow(RenderedTextWidget messageWidget, TaggedMessage message,
			RenderedRowIndex rowIndex, List<RenderedTextWidget> widgets) {
		if (messageWidget == null || messageWidget.widget == null || message == null
				|| rowIndex == null || widgets == null) {
			return false;
		}

		final Rectangle messageBounds = messageWidget.bounds;
		final String sender = message.getCanonicalSender();
		if (messageBounds == null || sender == null || sender.isEmpty()) {
			return false;
		}

		final List<RenderedTextWidget> indexedCandidates = rowIndex.candidates(messageBounds.y);
		if (hasRenderedSenderInIndexedCandidates(messageWidget, messageBounds, sender, indexedCandidates)) {
			return true;
		}

		/*
		 * The pass-local row index handles the normal path without repeated Widget
		 * reads. Retain the original full live scan only as a reconstruction safety
		 * fallback when the indexed snapshot cannot confirm ownership.
		 */
		return hasRenderedSenderInLiveCandidates(messageWidget, sender, widgets);
	}

	private static boolean hasRenderedSenderInIndexedCandidates(
			RenderedTextWidget messageWidget, Rectangle messageBounds,
			String sender, List<RenderedTextWidget> candidates) {
		if (messageWidget == null || messageBounds == null || sender == null
				|| sender.isEmpty() || candidates == null || candidates.isEmpty()) {
			return false;
		}

		for (RenderedTextWidget candidate : candidates) {
			if (candidate == null || candidate.widget == null || candidate.widget == messageWidget.widget
					|| candidate.bounds == null || candidate.bounds.x > messageBounds.x) {
				continue;
			}
			if (indexOfName(candidate.semanticText, sender) < 0) {
				continue;
			}

			final Rectangle liveMessageBounds = messageWidget.widget.getBounds();
			final Rectangle liveCandidateBounds = candidate.widget.getBounds();
			if (liveMessageBounds != null && liveCandidateBounds != null
					&& liveCandidateBounds.y == liveMessageBounds.y
					&& liveCandidateBounds.x <= liveMessageBounds.x
					&& !candidate.widget.isHidden()) {
				return true;
			}
		}

		return false;
	}

	private static boolean hasRenderedSenderInLiveCandidates(
			RenderedTextWidget messageWidget, String sender, List<RenderedTextWidget> candidates) {
		if (messageWidget == null || messageWidget.widget == null || sender == null
				|| sender.isEmpty() || candidates == null || candidates.isEmpty()) {
			return false;
		}

		final Rectangle messageBounds = messageWidget.widget.getBounds();
		if (messageBounds == null || messageBounds.width <= 0 || messageBounds.height <= 0) {
			return false;
		}

		for (RenderedTextWidget candidate : candidates) {
			if (candidate == null || candidate.widget == null
					|| candidate.widget == messageWidget.widget || candidate.widget.isHidden()) {
				continue;
			}

			final Rectangle candidateBounds = candidate.widget.getBounds();
			if (candidateBounds == null || candidateBounds.width <= 0 || candidateBounds.height <= 0
					|| candidateBounds.y != messageBounds.y || candidateBounds.x > messageBounds.x) {
				continue;
			}

			if (indexOfName(candidate.semanticText, sender) >= 0) {
				return true;
			}
		}

		return false;
	}

	/*
	 * Resolve the physical message-body widget for one semantic TaggedMessage.
	 *
	 * This exposes the same sender-aware association used by clickable reference
	 * layout so other RuneTags rendering layers do not maintain a second,
	 * potentially divergent widget-matching implementation.
	 *
	 * Widget ownership remains local to the caller's physical surface pass through
	 * the supplied usedWidgets set.
	 */
	public Widget findRenderedMessageWidget(TaggedMessage message, List<Widget> widgets, Set<Widget> usedWidgets) {
		if (message == null || widgets == null || usedWidgets == null) {
			return null;
		}

		return findWidgetForMessage(message, widgets, usedWidgets);
	}

	/*
	 * Find the rendered widget containing the semantic message body.
	 *
	 * The known-good live matcher remains authoritative. Private chat gets one
	 * narrow compatibility retry because RuneScape/RuneLite may canonicalize the
	 * local account-name casing after the ChatMessage was recorded
	 * (for example, "@santa" -> "@Santa").
	 */
	private Widget findWidgetForMessage(TaggedMessage message, List<Widget> widgets, Set<Widget> usedWidgets) {
		final Widget exactMatch = findWidgetForMessage(message, widgets, usedWidgets, false);

		if (exactMatch != null || !isPrivateMessage(message)) {
			return exactMatch;
		}

		/*
		 * Private-only fallback. This remains an exact whole-body comparison;
		 * character case is the only allowed difference.
		 */
		return findWidgetForMessage(message, widgets, usedWidgets, true);
	}

	private Widget findWidgetForMessage(TaggedMessage message,
			List<Widget> widgets, Set<Widget> usedWidgets, boolean ignoreCase) {
		if (message == null || widgets == null || usedWidgets == null) {
			return null;
		}

		final String needle = message.getOriginalMessage();
		if (needle == null || needle.isEmpty()) {
			return null;
		}

		final boolean whitespaceOnly = needle.trim().isEmpty();
		final String sender = message.getCanonicalSender();
		final boolean senderKnown = sender != null && !sender.isEmpty();
		Widget bodyFallback = null;

		for (Widget widget : widgets) {
			if (widget == null || usedWidgets.contains(widget) || widget.isHidden()) {
				continue;
			}

			final String raw = widget.getText();
			if (raw == null || raw.isEmpty()) {
				continue;
			}

			final String semantic = ChatText.toSemanticPlain(raw);
			final boolean bodyMatches;

			if (whitespaceOnly) {
				bodyMatches = semantic != null && !semantic.isEmpty() && semantic.trim().isEmpty();
			} else if (ignoreCase) {
				bodyMatches = semantic != null && semantic.equalsIgnoreCase(needle);
			} else {
				bodyMatches = semantic != null && semantic.equals(needle);
			}

			if (!bodyMatches) {
				continue;
			}

			if (!senderKnown && bodyFallback == null) {
				bodyFallback = widget;
			}

			if (senderKnown && hasSenderOnRow(widget, message, widgets)) {
				return widget;
			}
		}

		return senderKnown
				? null
				: bodyFallback;
	}

	/*
	 * Verify that a candidate message body shares its rendered row with the
	 * expected TaggedMessage sender.
	 *
	 * This disambiguates whitespace-only message bodies without treating every
	 * ordinary widget containing a space as a match.
	 */
	private boolean hasSenderOnRow(Widget messageWidget, TaggedMessage message, List<Widget> widgets) {
		if (messageWidget == null || message == null || widgets == null) {
			return false;
		}

		final Rectangle messageBounds = messageWidget.getBounds();
		final String sender = message.getCanonicalSender();
		if (messageBounds == null || sender == null || sender.isEmpty()) {
			return false;
		}

		for (Widget candidate : widgets) {
			if (candidate == null || candidate == messageWidget || candidate.isHidden()) {
				continue;
			}

			final Rectangle candidateBounds = candidate.getBounds();
			if (candidateBounds == null || candidateBounds.width <= 0 || candidateBounds.height <= 0) {
				continue;
			}

			/*
			 * Sender and body must occupy the same rendered chat row.
			 */
			if (!sameRenderedRow(candidate, messageWidget)) {
				continue;
			}

			/*
			 * The sender begins at or to the left of the message body.
			 */
			if (candidateBounds.x > messageBounds.x) {
				continue;
			}

			final String rawCandidateText = candidate.getText();
			if (rawCandidateText == null || rawCandidateText.isEmpty()) {
				continue;
			}

			final String semanticCandidateText = ChatText.toSemanticPlain(rawCandidateText);
			if (indexOfName(semanticCandidateText, sender) >= 0) {
				return true;
			}
		}

		return false;
	}

	/*
	 * Layout explicit @tags and recognized ordinary-name mentions inside the
	 * semantic message body.
	 *
	 * A RuneScape chat message may occupy multiple visual rows while remaining
	 * one Widget. Reference geometry must therefore be resolved against the
	 * widget's actual wrapping rather than treating the complete text as one
	 * horizontal line.
	 *
	 * One PlayerReference may legitimately produce more than one physical
	 * ReferenceHitbox if the reference itself crosses a visual line break.
	 */
	private void layoutMessage(RenderedTextWidget renderedWidget, TaggedMessage message, Surface surface,
			List<ReferenceHitbox> output, int horizontalOffset, int verticalOffset) {
		final Widget widget = renderedWidget != null
				? renderedWidget.widget
				: null;

		if (widget == null || message == null || message.getReferences() == null || message.getReferences().isEmpty()) {
			return;
		}

		final FontTypeFace font = widget.getFont();
		final Rectangle widgetBounds = offsetBounds(widget.getBounds(), horizontalOffset, verticalOffset);
		final String rawWidgetText = renderedWidget.rawText;
		final String semanticWidgetText = renderedWidget.semanticText;
		if (font == null || widgetBounds == null || widgetBounds.width <= 0 || widgetBounds.height <= 0
				|| rawWidgetText == null || semanticWidgetText == null) {
			return;
		}

		final String originalMessage = message.getOriginalMessage();
		if (originalMessage == null || originalMessage.isEmpty()) {
			return;
		}

		int messageStart = semanticWidgetText.indexOf(originalMessage);
		if (messageStart < 0 && isPrivateMessage(message)) {
			messageStart = indexOfIgnoreCase(semanticWidgetText, originalMessage);
		}
		if (messageStart < 0) {
			return;
		}

		final MessageMarkupMap map = MessageMarkupMap.create(rawWidgetText);
		if (!map.matchesPlain(semanticWidgetText)) {
			return;
		}

		final List<WrappedLine> wrappedLines = wrapSemanticLines(
				widget, rawWidgetText, semanticWidgetText, map, font, widgetBounds);
		if (wrappedLines.isEmpty()) {
			return;
		}

		for (PlayerReference reference : message.getReferences()) {
			if (reference == null || !ChatInteractionPolicy.isClickable(reference, config)) {
				continue;
			}

			final int semanticStart = messageStart + reference.getStartOffset();
			final int semanticEnd = messageStart + reference.getEndOffset();
			if (semanticStart < 0 || semanticEnd <= semanticStart || semanticEnd > semanticWidgetText.length()) {
				continue;
			}

			addWrappedSemanticHitboxes(widget, rawWidgetText, semanticWidgetText, map, font, widgetBounds, wrappedLines,
					semanticStart, semanticEnd, message.getId(), reference, surface, output);
		}
	}

	/*
	 * Lays out the rendered sender as an interaction-only SENDER reference.
	 *
	 * SENDER references are not added to TaggedMessage.references and do not affect
	 * mention processing.
	 */
	private void layoutSender(RenderedTextWidget messageWidget, TaggedMessage message, Surface surface,
			List<RenderedTextWidget> textWidgets, RenderedRowIndex rowIndex, List<ReferenceHitbox> output) {
		final String sender = message.getCanonicalSender();
		if (sender == null || sender.isEmpty()) {
			return;
		}

		final PlayerReference senderReference = PlayerReference.builder().rawText(sender).normalizedToken(sender)
				.lookupName(sender).startOffset(0).endOffset(sender.length()).type(ReferenceType.SENDER)
				.locallyResolved(false).identity(null).chatType(message.getType()).build();
		if (!ChatInteractionPolicy.isClickable(senderReference, config)) {
			return;
		}

		switch (surface) {
			case CHATBOX:
				/*
				 * Locates the normal-chatbox sender Widget on the body's rendered row and creates
				 * a hitbox for the account name.
				 */
				layoutChatboxSender(messageWidget, message, senderReference, surface, textWidgets, rowIndex, output);
				break;
			case SPLIT_PRIVATE:
				layoutSplitPrivateSender(
						messageWidget, message, senderReference, surface, textWidgets, rowIndex, output);
				break;
			default:
				break;
		}
	}

	private void layoutChatboxSender(
			RenderedTextWidget messageWidget, TaggedMessage message, PlayerReference senderReference, Surface surface,
			List<RenderedTextWidget> textWidgets, RenderedRowIndex rowIndex, List<ReferenceHitbox> output) {
		if (messageWidget == null || messageWidget.widget == null || rowIndex == null) {
			return;
		}

		final String sender = senderReference.getLookupName();
		final RenderedSenderMatch senderMatch = findChatboxSender(messageWidget, sender, textWidgets, rowIndex);
		if (senderMatch == null || senderMatch.rendered == null || senderMatch.rendered.widget == null) {
			return;
		}

		final int senderEnd = senderMatch.semanticStart + sender.length();
		addSemanticHitbox(senderMatch.rendered.widget, senderMatch.rendered.rawText, senderMatch.rendered.semanticText,
				senderMatch.semanticStart, senderEnd, message.getId(), senderReference, surface, output);
	}

	/*
	 * Resolves the normal-chatbox sender Widget shared by sender interaction
	 * and Favorite sender coloring.
	 */
	private RenderedSenderMatch findChatboxSender(RenderedTextWidget messageWidget, String sender,
			List<RenderedTextWidget> textWidgets, RenderedRowIndex rowIndex) {
		if (messageWidget == null || messageWidget.widget == null || sender == null || sender.isEmpty()
				|| textWidgets == null || rowIndex == null || messageWidget.bounds == null) {
			return null;
		}

		RenderedTextWidget senderWidget = null;
		int senderStart = -1;
		int bestCandidateX = Integer.MIN_VALUE;

		final List<RenderedTextWidget> indexedCandidates = rowIndex.candidates(messageWidget.bounds.y);
		for (RenderedTextWidget candidate : indexedCandidates) {
			if (candidate == null || candidate.widget == null || candidate.widget == messageWidget.widget
					|| candidate.bounds == null || candidate.bounds.x > messageWidget.bounds.x) {
				continue;
			}

			final int candidateSenderStart = indexOfName(candidate.semanticText, sender);
			if (candidateSenderStart < 0 || candidate.bounds.x <= bestCandidateX) {
				continue;
			}

			senderWidget = candidate;
			senderStart = candidateSenderStart;
			bestCandidateX = candidate.bounds.x;
		}

		if (senderWidget != null && senderStart >= 0 && isLiveSenderCandidate(senderWidget, messageWidget)) {
			return new RenderedSenderMatch(senderWidget, senderStart);
		}

		senderWidget = null;
		senderStart = -1;
		bestCandidateX = Integer.MIN_VALUE;

		final Rectangle liveMessageBounds = messageWidget.widget.getBounds();
		if (liveMessageBounds == null) {
			return null;
		}

		for (RenderedTextWidget candidate : textWidgets) {
			if (candidate == null || candidate.widget == null || candidate.widget == messageWidget.widget
					|| candidate.widget.isHidden()) {
				continue;
			}

			final Rectangle candidateBounds = candidate.widget.getBounds();
			if (candidateBounds == null || candidateBounds.width <= 0 || candidateBounds.height <= 0
					|| candidateBounds.y != liveMessageBounds.y || candidateBounds.x > liveMessageBounds.x) {
				continue;
			}

			final int candidateSenderStart = indexOfName(candidate.semanticText, sender);
			if (candidateSenderStart < 0 || candidateBounds.x <= bestCandidateX) {
				continue;
			}

			senderWidget = candidate;
			senderStart = candidateSenderStart;
			bestCandidateX = candidateBounds.x;
		}

		return senderWidget != null && senderStart >= 0
				? new RenderedSenderMatch(senderWidget, senderStart)
				: null;
	}

	private static boolean isLiveSenderCandidate(RenderedTextWidget senderWidget, RenderedTextWidget messageWidget) {
		if (senderWidget == null || senderWidget.widget == null || messageWidget == null
				|| messageWidget.widget == null || senderWidget.widget.isHidden()) {
			return false;
		}

		final Rectangle senderBounds = senderWidget.widget.getBounds();
		final Rectangle messageBounds = messageWidget.widget.getBounds();
		return senderBounds != null && messageBounds != null
				&& senderBounds.width > 0 && senderBounds.height > 0
				&& senderBounds.y == messageBounds.y && senderBounds.x <= messageBounds.x;
	}

	/*
	 * Locates the split-private sender/prefix Widget on the same rendered row
	 * and to the left of the message body.
	 *
	 * Matching does not depend on fixed child indices, account-name length,
	 * or message X position.
	 */
	private void layoutSplitPrivateSender(
			RenderedTextWidget messageWidget, TaggedMessage message, PlayerReference senderReference,
			Surface surface, List<RenderedTextWidget> textWidgets,
			RenderedRowIndex rowIndex, List<ReferenceHitbox> output) {
		if (messageWidget == null || messageWidget.widget == null || rowIndex == null || messageWidget.bounds == null) {
			return;
		}

		final String sender = senderReference.getLookupName();
		if (sender == null || sender.isEmpty()) {
			return;
		}

		RenderedTextWidget senderWidget = null;
		int senderStart = -1;

		final List<RenderedTextWidget> indexedCandidates = rowIndex.candidates(messageWidget.bounds.y);
		for (RenderedTextWidget candidate : indexedCandidates) {
			if (candidate == null || candidate.widget == null || candidate.widget == messageWidget.widget
					|| candidate.bounds == null || candidate.bounds.x > messageWidget.bounds.x) {
				continue;
			}

			final int candidateSenderStart = indexOfName(candidate.semanticText, sender);
			if (candidateSenderStart < 0 || !isLiveSenderCandidate(candidate, messageWidget)) {
				continue;
			}

			senderWidget = candidate;
			senderStart = candidateSenderStart;
			break;
		}

		if (senderWidget == null) {
			final Rectangle liveMessageBounds = messageWidget.widget.getBounds();
			if (liveMessageBounds == null) {
				return;
			}

			for (RenderedTextWidget candidate : textWidgets) {
				if (candidate == null || candidate.widget == null
						|| candidate.widget == messageWidget.widget || candidate.widget.isHidden()) {
					continue;
				}

				final Rectangle candidateBounds = candidate.widget.getBounds();
				if (candidateBounds == null || candidateBounds.width <= 0 || candidateBounds.height <= 0
						|| candidateBounds.y != liveMessageBounds.y || candidateBounds.x > liveMessageBounds.x) {
					continue;
				}

				final int candidateSenderStart = indexOfName(candidate.semanticText, sender);
				if (candidateSenderStart < 0) {
					continue;
				}

				senderWidget = candidate;
				senderStart = candidateSenderStart;
				break;
			}
		}

		if (senderWidget == null || senderWidget.widget == null || senderStart < 0) {
			return;
		}

		final int senderEnd = senderStart + sender.length();
		addSemanticHitbox(senderWidget.widget, senderWidget.rawText, senderWidget.semanticText, senderStart, senderEnd,
				message.getId(), senderReference, surface, output);
	}

	private int resolveChatboxBodyXOffset(TaggedMessage message, RenderedTextWidget renderedWidget) {
		if (message == null || renderedWidget == null || renderedWidget.widget == null) {
			return CHATBOX_X_PENDING;
		}

		final Rectangle bounds = renderedWidget.widget.getBounds();
		if (bounds == null || bounds.width <= 0 || bounds.height <= 0) {
			return CHATBOX_X_PENDING;
		}

		final long messageId = message.getId();
		final int currentX = bounds.x;
		final Integer acceptedX = acceptedChatboxBodyX.get(messageId);

		/*
		 * A temporary reconstructed X keeps rendering at the last accepted position.
		 */
		if (acceptedX != null && acceptedX == currentX) {
			pendingChatboxBodyX.remove(messageId);
			return 0;
		}

		final Integer pendingX = pendingChatboxBodyX.get(messageId);
		if (pendingX != null && pendingX == currentX) {
			pendingChatboxBodyX.remove(messageId);
			acceptedChatboxBodyX.put(messageId, currentX);
			return 0;
		}

		pendingChatboxBodyX.put(messageId, currentX);
		return acceptedX != null
				? acceptedX - currentX
				: CHATBOX_X_PENDING;
	}

	private int resolveChatboxBodyYOffset(
			TaggedMessage message, RenderedTextWidget renderedWidget, Widget surfaceWidget) {
		final ChatboxBodyState currentState = chatboxBodyState(renderedWidget, surfaceWidget);
		if (message == null || currentState == null) {
			return 0;
		}

		final long messageId = message.getId();
		final ChatboxBodyState stableState = stableChatboxBodyState(currentState);
		final ChatboxBodyState acceptedState = acceptedChatboxBodyRows.get(messageId);
		if (acceptedState == null) {
			acceptedChatboxBodyRows.put(messageId, stableState);
			return stableState.contentY - currentState.contentY;
		}

		/*
		 * Keep correcting a stale canvas Y only while RuneScape still reports the
		 * same physical row identity. A genuine OriginalY/RelativeY row move is
		 * accepted immediately so the overlay follows the chat text without lag.
		 */
		if (acceptedState.rowKey != null && acceptedState.rowKey.equals(currentState.rowKey)) {
			return acceptedState.contentY - currentState.contentY;
		}

		acceptedChatboxBodyRows.put(messageId, stableState);
		return stableState.contentY - currentState.contentY;
	}

	private ChatboxBodyState chatboxBodyState(RenderedTextWidget renderedWidget, Widget surfaceWidget) {
		if (renderedWidget == null || renderedWidget.widget == null || surfaceWidget == null) {
			return null;
		}

		final Widget widget = renderedWidget.widget;
		final Rectangle bounds = widget.getBounds();
		final Rectangle surfaceBounds = surfaceWidget.getBounds();
		final RowKey rowKey = RowKey.of(widget);
		if (bounds == null || bounds.width <= 0 || bounds.height <= 0
				|| surfaceBounds == null || surfaceBounds.height <= 0 || rowKey == null) {
			return null;
		}

		final int contentY = bounds.y - surfaceBounds.y + surfaceWidget.getScrollY();
		return new ChatboxBodyState(rowKey, contentY);
	}

	private static ChatboxBodyState stableChatboxBodyState(ChatboxBodyState state) {
		if (state == null || state.rowKey == null) {
			return state;
		}

		return new ChatboxBodyState(state.rowKey, state.rowKey.originalY);
	}

	private static boolean sameRenderedRow(Widget left, Widget right) {
		if (left == null || right == null) {
			return false;
		}

		final Rectangle leftBounds = left.getBounds();
		final Rectangle rightBounds = right.getBounds();
		return leftBounds != null && rightBounds != null && leftBounds.y == rightBounds.y;
	}

	private static Rectangle offsetBounds(Rectangle bounds, int horizontalOffset, int verticalOffset) {
		if (bounds == null || (horizontalOffset == 0 && verticalOffset == 0)) {
			return bounds;
		}

		final Rectangle adjusted = new Rectangle(bounds);
		adjusted.x += horizontalOffset;
		adjusted.y += verticalOffset;
		return adjusted;
	}

	/*
	 * Prunes CHATBOX geometry state only for messages no longer retained by RuneTags.
	 */
	private void pruneChatboxBodyXState(Set<Long> retainedMessageIds) {
		if (acceptedChatboxBodyX.isEmpty() && pendingChatboxBodyX.isEmpty() && acceptedChatboxBodyRows.isEmpty()) {
			return;
		}

		if (retainedMessageIds == null || retainedMessageIds.isEmpty()) {
			clearChatboxBodyXState();
			return;
		}

		acceptedChatboxBodyX.keySet().removeIf(messageId -> !retainedMessageIds.contains(messageId));
		pendingChatboxBodyX.keySet().removeIf(messageId -> !retainedMessageIds.contains(messageId));
		acceptedChatboxBodyRows.keySet().removeIf(messageId -> !retainedMessageIds.contains(messageId));
	}

	public void clearChatboxBodyXState() {
		acceptedChatboxBodyX.clear();
		pendingChatboxBodyX.clear();
		acceptedChatboxBodyRows.clear();
		lastGeometryPruneRevision = Long.MIN_VALUE;
	}

	/*
	 * Converts one semantic span into physical hitbox fragments across its wrapped
	 * visual lines.
	 */
	private void addSemanticHitbox(
			Widget widget, String rawWidgetText, String semanticWidgetText, int semanticStart, int semanticEnd,
			long messageId, PlayerReference reference, Surface surface, List<ReferenceHitbox> output) {
		if (widget == null || rawWidgetText == null || semanticWidgetText == null || semanticStart < 0
				|| semanticEnd <= semanticStart || semanticEnd > semanticWidgetText.length()) {
			return;
		}

		final Rectangle widgetBounds = widget.getBounds();
		final FontTypeFace font = widget.getFont();
		if (widgetBounds == null || widgetBounds.width <= 0 || widgetBounds.height <= 0 || font == null) {
			return;
		}

		final MessageMarkupMap map = MessageMarkupMap.create(rawWidgetText);
		if (!map.matchesPlain(semanticWidgetText)) {
			return;
		}

		final List<WrappedLine> wrappedLines = wrapSemanticLines(
				widget, rawWidgetText, semanticWidgetText, map, font, widgetBounds);
		if (wrappedLines.isEmpty()) {
			return;
		}

		addWrappedSemanticHitboxes(widget, rawWidgetText, semanticWidgetText, map, font, widgetBounds, wrappedLines,
				semanticStart, semanticEnd, messageId, reference, surface, output);
	}

	/*
	 * Measures the visual line count for raw RuneScape text using the supplied font
	 * and body width.
	 *
	 * FontLayoutService uses the same wrapping model before native row construction.
	 */
	public int measureWrappedLineCount(String rawWidgetText, FontTypeFace font, int availableWidth) {
		if (rawWidgetText == null || rawWidgetText.isEmpty() || font == null || availableWidth <= 0) {
			return 1;
		}

		final String semanticWidgetText = ChatText.toSemanticPlain(rawWidgetText);
		if (semanticWidgetText == null || semanticWidgetText.isEmpty()) {
			return 1;
		}

		final MessageMarkupMap map = MessageMarkupMap.create(rawWidgetText);
		if (!map.matchesPlain(semanticWidgetText)) {
			return 1;
		}

		/*
		 * PRE construction has no physical Widget; wrapSemanticLines() uses only
		 * the supplied bounds width.
		 */
		final Rectangle measurementBounds = new Rectangle(0, 0, availableWidth, 1);
		final List<WrappedLine> lines = wrapSemanticLines(
				null, rawWidgetText, semanticWidgetText, map, font, measurementBounds);
		return Math.max(1, lines.size());
	}

	/*
	 * Whether non-clickable local-token geometry can contribute an overlay
	 * decoration to the current frame.
	 */
	private boolean shouldLayoutLocalHighlights() {
		if (config.underlineMentions()) {
			return true;
		}

		if (!config.highlightBackground()) {
			return false;
		}

		return config.selfBackgroundColor() != null && config.selfBackgroundColor().getAlpha() > 0;
	}

	/*
	 * Layout Unique Highlight / normalized-account-name local matches which are
	 * not already represented by normal PlayerReference objects.
	 *
	 * The physical message Widget has already been resolved by layoutSurface().
	 */
	private void layoutLocalHighlight(RenderedTextWidget renderedWidget, TaggedMessage message, Surface surface,
			List<LocalHighlight> output, int horizontalOffset, int verticalOffset) {
		final Widget widget = renderedWidget != null
				? renderedWidget.widget
				: null;
		if (widget == null || message == null || output == null) {
			return;
		}

		final LocalMentionMatch localMatch = message.getLocalMentionMatch();
		if (!shouldDrawLocalToken(localMatch)) {
			return;
		}

		final String rawWidgetText = renderedWidget.rawText;
		if (rawWidgetText == null || rawWidgetText.isEmpty()) {
			return;
		}

		final String semanticWidgetText = renderedWidget.semanticText;
		final String originalMessage = message.getOriginalMessage();
		if (semanticWidgetText == null || originalMessage == null || originalMessage.isEmpty()) {
			return;
		}

		int messageStart = semanticWidgetText.indexOf(originalMessage);
		if (messageStart < 0 && isPrivateMessage(message)) {
			messageStart = indexOfIgnoreCase(semanticWidgetText, originalMessage);
		}
		if (messageStart < 0) {
			return;
		}

		final String token = localMatch.getMatchedToken();
		if (token == null || token.trim().isEmpty()) {
			return;
		}

		/*
		 * Mirror MessageFormatter's token semantics exactly.
		 */
		final String loweredMessage = originalMessage.toLowerCase(Locale.ROOT);
		final String loweredToken = token.toLowerCase(Locale.ROOT);
		int from = 0;
		while (from <= loweredMessage.length() - loweredToken.length()) {
			final int start = loweredMessage.indexOf(loweredToken, from);
			if (start < 0) {
				break;
			}

			final int end = start + loweredToken.length();
			if (hasBoundaries(loweredMessage, start, end) && !overlapsPlayerReference(start, end, message)) {
				final List<Rectangle> rectangles = layoutSemanticSpan(widget, rawWidgetText, semanticWidgetText,
						messageStart + start, messageStart + end, horizontalOffset, verticalOffset);
				for (Rectangle bounds : rectangles) {
					if (bounds == null || bounds.width <= 0 || bounds.height <= 0) {
						continue;
					}
					output.add(new LocalHighlight(message.getId(), bounds, surface));
				}
			}

			/*
			 * Preserve MessageFormatter's overlapping-search behavior.
			 */
			from = start + 1;
		}
	}

	/*
	 * Only local matches without a PlayerReference require additional overlay geometry.
	 */
	private static boolean shouldDrawLocalToken(LocalMentionMatch localMatch) {
		if (localMatch == null || !localMatch.isMatchesLocalPlayer() || localMatch.getReason() == null) {
			return false;
		}

		return localMatch.getReason() == MatchReason.UNIQUE_HIGHLIGHT
				|| localMatch.getReason() == MatchReason.NORMALIZED_ACCOUNT_NAME;
	}

	private static boolean overlapsPlayerReference(int start, int end, TaggedMessage message) {
		if (message == null || message.getReferences() == null) {
			return false;
		}

		for (PlayerReference reference : message.getReferences()) {
			if (reference == null) {
				continue;
			}

			if (start < reference.getEndOffset() && end > reference.getStartOffset()) {
				return true;
			}
		}
		return false;
	}

	private static boolean hasBoundaries(String text, int start, int end) {
		final boolean leftBoundary = start == 0 || !isNameChar(text.charAt(start - 1));
		final boolean rightBoundary = end == text.length() || !isNameChar(text.charAt(end));
		return leftBoundary && rightBoundary;
	}

	private static boolean isNameChar(char c) {
		return Character.isLetterOrDigit(c) || c == '_' || c == '-';
	}

	/*
	 * Resolves one semantic span into physical rectangles across the Widget's
	 * wrapped visual lines.
	 */
	public List<Rectangle> layoutSemanticSpan(Widget widget, int semanticStart, int semanticEnd) {
		final List<Rectangle> output = new ArrayList<>();
		if (widget == null || semanticStart < 0 || semanticEnd <= semanticStart) {
			return output;
		}

		final String rawWidgetText = widget.getText();
		if (rawWidgetText == null) {
			return output;
		}

		final String semanticWidgetText = ChatText.toSemanticPlain(rawWidgetText);
		return layoutSemanticSpan(widget, rawWidgetText, semanticWidgetText, semanticStart, semanticEnd, 0, 0);
	}

	/*
	 * Cached-text form used by the render pass. Bounds and FontTypeFace remain
	 * live reads so no reconstruction geometry is frozen in the semantic cache.
	 */
	private List<Rectangle> layoutSemanticSpan(Widget widget, String rawWidgetText, String semanticWidgetText,
			int semanticStart, int semanticEnd, int horizontalOffset, int verticalOffset) {
		final List<Rectangle> output = new ArrayList<>();

		if (widget == null || rawWidgetText == null || semanticWidgetText == null
				|| semanticStart < 0 || semanticEnd <= semanticStart) {
			return output;
		}

		final Rectangle widgetBounds = offsetBounds(widget.getBounds(), horizontalOffset, verticalOffset);
		final FontTypeFace font = widget.getFont();
		if (widgetBounds == null || widgetBounds.width <= 0 || widgetBounds.height <= 0 || font == null) {
			return output;
		}
		if (semanticEnd > semanticWidgetText.length()) {
			return output;
		}

		final MessageMarkupMap map = MessageMarkupMap.create(rawWidgetText);
		if (!map.matchesPlain(semanticWidgetText)) {
			return output;
		}

		final List<WrappedLine> wrappedLines = wrapSemanticLines(
				widget, rawWidgetText, semanticWidgetText, map, font, widgetBounds);
		if (wrappedLines.isEmpty()) {
			return output;
		}

		final int physicalLineHeight = resolvePhysicalLineHeight(widget, widgetBounds, wrappedLines.size());
		for (int lineIndex = 0; lineIndex < wrappedLines.size(); lineIndex++) {
			final WrappedLine line = wrappedLines.get(lineIndex);
			final int segmentStart = Math.max(semanticStart, line.start);
			final int segmentEnd = Math.min(semanticEnd, line.end);
			if (segmentStart >= segmentEnd) {
				continue;
			}

			/*
			 * Include leading raw markup on the first visual line so rendered images
			 * contribute their physical width.
			 */
			final int rawLineStart = line.start == 0
					? 0
					: map.rawBoundary(line.start);
			final int rawSegmentStart = map.rawBoundary(segmentStart);
			final int rawSegmentEnd = map.rawBoundary(segmentEnd);
			if (rawLineStart < 0 || rawSegmentStart < rawLineStart
					|| rawSegmentEnd < rawSegmentStart || rawSegmentEnd > rawWidgetText.length()) {
				continue;
			}

			final int prefixWidth = font.getTextWidth(rawWidgetText.substring(rawLineStart, rawSegmentStart));
			final int segmentWidth = Math.max(1, font.getTextWidth(
					rawWidgetText.substring(rawSegmentStart, rawSegmentEnd)));
			final int lineOriginX = alignedLineX(widget, widgetBounds, line.width);
			final int lineY = widgetBounds.y + (lineIndex * physicalLineHeight);
			output.add(new Rectangle(lineOriginX + prefixWidth, lineY, segmentWidth, physicalLineHeight));
		}
		return output;
	}

	/*
	 * Add the physical pieces of one semantic span.
	 *
	 * The span is intersected independently with every visual line occupied by
	 * the widget. If a name crosses a wrap boundary, each visible piece receives
	 * its own ReferenceHitbox pointing to the same PlayerReference.
	 */
	private void addWrappedSemanticHitboxes(
			Widget widget, String rawWidgetText, String semanticWidgetText, MessageMarkupMap map, FontTypeFace font,
			Rectangle widgetBounds, List<WrappedLine> wrappedLines, int semanticStart, int semanticEnd,
			long messageId, PlayerReference reference, Surface surface, List<ReferenceHitbox> output) {
		if (wrappedLines == null || wrappedLines.isEmpty()) {
			return;
		}

		/*
		 * Prefer the live Widget line height and fall back to allocated bounds when
		 * no usable line height is exposed.
		 */
		final int physicalLineHeight = resolvePhysicalLineHeight(widget, widgetBounds, wrappedLines.size());
		for (int lineIndex = 0; lineIndex < wrappedLines.size(); lineIndex++) {
			final WrappedLine line = wrappedLines.get(lineIndex);
			final int segmentStart = Math.max(semanticStart, line.start);
			final int segmentEnd = Math.min(semanticEnd, line.end);
			if (segmentStart >= segmentEnd) {
				continue;
			}

			/*
			 * Semantic offset zero excludes leading markup, but geometry must include rendered
			 * prefixes such as <img=...>. Continuation lines begin at their semantic raw boundary.
			 */
			final int rawLineStart = line.start == 0
					? 0
					: map.rawBoundary(line.start);
			final int rawSegmentStart = map.rawBoundary(segmentStart);
			final int rawSegmentEnd = map.rawBoundary(segmentEnd);
			if (rawLineStart < 0
					|| rawSegmentStart < rawLineStart
					|| rawSegmentEnd < rawSegmentStart
					|| rawSegmentEnd > rawWidgetText.length()) {
				continue;
			}

			final int prefixWidth = font.getTextWidth(rawWidgetText.substring(rawLineStart, rawSegmentStart));
			final int segmentWidth = Math.max(1, font.getTextWidth(
					rawWidgetText.substring(rawSegmentStart, rawSegmentEnd)));

			/*
			 * Resolve horizontal alignment independently for each visual line.
			 */
			final int lineOriginX = alignedLineX(widget, widgetBounds, line.width);
			final int lineY = widgetBounds.y + (lineIndex * physicalLineHeight);
			final Rectangle bounds = new Rectangle(lineOriginX + prefixWidth, lineY, segmentWidth, physicalLineHeight);
			output.add(new ReferenceHitbox(messageId, bounds, reference, surface));
		}
	}

	/*
	 * Reproduce the visual line ranges used by a RuneScape text widget.
	 *
	 * RuneScape exposes the final widget width and total expanded height but does
	 * not expose an API containing the semantic start/end offset of each rendered
	 * line. Reconstruct those ranges using the same Jagex FontTypeFace used by the
	 * widget.
	 *
	 * Wrapping prefers whitespace. If one unbroken token is wider than the
	 * widget, it falls back to a hard character boundary so layout can still
	 * progress.
	 */
	private List<WrappedLine> wrapSemanticLines(Widget widget, String rawWidgetText, String semanticWidgetText,
			MessageMarkupMap map, FontTypeFace font, Rectangle widgetBounds) {
		final List<WrappedLine> lines = new ArrayList<>();
		if (semanticWidgetText == null || semanticWidgetText.isEmpty() || widgetBounds.width <= 0) {
			return lines;
		}

		final int textLength = semanticWidgetText.length();
		int lineStart = 0;
		while (lineStart < textLength) {
			if (isExplicitLineBreak(semanticWidgetText.charAt(lineStart))) {
				lineStart++;
				continue;
			}

			int cursor = lineStart;
			int lastWhitespace = -1;
			int acceptedEnd = lineStart;
			while (cursor < textLength) {
				final char current = semanticWidgetText.charAt(cursor);
				if (isExplicitLineBreak(current)) {
					acceptedEnd = cursor;
					break;
				}

				if (Character.isWhitespace(current)) {
					lastWhitespace = cursor;
				}

				final int candidateEnd = cursor + 1;
				final int candidateWidth = semanticWidth(rawWidgetText, map, font, lineStart, candidateEnd);
				if (candidateWidth <= widgetBounds.width) {
					acceptedEnd = candidateEnd;
					cursor++;
					continue;
				}

				/*
				 * The candidate no longer fits.
				 *
				 * Prefer the last whitespace belonging to this line. The space
				 * itself remains semantically between the two words but is not
				 * treated as visible leading content on the following line.
				 */
				if (lastWhitespace >= lineStart) {
					acceptedEnd = lastWhitespace;
				} else if (acceptedEnd <= lineStart) {
					/*
					 * One token/character itself is wider than the widget.
					 * Force progress by allowing one semantic character.
					 */
					acceptedEnd = candidateEnd;
				}
				break;
			}

			if (cursor >= textLength) {
				acceptedEnd = textLength;
			}
			if (acceptedEnd < lineStart) {
				acceptedEnd = lineStart;
			}
			/*
			 * Avoid zero-length visual lines caused by unusual whitespace.
			 */
			if (acceptedEnd == lineStart) {
				acceptedEnd = Math.min(textLength, lineStart + 1);
			}

			final int lineWidth = semanticWidth(rawWidgetText, map, font, lineStart, acceptedEnd);
			lines.add(new WrappedLine(lineStart, acceptedEnd, Math.max(0, lineWidth)));

			int nextStart = acceptedEnd;
			while (nextStart < textLength) {
				final char next = semanticWidgetText.charAt(nextStart);
				if (isExplicitLineBreak(next)) {
					nextStart++;
					break;
				}
				/*
				 * RuneScape does not visually preserve the wrapping space at the
				 * start of the following line.
				 */
				if (Character.isWhitespace(next)) {
					nextStart++;
					continue;
				}
				break;
			}

			if (nextStart <= lineStart) {
				nextStart = Math.min(textLength, lineStart + 1);
			}
			lineStart = nextStart;
		}

		/*
		 * Normally the number of reconstructed lines will agree with the widget
		 * height. If the widget reports one physical row, preserving a single
		 * line avoids introducing artificial vertical geometry.
		 */
		if (lines.isEmpty()) {
			lines.add(new WrappedLine(0, textLength, semanticWidth(
					rawWidgetText, map, font, 0, textLength)));
		}

		return lines;
	}

	/*
	 * Resolve the physical height of one rendered text line.
	 *
	 * Prefer the Widget's live line height when available so RuneTags follows
	 * font/layout changes made by RuneScape or other plugins. Fall back to the
	 * Widget's allocated bounds when no useful line height is exposed.
	 */
	private static int resolvePhysicalLineHeight(Widget widget, Rectangle widgetBounds, int lineCount) {
		if (widget != null) {
			final int lineHeight = widget.getLineHeight();
			if (lineHeight > 0) {
				return lineHeight;
			}
		}
		return Math.max(1, widgetBounds.height / Math.max(1, lineCount));
	}

	/*
	 * Measure one semantic range using the actual raw RuneScape markup and the
	 * widget's own font.
	 */
	private static int semanticWidth(String rawWidgetText, MessageMarkupMap map, FontTypeFace font,
			int semanticStart, int semanticEnd) {
		if (semanticStart < 0 || semanticEnd < semanticStart) {
			return 0;
		}

		final int rawStart = map.rawBoundary(semanticStart);
		final int rawEnd = map.rawBoundary(semanticEnd);
		if (rawStart < 0 || rawEnd < rawStart || rawEnd > rawWidgetText.length()) {
			return 0;
		}
		return font.getTextWidth(rawWidgetText.substring(rawStart, rawEnd));
	}

	/*
	 * Resolve horizontal alignment for one visual line rather than the complete
	 * multiline widget.
	 */
	private static int alignedLineX(Widget widget, Rectangle bounds, int lineWidth) {
		switch (widget.getXTextAlignment()) {
			case WidgetTextAlignment.CENTER:
				return bounds.x + Math.max(0, (bounds.width - lineWidth) / 2);
			case WidgetTextAlignment.RIGHT:
				return bounds.x + Math.max(0, bounds.width - lineWidth);
			case WidgetTextAlignment.LEFT:
			default:
				return bounds.x;
		}
	}

	/*
	 * Semantic line-break characters which should terminate the current visual
	 * row immediately.
	 */
	private static boolean isExplicitLineBreak(char value) {
		return value == '\n' || value == '\r';
	}

	/*
	 * Find an account name without depending on capitalization or
	 * RuneScape's alternate space characters.
	 *
	 * NBSP and narrow-NBSP replacement is length-preserving, so the returned
	 * offset remains valid against the original semantic text and
	 * MessageMarkupMap.
	 */
	private static int indexOfIgnoreCase(String text, String needle) {
		if (text == null || needle == null || needle.isEmpty() || needle.length() > text.length()) {
			return -1;
		}

		final int lastStart = text.length() - needle.length();
		for (int i = 0; i <= lastStart; i++) {
			if (text.regionMatches(true, i, needle, 0, needle.length())) {
				return i;
			}
		}
		return -1;
	}

	private static int indexOfName(String text, String name) {
		if (text == null || text.isEmpty() || name == null || name.isEmpty()) {
			return -1;
		}

		final String comparableText = comparableNameText(text);
		final String comparableName = comparableNameText(name);
		if (comparableName.isEmpty() || comparableName.length() > comparableText.length()) {
			return -1;
		}

		final int maxStart = comparableText.length() - comparableName.length();
		for (int start = 0; start <= maxStart; start++) {
			if (comparableText.regionMatches(true, start, comparableName, 0, comparableName.length())) {
				return start;
			}
		}
		return -1;
	}

	private static String comparableNameText(String value) {
		return value.replace('\u00A0', ' ').replace('\u202F', ' ');
	}

	/*
	 * The split-private PmChat surface must only match private-message
	 * semantic records.
	 */
	private static boolean isPrivateMessage(TaggedMessage message) {
		if (message == null || message.getType() == null) {
			return false;
		}

		final ChatMessageType type = message.getType();
		return type == ChatMessageType.PRIVATECHAT
				|| type == ChatMessageType.MODPRIVATECHAT
				|| type == ChatMessageType.PRIVATECHATOUT;
	}

	/*
	 * Collects pass-local semantic text for eligible rendered Widgets.
	 *
	 * Cache text-bearing Widget membership instead of every descendant.
	 * Native reconstruction or semantic repository revision changes
	 * force rediscovery, while text, visibility, and geometry remain live reads.
	 */
	private void collectRenderedTextWidgets(Widget surfaceWidget, Surface surface, Rectangle visibleBounds,
			List<RenderedTextWidget> output) {
		if (surfaceWidget == null || surface == null || output == null) {
			return;
		}

		final RenderedSurfaceCache cache = renderedSurfaceCache(surface);
		final int topologySignature = surfaceTopologySignature(surfaceWidget);
		final long repositoryRevision = repository.getRevision();
		final boolean requiresRebuild = cache.root != surfaceWidget || cache.dirty
				|| cache.topologySignature != topologySignature || cache.repositoryRevision != repositoryRevision;

		boolean staleMembership = false;
		if (!requiresRebuild) {
			for (CachedRenderedWidget cached : cache.widgets) {
				if (cached == null || cached.widget == null || !isDescendantOrSelf(surfaceWidget, cached.widget)) {
					staleMembership = true;
					break;
				}
			}
		}

		if (requiresRebuild || staleMembership) {
			rebuildRenderedSurfaceCache(cache, surfaceWidget, topologySignature, repositoryRevision);
		}


		for (CachedRenderedWidget cached : cache.widgets) {
			addCachedRenderedTextWidget(cached, surface, visibleBounds, output);
		}
	}

	private void addCachedRenderedTextWidget(CachedRenderedWidget cached, Surface surface, Rectangle visibleBounds,
			List<RenderedTextWidget> output) {
		if (cached == null || cached.widget == null || cached.widget.isHidden()) {
			return;
		}

		final String rawText = cached.widget.getText();
		if (rawText == null || rawText.isEmpty()) {
			return;
		}

		final Rectangle bounds = cached.widget.getBounds();
		if (bounds == null || bounds.width <= 0 || bounds.height <= 0) {
			return;
		}

		if (surface == Surface.CHATBOX && visibleBounds != null && !visibleBounds.intersects(bounds)) {
			return;
		}

		if (cached.widget.getFont() == null) {
			return;
		}

		final String semanticText;
		if (rawText.equals(cached.rawText) && cached.semanticText != null) {
			semanticText = cached.semanticText;
		} else {
			semanticText = ChatText.toSemanticPlain(rawText);
			cached.rawText = rawText;
			cached.semanticText = semanticText;
		}

		output.add(new RenderedTextWidget(cached.widget, rawText, semanticText, new Rectangle(bounds)));
	}

	private void rebuildRenderedSurfaceCache(RenderedSurfaceCache cache, Widget surfaceWidget, int topologySignature,
			long repositoryRevision) {
		cache.root = surfaceWidget;
		cache.widgets.clear();

		final Set<Widget> visited = Collections.newSetFromMap(new IdentityHashMap<>());
		discoverRenderedSurfaceWidgets(surfaceWidget, cache.widgets, visited, 0);

		cache.topologySignature = topologySignature;
		cache.repositoryRevision = repositoryRevision;
		cache.dirty = false;
	}

	private void discoverRenderedSurfaceWidgets(
			Widget widget, List<CachedRenderedWidget> output, Set<Widget> visited, int depth) {
		if (widget == null || depth > MAX_WIDGET_DEPTH || !visited.add(widget)) {
			return;
		}

		final String rawText = widget.getText();
		if (rawText != null && !rawText.isEmpty()) {
			final CachedRenderedWidget cached = new CachedRenderedWidget(widget);
			cached.rawText = rawText;
			cached.semanticText = ChatText.toSemanticPlain(rawText);
			output.add(cached);
		}

		discoverRenderedSurfaceChildren(widget.getChildren(), output, visited, depth + 1);
		discoverRenderedSurfaceChildren(widget.getStaticChildren(), output, visited, depth + 1);
		discoverRenderedSurfaceChildren(widget.getNestedChildren(), output, visited, depth + 1);
	}

	private void discoverRenderedSurfaceChildren(
			Widget[] children, List<CachedRenderedWidget> output, Set<Widget> visited, int depth) {
		if (children == null) {
			return;
		}

		for (Widget child : children) {
			discoverRenderedSurfaceWidgets(child, output, visited, depth);
		}
	}

	private RenderedSurfaceCache renderedSurfaceCache(Surface surface) {
		return surface == Surface.SPLIT_PRIVATE
				? splitPrivateRenderedSurfaceCache
				: chatboxRenderedSurfaceCache;
	}

	private static int surfaceTopologySignature(Widget surfaceWidget) {
		if (surfaceWidget == null) {
			return 0;
		}

		int result = System.identityHashCode(surfaceWidget);
		result = 31 * result + widgetArrayIdentitySignature(surfaceWidget.getChildren());
		result = 31 * result + widgetArrayIdentitySignature(surfaceWidget.getStaticChildren());
		result = 31 * result + widgetArrayIdentitySignature(surfaceWidget.getNestedChildren());
		return result;
	}

	private static int widgetArrayIdentitySignature(Widget[] widgets) {
		if (widgets == null || widgets.length == 0) {
			return 0;
		}

		int result = widgets.length;
		for (Widget widget : widgets) {
			result = 31 * result + System.identityHashCode(widget);
		}
		return result;
	}

	private static boolean isDescendantOrSelf(Widget root, Widget widget) {
		for (Widget current = widget; current != null; current = current.getParent()) {
			if (current == root) {
				return true;
			}
		}
		return false;
	}

	/*
	 * Recursively collects rendered text Widgets beneath one physical chat surface.
	 */
	private void collectTextWidgets(Widget widget, List<Widget> output, Set<Widget> visited, int depth) {
		if (widget == null || depth > MAX_WIDGET_DEPTH || !visited.add(widget)) {
			return;
		}

		final String text = widget.getText();
		if (!widget.isHidden() && text != null && !text.isEmpty() && widget.getFont() != null) {
			final Rectangle bounds = widget.getBounds();

			/*
			 * Do not trim rendered text here. RuneScape can represent a real chat message
			 * body as markup containing only whitespace, and the Widget is still required
			 * as the physical row anchor used to locate its sender.
			 */
			if (bounds != null && bounds.width > 0 && bounds.height > 0) {
				output.add(widget);
			}
		}
		collectChildren(widget.getChildren(), output, visited, depth + 1);
		collectChildren(widget.getStaticChildren(), output, visited, depth + 1);
		collectChildren(widget.getNestedChildren(), output, visited, depth + 1);
	}

	private void collectChildren(Widget[] children, List<Widget> output, Set<Widget> visited, int depth) {
		if (children == null) {
			return;
		}

		for (Widget child : children) {
			collectTextWidgets(child, output, visited, depth);
		}
	}
}

package com.runetags.location;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import javax.inject.Inject;

/**
 * Loads RuneTags' coarse-location map from the bundled Locations.json.
 *
 * JSON values are RuneScape region-grid coordinates [regionX, regionY].
 */
public class LocationIndex {
	private static final String RESOURCE = "/com/runetags/context/Locations.json";

	private final Map<Integer, String> byRegion;

	@Inject
	public LocationIndex(Gson gson) {
		this.byRegion = load(gson);
	}

	public String findName(int regionId) {
		return byRegion.get(regionId);
	}

	public int size() {
		return byRegion.size();
	}

	private static Map<Integer, String> load(Gson gson) {
		final InputStream stream = LocationIndex.class.getResourceAsStream(RESOURCE);
		if (stream == null) {
			throw new IllegalStateException("Missing RuneTags location resource: " + RESOURCE);
		}

		final Type type = new TypeToken<LinkedHashMap<String, List<List<Integer>>>>() { }.getType();

		final Map<String, List<List<Integer>>> source = gson.fromJson(
				new InputStreamReader(stream, StandardCharsets.UTF_8), type);
		final Map<Integer, String> result = new LinkedHashMap<>();

		for (Map.Entry<String, List<List<Integer>>> entry : source.entrySet()) {
			for (List<Integer> pair : entry.getValue()) {
				if (pair == null || pair.size() < 2) {
					continue;
				}

				final int regionX = pair.get(0);
				final int regionY = pair.get(1);
				final int regionId = (regionX << 8) | regionY;
				result.put(regionId, entry.getKey());
			}
		}

		return Collections.unmodifiableMap(result);
	}
}

package com.runetags.location;

import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;

/**
 * Tracks the local player's coarse client-thread location.
 *
 * Contextual metric selection and encounter semantics remain owned by the context layer.
 */
public class PlayerLocationService {
	private final Client client;
	private final LocationIndex locationIndex;

	private volatile PlayerLocation current = PlayerLocation.unknown();

	public PlayerLocationService(Client client, LocationIndex locationIndex) {
		this.client = client;
		this.locationIndex = locationIndex;
	}

	public PlayerLocation getCurrent() {
		return current;
	}

	public void clear() {
		current = PlayerLocation.unknown();
	}

	/*
	 * Refreshes the local player's coarse location on RuneLite's client thread.
	 */
	public void refresh() {
		final Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null) {
			clear();
			return;
		}

		final WorldPoint point = localPlayer.getWorldLocation();
		if (point == null) {
			clear();
			return;
		}

		final int regionId = point.getRegionID();
		final String locationName = locationIndex.findName(regionId);
		current = new PlayerLocation(locationName, regionId);
	}
}

