package com.runetags.hiscores;

import com.runetags.player.AccountType;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;

import lombok.extern.slf4j.Slf4j;

import net.runelite.api.Experience;
import net.runelite.client.hiscore.HiscoreClient;
import net.runelite.client.hiscore.HiscoreEndpoint;
import net.runelite.client.hiscore.HiscoreResult;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.HiscoreSkillType;
import net.runelite.client.hiscore.Skill;

@Slf4j
public class HiscoreEnrichmentService {
	private final HiscoreClient hiscoreClient;
	private final HiscoreEnrichmentCache cache;
	private final Map<String, CompletableFuture<HiscoreEnrichmentCache.CachedProfileEnrichment>> inFlight =
			new ConcurrentHashMap<>();

	private CompletableFuture<AccountType> detectAccountType(String playerName) {
		/*
		 * Solo Ironman endpoints can positively identify Ironman variants. Missing entries cannot distinguish a
		 * normal account from Group Ironman, so that case remains UNKNOWN.
		 */
		return safeLookup(playerName, HiscoreEndpoint.IRONMAN).thenCompose(ironmanResult -> {
			if (ironmanResult == null) {
				return CompletableFuture.completedFuture(AccountType.UNKNOWN);
			}

			final CompletableFuture<HiscoreResult> hardcoreFuture =
					safeLookup(playerName, HiscoreEndpoint.HARDCORE_IRONMAN);
			final CompletableFuture<HiscoreResult> ultimateFuture =
					safeLookup(playerName, HiscoreEndpoint.ULTIMATE_IRONMAN);

			return hardcoreFuture.thenCombine(ultimateFuture, (hardcoreResult, ultimateResult) -> {
				if (hardcoreResult != null) {
					return AccountType.HARDCORE;
				}

				if (ultimateResult != null) {
					return AccountType.ULTIMATE;
				}

				return AccountType.IRONMAN;
			});
		});
	}

	private CompletableFuture<HiscoreResult> safeLookup(String playerName, HiscoreEndpoint endpoint) {
		try {
			final CompletableFuture<HiscoreResult> future = hiscoreClient.lookupAsync(playerName, endpoint);
			if (future == null) {
				return CompletableFuture.completedFuture(null);
			}

			return future.handle((result, throwable) -> throwable == null
					? result
					: null);
		} catch (RuntimeException ex) {
			return CompletableFuture.completedFuture(null);
		}
	}

	@lombok.Value
	private static class BaseLookupResult {
		HiscoreResult result;
		Throwable throwable;
	}

	private static Integer calculateCombatLevel(HiscoreResult result) {
		final Skill attack = result.getSkill(HiscoreSkill.ATTACK);
		final Skill strength = result.getSkill(HiscoreSkill.STRENGTH);
		final Skill defence = result.getSkill(HiscoreSkill.DEFENCE);
		final Skill hitpoints = result.getSkill(HiscoreSkill.HITPOINTS);
		final Skill magic = result.getSkill(HiscoreSkill.MAGIC);
		final Skill ranged = result.getSkill(HiscoreSkill.RANGED);
		final Skill prayer = result.getSkill(HiscoreSkill.PRAYER);
		if (attack == null || strength == null || defence == null || hitpoints == null
				|| magic == null || ranged == null || prayer == null) {
			return null;
		}

		if (attack.getLevel() < 1 || strength.getLevel() < 1 || defence.getLevel() < 1 || hitpoints.getLevel() < 1
				|| magic.getLevel() < 1 || ranged.getLevel() < 1 || prayer.getLevel() < 1) {
			return null;
		}

		return Experience.getCombatLevel(
				attack.getLevel(), strength.getLevel(), defence.getLevel(), hitpoints.getLevel(),
				magic.getLevel(), ranged.getLevel(), prayer.getLevel());
	}

	public HiscoreEnrichmentService(HiscoreClient hiscoreClient, HiscoreEnrichmentCache cache) {
		this.hiscoreClient = hiscoreClient;
		this.cache = cache;
	}

	public EnrichmentRequest enrich(String playerName) {
		final String requestKey = HiscoreEnrichmentCache.key(playerName);
		if (requestKey.isEmpty()) {
			return EnrichmentRequest.failed();
		}

		final HiscoreEnrichmentCache.CachedProfileEnrichment cached = cache.get(playerName).orElse(null);
		if (cached != null) {
			return EnrichmentRequest.cached(cached);
		}

		/*
		 * Synchronize request creation so concurrent callers cannot start duplicate
		 * lookups for the same normalized player. Network work remains asynchronous.
		 */
		synchronized (inFlight) {
			// Re-check after acquiring the lock in case another request populated the cache.
			final HiscoreEnrichmentCache.CachedProfileEnrichment cachedAfterLock =
					cache.get(playerName).orElse(null);
			if (cachedAfterLock != null) {
				return EnrichmentRequest.cached(cachedAfterLock);
			}

			final CompletableFuture<HiscoreEnrichmentCache.CachedProfileEnrichment> existing = inFlight.get(requestKey);
			if (existing != null) {
				return EnrichmentRequest.loading(existing);
			}

			final CompletableFuture<HiscoreResult> normalFuture;
			try {
				normalFuture = hiscoreClient.lookupAsync(playerName, HiscoreEndpoint.NORMAL);
			} catch (RuntimeException ex) {
				log.debug("[RuneTags][HiScore] Unable to Start Lookup for Player='{}'", playerName, ex);
				return EnrichmentRequest.failed();
			}

			if (normalFuture == null) {
				return EnrichmentRequest.failed();
			}

			final CompletableFuture<AccountType> accountTypeFuture = detectAccountType(playerName);
			final CompletableFuture<HiscoreEnrichmentCache.CachedProfileEnrichment> mapped =
					normalFuture.handle((result, throwable) -> {
						if (throwable != null) {
							log.debug(
									"[RuneTags][HiScore] Lookup Failed for Player='{}' | ERROR: {}",
									playerName, throwable.getMessage());
							return new BaseLookupResult(null, throwable);
						}

						return new BaseLookupResult(result, null);
					}).thenCombine(accountTypeFuture, (baseLookup, accountType) -> {
						if (baseLookup.getThrowable() != null) {
							return new HiscoreEnrichmentCache.CachedProfileEnrichment(
									HiscoreEnrichmentState.ERROR, null);
						}

						final HiscoreResult result = baseLookup.getResult();
						if (result == null) {
							cache.putNotFound(playerName);
							return new HiscoreEnrichmentCache.CachedProfileEnrichment(
									HiscoreEnrichmentState.NOT_FOUND, null);
						}

						final Skill overall = result.getSkill(HiscoreSkill.OVERALL);
						final Integer totalLevel = overall != null && overall.getLevel() >= 0
								? overall.getLevel()
								: null;
						final Integer combatLevel = calculateCombatLevel(result);
						final Map<String, Integer> contextValues = new LinkedHashMap<>();

						for (HiscoreSkill hiscoreSkill : HiscoreSkill.values()) {
							if (hiscoreSkill.getType() != HiscoreSkillType.BOSS
									&& hiscoreSkill.getType() != HiscoreSkillType.ACTIVITY
									&& hiscoreSkill.getType() != HiscoreSkillType.SKILL) {
								continue;
							}

							final Skill skill = result.getSkill(hiscoreSkill);
							if (skill == null || skill.getLevel() < 0) {
								continue;
							}

							contextValues.put(hiscoreSkill.name(), skill.getLevel());
						}

						final HiscoreProfileData data =
								new HiscoreProfileData(combatLevel, totalLevel, accountType, contextValues);
						cache.putSuccess(playerName, data);

						return new HiscoreEnrichmentCache.CachedProfileEnrichment(
								HiscoreEnrichmentState.LOADED,
								data);
					});

			inFlight.put(requestKey, mapped);
			mapped.whenComplete((result, throwable) -> inFlight.remove(requestKey, mapped));
			return EnrichmentRequest.loading(mapped);
		}
	}

	@lombok.Value
	public static class EnrichmentRequest {
		HiscoreEnrichmentState initialState;
		HiscoreProfileData initialData;
		CompletableFuture<HiscoreEnrichmentCache.CachedProfileEnrichment> future;

		static EnrichmentRequest cached(HiscoreEnrichmentCache.CachedProfileEnrichment cached) {
			return new EnrichmentRequest(cached.getState(), cached.getData(), null);
		}

		static EnrichmentRequest loading(
				CompletableFuture<HiscoreEnrichmentCache.CachedProfileEnrichment> future) {
			return new EnrichmentRequest(HiscoreEnrichmentState.LOADING, null, future);
		}

		static EnrichmentRequest failed() {
			return new EnrichmentRequest(HiscoreEnrichmentState.ERROR, null, null);
		}
	}
}

package com.runetags.hiscores;

import com.google.gson.Gson;

import java.io.IOException;
import java.time.Duration;
import java.time.Instant;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;

import lombok.Value;
import lombok.extern.slf4j.Slf4j;

import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Fetches EHP/EHB profile values from Wise Old Man for Quick-Card hiscores.
 *
 * Requests are lazy. Successful results are cached for ten minutes and negative
 * results briefly to avoid repeated lookups for unavailable or untracked players.
 */
@Slf4j
public class EfficiencyMetricService {
	private static final String PLAYER_API_URL = "https://api.wiseoldman.net/v2/players";
	private static final Duration SUCCESS_TTL = Duration.ofMinutes(10);
	private static final Duration NEGATIVE_TTL = Duration.ofMinutes(1);

	private final OkHttpClient httpClient;
	private final Gson gson;
	private final Map<String, CacheEntry> cache = new ConcurrentHashMap<>();
	private final Map<String, CompletableFuture<EfficiencyProfileData>> inFlight = new ConcurrentHashMap<>();
	private final Set<Call> activeCalls = ConcurrentHashMap.newKeySet();
	private volatile boolean closed;

	public EfficiencyMetricService(OkHttpClient httpClient, Gson gson) {
		this.httpClient = httpClient;
		this.gson = gson;
	}

	public CompletableFuture<EfficiencyProfileData> lookup(String playerName) {
		final String key = key(playerName);
		if (closed || key.isEmpty()) {
			return CompletableFuture.completedFuture(null);
		}

		final CacheEntry cached = cache.get(key);
		if (cached != null) {
			if (Instant.now().isBefore(cached.getExpiresAt())) {
				return CompletableFuture.completedFuture(cached.getData());
			}

			cache.remove(key, cached);
		}

		return inFlight.computeIfAbsent(key, ignored -> request(playerName.trim(), key));
	}

	public void clear() {
		cache.clear();
	}

	public void shutdown() {
		closed = true;
		cache.clear();

		for (Call call : activeCalls) {
			call.cancel();
		}

		activeCalls.clear();

		for (CompletableFuture<EfficiencyProfileData> future : inFlight.values()) {
			future.cancel(false);
		}

		inFlight.clear();
	}

	private CompletableFuture<EfficiencyProfileData> request(String playerName, String key) {
		final CompletableFuture<EfficiencyProfileData> future = new CompletableFuture<>();
		final HttpUrl baseUrl = HttpUrl.parse(PLAYER_API_URL);
		if (baseUrl == null) {
			future.complete(null);
			return future;
		}

		final HttpUrl url = baseUrl.newBuilder().addPathSegment(playerName).build();
		final Request request = new Request.Builder()
				.url(url).header("Accept", "application/json").header("User-Agent", "RuneTags RuneLite plugin").build();

		final Call call = httpClient.newCall(request);
		activeCalls.add(call);

		call.enqueue(new Callback() {
			@Override
			public void onFailure(Call failedCall, IOException exception) {
				activeCalls.remove(failedCall);
				complete(key, future, null, NEGATIVE_TTL);

				//log.debug("[RuneTags][WOM] Efficiency Lookup Failed for Player='{}' | ERROR: {}", playerName,
				// exception.getMessage());
			}

			@Override
			public void onResponse(Call completedCall, Response response) {
				activeCalls.remove(completedCall);
				EfficiencyProfileData data = null;

				try (Response closedResponse = response) {
					if (!closedResponse.isSuccessful()) {
						//log.debug("[RuneTags][WOM] Efficiency Lookup for Player='{}' returned HTTP {}", playerName,
						// closedResponse.code());
						return;
					}

					final ResponseBody body = closedResponse.body();
					if (body == null) {
						return;
					}

					final WiseOldManPlayer responseData = gson.fromJson(body.charStream(), WiseOldManPlayer.class);
					if (responseData != null) {
						data = new EfficiencyProfileData(valid(responseData.getEhp()), valid(responseData.getEhb()));
						if (data.getEhp() == null && data.getEhb() == null) {
							data = null;
						}
					}
				} catch (RuntimeException exception) {
					log.debug(
							"[RuneTags][WOM] Unable to Parse Efficiency Response for Player='{}' | ERROR: {}",
							playerName, exception.getMessage());
				} finally {
					complete(key, future, data, data != null
							? SUCCESS_TTL
							: NEGATIVE_TTL);
				}
			}
		});

		return future;
	}

	private void complete(
			String key,
			CompletableFuture<EfficiencyProfileData> future,
			EfficiencyProfileData data,
			Duration ttl) {
		if (!closed) {
			cache.put(key, new CacheEntry(data, Instant.now().plus(ttl)));
		}

		inFlight.remove(key, future);
		future.complete(data);
	}

	private static Double valid(Double value) {
		return value != null && Double.isFinite(value) && value >= 0d
				? value
				: null;
	}

	private static String key(String playerName) {
		if (playerName == null) {
			return "";
		}

		return playerName.trim().replace('_', ' ').replace('-', ' ').replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
	}

	@Value
	private static class CacheEntry {
		EfficiencyProfileData data;
		Instant expiresAt;
	}

	@Value
	private static class WiseOldManPlayer {
		Double ehp;
		Double ehb;
	}
}

