package com.runetags.hiscores;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;

public class HiscoreEnrichmentCache {
	private static final Duration SUCCESS_TTL = Duration.ofMinutes(10);
	private static final Duration NEGATIVE_TTL = Duration.ofSeconds(60);

	private final Map<String, CacheEntry> entries = new ConcurrentHashMap<>();
	private final Clock clock;

	public HiscoreEnrichmentCache() {
		this(Clock.systemUTC());
	}

	public HiscoreEnrichmentCache(Clock clock) {
		this.clock = clock != null
				? clock
				: Clock.systemUTC();
	}

	public Optional<CachedProfileEnrichment> get(String playerName) {
		final String key = key(playerName);
		if (key.isEmpty()) {
			return Optional.empty();
		}

		final CacheEntry entry = entries.get(key);
		if (entry == null) {
			return Optional.empty();
		}

		if (!clock.instant().isBefore(entry.expiresAt)) {
			entries.remove(key, entry);
			return Optional.empty();
		}

		return Optional.of(entry.value);
	}

	public void putSuccess(String playerName, HiscoreProfileData data) {
		put(playerName, new CachedProfileEnrichment(HiscoreEnrichmentState.LOADED, data), SUCCESS_TTL);
	}

	public void putNotFound(String playerName) {
		put(playerName, new CachedProfileEnrichment(HiscoreEnrichmentState.NOT_FOUND, null), NEGATIVE_TTL);
	}

	public void clear() {
		entries.clear();
	}

	private void put(String playerName, CachedProfileEnrichment value, Duration ttl) {
		final String key = key(playerName);
		if (key.isEmpty()) {
			return;
		}

		entries.put(key, new CacheEntry(value, clock.instant().plus(ttl)));
	}

	static String key(String playerName) {
		if (playerName == null) {
			return "";
		}

		return playerName.trim().replace('_', ' ').replace('-', ' ').replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
	}

	@lombok.Value
	public static class CachedProfileEnrichment {
		HiscoreEnrichmentState state;
		HiscoreProfileData data;
	}

	@lombok.Value
	private static class CacheEntry {
		CachedProfileEnrichment value;
		Instant expiresAt;
	}
}

package com.runetags.hiscores;

public enum HiscoreEnrichmentState {
	LOCAL,
	LOADING,
	LOADED,
	NOT_FOUND,
	ERROR
}

package com.runetags.hiscores;

import com.runetags.Configurations;
import com.runetags.config.LookupProvider;

import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;

import lombok.extern.slf4j.Slf4j;

import net.runelite.client.util.LinkBrowser;

@Slf4j
public class PlayerLookupService {
	private final Configurations config;

	public PlayerLookupService(Configurations config) {
		this.config = config;
	}

	public void lookup(String playerName) {
		if (playerName == null || playerName.trim().isEmpty()) {
			return;
		}

		final LookupProvider provider = config.lookupProvider();
		switch (provider) {
			case WISE_OLD_MAN:
				openWiseOldMan(playerName);
				break;

			case RUNE_PROFILE:
				openRuneProfile(playerName);
				break;

			case HISCORES:
			default:
				openHiscores(playerName);
				break;
		}

		//log.debug("[RuneTags][Lookup] Player='{}' | Provider={}", playerName, provider);
	}

	private static void openWiseOldMan(String playerName) {
		LinkBrowser.browse("https://wiseoldman.net/players/" + encodePath(playerName));
	}

	private static void openRuneProfile(String playerName) {
		LinkBrowser.browse("https://runeprofile.com/" + encodePath(playerName));
	}

	private static void openHiscores(String playerName) {
		LinkBrowser.browse(
				"https://secure.runescape.com/m=hiscore_oldschool/hiscorepersonal?user1=" + encodeQuery(playerName));
	}

	private static String encodePath(String value) {
		// URLEncoder uses '+' for spaces, but path segments require percent-encoded spaces.
		return URLEncoder.encode(value.trim(), StandardCharsets.UTF_8).replace("+", "%20");
	}

	private static String encodeQuery(String value) {
		return URLEncoder.encode(value.trim(), StandardCharsets.UTF_8);
	}
}

package com.runetags.mention;

import java.util.Locale;
import java.util.regex.Pattern;

import net.runelite.client.util.Text;

public class NameNormalizer {
	private static final Pattern SEPARATORS = Pattern.compile("[ _-]+");
	private static final Pattern NON_NAME_CHARS = Pattern.compile("[^A-Za-z0-9 _-]");

	public NormalizedPlayerName normalize(String raw) {
		final String canonical = canonicalize(raw);
		final String lowercase = canonical.toLowerCase(Locale.ROOT);
		final String comparison = SEPARATORS.matcher(lowercase).replaceAll("");
		final String tagged = SEPARATORS.matcher(lowercase).replaceAll("_");

		return new NormalizedPlayerName(canonical, comparison, tagged);
	}

	public String comparisonKey(String raw) {
		return normalize(raw).getComparisonKey();
	}

	public String taggedToken(String raw) {
		return normalize(raw).getTaggedToken();
	}

	public String canonicalize(String raw) {
		if (raw == null) {
			return "";
		}

		String clean = Text.removeTags(raw).trim();

		// Preserve RuneScape/RuneLite non-breaking player-name separators as spaces.
		clean = clean.replace('\u00A0', ' ').replace('\u202F', ' ');
		clean = NON_NAME_CHARS.matcher(clean).replaceAll("");
		clean = clean.replace('_', ' ').replace('-', ' ');
		clean = clean.replaceAll("\\s+", " ").trim();

		return clean;
	}
}

package com.runetags.mention;

import lombok.Value;

