package com.runetags.mention;

import com.runetags.player.PlayerDirectory;
import com.runetags.player.PlayerIdentity;
import com.runetags.reference.PlayerReference;
import com.runetags.reference.ReferenceType;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

public class KnownPlayerMentionParser {
	private final PlayerDirectory playerDirectory;
	private final NameNormalizer normalizer;

	public KnownPlayerMentionParser(PlayerDirectory playerDirectory, NameNormalizer normalizer) {
		this.playerDirectory = playerDirectory;
		this.normalizer = normalizer;
	}

	public List<PlayerReference> parse(String message, List<PlayerReference> reservedReferences) {
		final List<PlayerReference> matches = new ArrayList<>();
		if (message == null || message.isEmpty()) {
			return matches;
		}

		final String lowered = message.toLowerCase(Locale.ROOT);

		// Longer player names retain overlap priority.
		final List<PlayerIdentity> identities = playerDirectory.allSortedLongestNameFirst();

		/*
		 * Index normalized message spans once while retaining their original offsets.
		 */
		final Map<String, List<NormalizedMessageSpan>> normalizedSpanIndex = buildNormalizedSpanIndex(message);

		for (PlayerIdentity identity : identities) {
			final String canonical = identity.getCanonicalName();
			if (canonical == null || canonical.isEmpty()) {
				continue;
			}

			findVariant(message, lowered, canonical, identity, matches, reservedReferences);
			findVariant(message, lowered, canonical.replace(' ', '_'), identity, matches, reservedReferences);
			findVariant(message, lowered, canonical.replace(' ', '-'), identity, matches, reservedReferences);

			/*
			 * Normalized fallback matches equivalent separator representations such as
			 * "Santaclause" and "Santa clause".
			 */
			findNormalizedVariant(message, identity, normalizedSpanIndex, matches, reservedReferences);
		}

		matches.sort(Comparator.comparingInt(PlayerReference::getStartOffset));
		return removeOverlaps(matches);
	}

	private void findVariant(
			String original,
			String lowered,
			String candidate,
			PlayerIdentity identity,
			List<PlayerReference> output,
			List<PlayerReference> reserved) {
		if (candidate == null || candidate.isEmpty()) {
			return;
		}

		final String needle = candidate.toLowerCase(Locale.ROOT);
		int from = 0;

		while (from <= lowered.length() - needle.length()) {
			final int start = lowered.indexOf(needle, from);
			if (start < 0) {
				return;
			}

			final int end = start + needle.length();
			if (hasBoundaries(lowered, start, end)
					&& !isInsideExplicitTag(lowered, start)
					&& !overlapsAny(start, end, reserved)
					&& !overlapsAny(start, end, output)) {
				addReference(original, start, end, identity, output);
			}

			from = start + 1;
		}
	}

	private void findNormalizedVariant(
			String original,
			PlayerIdentity identity,
			Map<String, List<NormalizedMessageSpan>> normalizedSpanIndex,
			List<PlayerReference> output,
			List<PlayerReference> reserved) {
		String targetKey = identity.getNormalizedName();
		if (targetKey == null || targetKey.isEmpty()) {
			targetKey = normalizer.comparisonKey(identity.getCanonicalName());
		}

		if (targetKey.isEmpty()) {
			return;
		}

		final List<NormalizedMessageSpan> candidates = normalizedSpanIndex.get(targetKey);
		if (candidates == null || candidates.isEmpty()) {
			return;
		}

		// Preserve discovery order so identity ordering continues to control overlap priority.
		for (NormalizedMessageSpan candidate : candidates) {
			final int start = candidate.start;
			final int end = candidate.end;
			if (!hasBoundaries(original, start, end)
					|| overlapsAny(start, end, reserved)
					|| overlapsAny(start, end, output)) {
				continue;
			}

			addReference(original, start, end, identity, output);
		}
	}

	private Map<String, List<NormalizedMessageSpan>> buildNormalizedSpanIndex(String original) {
		final Map<String, List<NormalizedMessageSpan>> index = new HashMap<>();

		for (int start = 0; start < original.length(); start++) {
			if (!isNameChar(original.charAt(start))) {
				continue;
			}

			if (start > 0 && isNameChar(original.charAt(start - 1))) {
				continue;
			}

			if (isInsideExplicitTag(original, start)) {
				continue;
			}

			for (int end = start + 1; end <= original.length(); end++) {
				final char last = original.charAt(end - 1);
				if (!isNameChar(last) && last != ' ') {
					break;
				}

				if (end < original.length() && isNameChar(original.charAt(end))) {
					continue;
				}

				final String candidate = original.substring(start, end);
				final String candidateKey = normalizer.comparisonKey(candidate);
				if (candidateKey.isEmpty()) {
					continue;
				}

				index.computeIfAbsent(candidateKey, ignored -> new ArrayList<>())
						.add(new NormalizedMessageSpan(start, end));
			}
		}

		return index;
	}

	private void addReference(String original, int start, int end, PlayerIdentity identity, List<PlayerReference> output) {
		output.add(
				PlayerReference.builder()
						.rawText(original.substring(start, end))
						.normalizedToken(normalizer.taggedToken(identity.getCanonicalName()))
						.lookupName(identity.getCanonicalName())
						.startOffset(start)
						.endOffset(end)
						.type(ReferenceType.MENTION)
						.locallyResolved(true)
						.identity(identity)
						.build());
	}

	private static boolean hasBoundaries(String text, int start, int end) {
		return (start == 0 || !isNameChar(text.charAt(start - 1)))
				&& (end == text.length() || !isNameChar(text.charAt(end)));
	}

	private static boolean isInsideExplicitTag(String text, int start) {
		return start > 0 && text.charAt(start - 1) == '@';
	}

	private static boolean isNameChar(char c) {
		return Character.isLetterOrDigit(c) || c == '_' || c == '-';
	}

	private static boolean overlapsAny(int start, int end, List<PlayerReference> references) {
		if (references == null) {
			return false;
		}

		for (PlayerReference reference : references) {
			if (start < reference.getEndOffset() && end > reference.getStartOffset()) {
				return true;
			}
		}

		return false;
	}

	private static List<PlayerReference> removeOverlaps(List<PlayerReference> references) {
		final List<PlayerReference> result = new ArrayList<>();

		for (PlayerReference reference : references) {
			if (!overlapsAny(reference.getStartOffset(), reference.getEndOffset(), result)) {
				result.add(reference);
			}
		}

		return result;
	}

	private static final class NormalizedMessageSpan {
		private final int start;
		private final int end;

		private NormalizedMessageSpan(int start, int end) {
			this.start = start;
			this.end = end;
		}
	}
}

package com.runetags.mention;

import com.runetags.player.PlayerDirectory;
import com.runetags.player.PlayerIdentity;
import com.runetags.reference.PlayerReference;
import com.runetags.reference.ReferenceType;

import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class TagParser {
	private static final Pattern TAG_PATTERN = Pattern.compile("@([A-Za-z0-9_-]+)");

	private final NameNormalizer nameNormalizer;
	private final PlayerDirectory playerDirectory;

	public TagParser(NameNormalizer nameNormalizer, PlayerDirectory playerDirectory) {
		this.nameNormalizer = nameNormalizer;
		this.playerDirectory = playerDirectory;
	}

	public List<PlayerReference> parse(String message) {
		final List<PlayerReference> references = new ArrayList<>();
		if (message == null || message.isEmpty()) {
			return references;
		}

		final Matcher matcher = TAG_PATTERN.matcher(message);
		while (matcher.find()) {
			final String token = matcher.group(1);
			final String canonicalLookupName = nameNormalizer.canonicalize(token);
			final Optional<PlayerIdentity> identity = playerDirectory.find(canonicalLookupName);
			final String resolvedLookupName = identity.map(PlayerIdentity::getCanonicalName).orElse(canonicalLookupName);

			references.add(
					PlayerReference.builder()
							.rawText(matcher.group(0))
							.normalizedToken(nameNormalizer.taggedToken(token))
							.lookupName(resolvedLookupName)
							.startOffset(matcher.start())
							.endOffset(matcher.end())
							.type(ReferenceType.TAG)
							.locallyResolved(identity.isPresent())
							.identity(identity.orElse(null))
							.build());
		}

		return references;
	}
}

package com.runetags.mention;

public enum MatchReason {
	NONE,
	ACCOUNT_NAME,
	NORMALIZED_ACCOUNT_NAME,
	UNIQUE_HIGHLIGHT
}

package com.runetags.mention;

import com.runetags.Configurations;
import com.runetags.reference.PlayerReference;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import java.util.stream.Collectors;

public class LocalMentionMatcher {
	private final Configurations config;
	private final NameNormalizer normalizer;

	public LocalMentionMatcher(Configurations config, NameNormalizer normalizer) {
		this.config = config;
		this.normalizer = normalizer;
	}

	/*
	 * Matches a structured reference against the local account or a Unique Highlight.
	 * Unique Highlights never remap PlayerReference identity.
	 */
	public LocalMentionMatch match(PlayerReference reference, String localPlayerName) {
		if (reference == null || localPlayerName == null || localPlayerName.isEmpty()) {
			return LocalMentionMatch.none();
		}

		final String referenceText = reference.getRawText().replaceFirst("^@", "");
		final String referenceKey = normalizer.comparisonKey(referenceText);
		final String localKey = normalizer.comparisonKey(localPlayerName);

		// Local-account identity takes precedence over Unique Highlights.
		if (!referenceKey.isEmpty() && referenceKey.equals(localKey)) {
			return new LocalMentionMatch(true, MatchReason.ACCOUNT_NAME, reference.getRawText());
		}

		if (uniqueHighlightKeys().contains(referenceKey)) {
			return new LocalMentionMatch(true, MatchReason.UNIQUE_HIGHLIGHT, reference.getRawText());
		}

		return LocalMentionMatch.none();
	}

	/*
	 * Scans message text for a local-account variant or configured Unique Highlight.
	 */
	public LocalMentionMatch matchMessage(String message, String localPlayerName) {
		if (message == null || message.isEmpty()) {
			return LocalMentionMatch.none();
		}

		final String lowered = message.toLowerCase(Locale.ROOT);

		// Local-account variants take priority over Unique Highlights.
		if (localPlayerName != null && !localPlayerName.isEmpty()) {
			final String canonical = normalizer.canonicalize(localPlayerName).toLowerCase(Locale.ROOT);
			final String tagged = normalizer.taggedToken(localPlayerName).toLowerCase(Locale.ROOT);
			final String hyphenated = canonical.replace(' ', '-');

			if (containsWholePhrase(lowered, canonical)) {
				return new LocalMentionMatch(true, MatchReason.NORMALIZED_ACCOUNT_NAME, canonical);
			}

			if (containsWholePhrase(lowered, tagged)) {
				return new LocalMentionMatch(true, MatchReason.NORMALIZED_ACCOUNT_NAME, tagged);
			}

			if (containsWholePhrase(lowered, hyphenated)) {
				return new LocalMentionMatch(true, MatchReason.NORMALIZED_ACCOUNT_NAME, hyphenated);
			}
		}

		for (String trigger : configuredHighlights()) {
			final String loweredTrigger = trigger.toLowerCase(Locale.ROOT);
			if (containsWholePhrase(lowered, loweredTrigger)) {
				return new LocalMentionMatch(true, MatchReason.UNIQUE_HIGHLIGHT, trigger);
			}
		}

		return LocalMentionMatch.none();
	}

	private Set<String> uniqueHighlightKeys() {
		return configuredHighlights().stream()
				.map(normalizer::comparisonKey).filter(key -> !key.isEmpty()).collect(Collectors.toSet());
	}

	private Set<String> configuredHighlights() {
		final String configured = config.uniqueMentions();
		if (configured == null || configured.trim().isEmpty()) {
			return new HashSet<>();
		}

		return Arrays.stream(configured.split(","))
				.map(String::trim).filter(value -> !value.isEmpty()).collect(Collectors.toCollection(HashSet::new));
	}

	private static boolean containsWholePhrase(String message, String phrase) {
		if (phrase == null || phrase.isEmpty()) {
			return false;
		}

		int from = 0;
		while (from <= message.length() - phrase.length()) {
			final int index = message.indexOf(phrase, from);
			if (index < 0) {
				return false;
			}

			final boolean leftBoundary = index == 0 || !isNameChar(message.charAt(index - 1));
			final int right = index + phrase.length();
			final boolean rightBoundary = right == message.length() || !isNameChar(message.charAt(right));
			if (leftBoundary && rightBoundary) {
				return true;
			}

			from = index + 1;
		}

		return false;
	}

	private static boolean isNameChar(char c) {
		return Character.isLetterOrDigit(c) || c == '_' || c == '-';
	}
}

