package com.runetags.notification;

import com.runetags.Configurations;
import com.runetags.chat.TaggedMessage;

import java.awt.TrayIcon;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.Notifier;
import net.runelite.client.config.Notification;
import net.runelite.client.config.NotificationSound;

public class MentionNotificationService {
	private final Client client;
	private final Configurations config;
	private final Notifier notifier;

	public MentionNotificationService(Client client, Configurations config, Notifier notifier) {
		this.client = client;
		this.config = config;
		this.notifier = notifier;
	}

	public void notifyMention(TaggedMessage taggedMessage) {
		if (taggedMessage == null
				|| taggedMessage.getLocalMentionMatch() == null
				|| !taggedMessage.getLocalMentionMatch().isMatchesLocalPlayer()) {
			return;
		}

		/*
		 * Override RuneLite notification settings so RuneTags owns focus/flash behavior
		 * while tray, RuneLite sound, and game-message output remain disabled.
		 */
		final Notification notification = new Notification(
				true,								// enabled
				true,								// initialized
				true,								// override
				false,								// tray
				TrayIcon.MessageType.NONE,			// tray icon type
				config.requestFocusOnMention(),		// request focus
				NotificationSound.OFF,				// RuneLite sound
				null,								// custom sound name
				100,								// unused volume
				0,									// unused timeout
				false,								// game message
				config.flashOnMention(),			// flash mode
				config.flashColor(),				// flash color
				config.sendNotificationsWhenFocused());

		notifier.notify(notification, notificationText(taggedMessage));

		// Mention sound remains independent from focused-notification delivery.
		playMentionSound();
	}

	private void playMentionSound() {
		if (!config.playMentionSound()) {
			return;
		}

		if (client.getGameState() != GameState.LOGGED_IN) {
			return;
		}

		final int soundId = config.mentionSoundId();
		if (soundId <= 0) {
			return;
		}

		client.playSoundEffect(soundId);
	}

	private static String notificationText(TaggedMessage taggedMessage) {
		final String sender = taggedMessage.getCanonicalSender();
		final String message = taggedMessage.getOriginalMessage();
		if (sender == null || sender.isEmpty()) {
			return message != null && !message.isEmpty()
					? message
					: "[RuneTags][Notification] Player Mentioned";
		}
		if (message == null || message.isEmpty()) {
			return sender;
		}

		return sender + ": " + message;
	}
}

package com.runetags.suggestion;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.List;

import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

/**
 * Passive suggestion list anchored immediately above RuneScape's chat input.
 */
public final class SuggestionOverlay extends Overlay {
	private static final int WIDTH = 180;
	private static final int ROW_HEIGHT = 18;
	private static final int PADDING = 4;
	private static final int GAP = 3;

	private static final Color BACKGROUND = new Color(20, 20, 20, 210);
	private static final Color SELECTED_BACKGROUND = new Color(70, 60, 35, 220);
	private static final Color TEXT = new Color(220, 220, 220, 255);
	private static final Color SELECTED_TEXT = new Color(230, 185, 85, 255);

	private final Client client;
	private final SuggestionService suggestionService;

	public SuggestionOverlay(Client client, SuggestionService suggestionService) {
		this.client = client;
		this.suggestionService = suggestionService;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(OverlayPriority.HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics) {
		suggestionService.refresh();

		if (!suggestionService.isActive()) {
			return null;
		}

		final Widget input = client.getWidget(InterfaceID.Chatbox.INPUT);
		if (input == null || input.isHidden()) {
			return null;
		}

		final List<String> suggestions = suggestionService.getSuggestions();
		if (suggestions.isEmpty()) {
			return null;
		}

		final Rectangle inputBounds = input.getBounds();
		final int height = (PADDING * 2) + (suggestions.size() * ROW_HEIGHT);
		final int x = Math.max(4, Math.min(inputBounds.x, client.getCanvasWidth() - WIDTH - 4));
		final int y = Math.max(4, inputBounds.y - height - GAP);
		final int selectedIndex = suggestionService.getSelectedIndex();
		final FontMetrics metrics = graphics.getFontMetrics();

		graphics.setColor(BACKGROUND);
		graphics.fillRoundRect(x, y, WIDTH, height, 6, 6);

		for (int i = 0; i < suggestions.size(); i++) {
			final int rowY = y + PADDING + (i * ROW_HEIGHT);
			final boolean selected = i == selectedIndex;

			if (selected) {
				graphics.setColor(SELECTED_BACKGROUND);
				graphics.fillRoundRect(x + 2, rowY, WIDTH - 4, ROW_HEIGHT, 4, 4);
			}

			graphics.setColor(selected
					? SELECTED_TEXT
					: TEXT);
			graphics.drawString(
					"@" + suggestions.get(i),
					x + 7,
					rowY + ((ROW_HEIGHT - metrics.getHeight()) / 2) + metrics.getAscent());
		}

		return null;
	}
}

package com.runetags.suggestion;

import com.runetags.Configurations;
import com.runetags.player.PlayerDirectory;
import com.runetags.player.PlayerIdentity;
import com.runetags.player.PlayerSource;

import java.awt.event.KeyEvent;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.Set;

import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;

/**
 * Maintains passive @username suggestions for the local chat input.
 *
 * Completion only replaces the trailing @query in CHATINPUT. RuneScape remains
 * responsible for the later Enter/send action performed by the user.
 */
public final class SuggestionService {
	private static final int MAX_SUGGESTIONS = 6;

	private final Client client;
	private final ClientThread clientThread;
	private final Configurations config;
	private final PlayerDirectory playerDirectory;

	private final List<String> suggestions = new ArrayList<>();

	private String observedInput = "";
	private String query = "";
	private String suppressedInput;
	private int mentionStart = -1;
	private int selectedIndex;

	public SuggestionService(
			Client client,
			ClientThread clientThread,
			Configurations config,
			PlayerDirectory playerDirectory) {
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.playerDirectory = playerDirectory;
	}

	public void refresh() {
		if (!config.suggestUsernames()) {
			clear();
			return;
		}

		final String input = safe(client.getVarcStrValue(VarClientID.CHATINPUT));
		if (input.equals(suppressedInput)) {
			clear();
			observedInput = input;
			return;
		}

		suppressedInput = null;

		final int at = trailingMentionStart(input);
		if (at < 0) {
			clear();
			observedInput = input;
			return;
		}

		final String nextQuery = input.substring(at + 1);
		final boolean queryChanged = !input.equals(observedInput) || at != mentionStart;

		observedInput = input;
		mentionStart = at;
		query = nextQuery;

		final List<String> next = buildSuggestions(nextQuery);
		if (!next.equals(suggestions)) {
			suggestions.clear();
			suggestions.addAll(next);
		}

		if (queryChanged) {
			selectedIndex = 0;
		} else if (selectedIndex >= suggestions.size()) {
			selectedIndex = Math.max(0, suggestions.size() - 1);
		}
	}

	public boolean handleKeyPressed(KeyEvent event) {
		if (event == null || !config.suggestUsernames()) {
			return false;
		}

		refresh();

		if (suggestions.isEmpty()) {
			return false;
		}

		if (event.getKeyCode() == KeyEvent.VK_ESCAPE) {
			clear();
			event.consume();
			return true;
		}

		if (event.getKeyCode() == KeyEvent.VK_UP) {
			selectedIndex = (selectedIndex - 1 + suggestions.size()) % suggestions.size();
			event.consume();
			return true;
		}

		if (event.getKeyCode() == KeyEvent.VK_DOWN) {
			selectedIndex = (selectedIndex + 1) % suggestions.size();
			event.consume();
			return true;
		}

		if (config.completeSuggestionHotkey().matches(event)) {
			completeSelected();
			event.consume();
			return true;
		}

		return false;
	}

	public List<String> getSuggestions() {
		return new ArrayList<>(suggestions);
	}

	public int getSelectedIndex() {
		return selectedIndex;
	}

	public boolean isActive() {
		return config.suggestUsernames() && mentionStart >= 0 && !suggestions.isEmpty();
	}

	public void clear() {
		suggestions.clear();
		query = "";
		mentionStart = -1;
		selectedIndex = 0;
	}

	private void completeSelected() {
		if (mentionStart < 0 || selectedIndex < 0 || selectedIndex >= suggestions.size()) {
			return;
		}

		// Capture the selection before client-thread mutation.
		final int completionMentionStart = mentionStart;

		// Complete RuneScape name separators with underscores.
		final String completionName = suggestions.get(selectedIndex).replace(' ', '_').replace('\u00A0', '_');

		// Close suggestions before mutating CHATINPUT.
		clear();

		clientThread.invokeLater(() -> {
			final String input = safe(client.getVarcStrValue(VarClientID.CHATINPUT));

			// Leave changed input untouched if the captured @ position is no longer valid.
			if (completionMentionStart < 0
					|| completionMentionStart >= input.length()
					|| input.charAt(completionMentionStart) != '@') {
				return;
			}

			final String completed = input.substring(0, completionMentionStart) + "@" + completionName + " ";

			client.setVarcStrValue(VarClientID.CHATINPUT, completed);

			// Keep the rendered input Widget synchronized with CHATINPUT.
			final Widget chatboxInput = client.getWidget(InterfaceID.Chatbox.INPUT);
			if (chatboxInput != null) {
				final String widgetText = chatboxInput.getText();
				if (widgetText != null) {
					final int separator = widgetText.indexOf(':');
					if (separator >= 0) {
						final int colorStart = widgetText.indexOf("<col=", separator + 1);
						final int colorEnd = colorStart >= 0
								? widgetText.indexOf('>', colorStart)
								: -1;
						final String colorTag = colorStart >= 0 && colorEnd > colorStart
								? widgetText.substring(colorStart, colorEnd + 1)
								: "";
						final String prefix = widgetText.substring(0, separator + 1);

						if (!colorTag.isEmpty()) {
							chatboxInput.setText(
									prefix + " " + colorTag + completed + "</col>" + colorTag + "*</col" + ">");
						} else {
							chatboxInput.setText(prefix + " " + completed + "*");
						}
					}
				}
			}

			suppressedInput = completed;
			observedInput = completed;
		});
	}

	private List<String> buildSuggestions(String rawQuery) {
		// Require two raw query characters before separator normalization.
		final String rawNeedle = safe(rawQuery).toLowerCase(Locale.ENGLISH);
		if (rawNeedle.length() < 2) { // 2+ characters to begin offering suggestions
			return new ArrayList<>();
		}

		final String needle = normalizeSuggestionMatchText(rawNeedle);
		final List<Candidate> candidates = new ArrayList<>();

		for (PlayerIdentity identity : playerDirectory.all()) {
			if (identity == null || identity.getCanonicalName() == null || !sourceEnabled(identity.getSources())) {
				continue;
			}

			final String name = identity.getCanonicalName().trim();
			if (name.isEmpty()) {
				continue;
			}

			// Compare RuneScape name separators interchangeably without altering completion text.
			final String comparableName = normalizeSuggestionMatchText(name);
			final int matchIndex = comparableName.indexOf(needle);
			if (matchIndex < 0) {
				continue;
			}

			candidates.add(new Candidate(name, matchIndex == 0));
		}

		candidates.sort(Comparator.comparing(Candidate::isPrefixMatch).reversed()
				.thenComparing(Candidate::getName, String.CASE_INSENSITIVE_ORDER));

		final List<String> output = new ArrayList<>();
		for (Candidate candidate : candidates) {
			output.add(candidate.getName());

			if (output.size() >= MAX_SUGGESTIONS) {
				break;
			}
		}

		return output;
	}

	private static String normalizeSuggestionMatchText(String value) {
		if (value == null || value.isEmpty()) {
			return "";
		}

		return value.toLowerCase(Locale.ENGLISH).replace('_', ' ').replace('-', ' ').replace('\u00A0', ' ');
	}

	private boolean sourceEnabled(Set<PlayerSource> sources) {
		if (sources == null || sources.isEmpty()) {
			return false;
		}

		return (config.autocompleteFriends() && sources.contains(PlayerSource.FRIEND))
				|| (config.autocompleteClan()
				&& (sources.contains(PlayerSource.CLAN) || sources.contains(PlayerSource.GUEST_CLAN)))
				|| (config.autocompleteFriendsChat() && sources.contains(PlayerSource.FRIENDS_CHAT))
				|| (config.autocompleteParty() && sources.contains(PlayerSource.PARTY))
				|| (config.autocompleteNearby() && sources.contains(PlayerSource.NEARBY));
	}

	private static int trailingMentionStart(String input) {
		if (input == null || input.isEmpty()) {
			return -1;
		}

		final int at = input.lastIndexOf('@');
		if (at < 0) {
			return -1;
		}

		// Accept @ at input start, after a channel shortcut, or after whitespace.
		if (at > 0 && !Character.isWhitespace(input.charAt(at - 1)) && !isLeadingChannelShortcut(input, at)) {
			return -1;
		}

		final String tail = input.substring(at + 1);
		if (tail.indexOf('\n') >= 0 || tail.indexOf('\r') >= 0) {
			return -1;
		}

		return at;
	}

	private static boolean isLeadingChannelShortcut(String input, int mentionStart) {
		if (input == null || mentionStart < 1 || mentionStart > 3 || input.length() <= mentionStart) {
			return false;
		}

		for (int i = 0; i < mentionStart; i++) {
			if (input.charAt(i) != '/') {
				return false;
			}
		}

		return true;
	}

	private static String safe(String value) {
		return value == null
				? ""
				: value;
	}

	private static final class Candidate {
		private final String name;
		private final boolean prefixMatch;

		private Candidate(String name, boolean prefixMatch) {
			this.name = name;
			this.prefixMatch = prefixMatch;
		}

		private String getName() {
			return name;
		}

		private boolean isPrefixMatch() {
			return prefixMatch;
		}
	}
}

package com.runetags.target;

import net.runelite.api.Player;
import net.runelite.api.Renderable;
import net.runelite.client.callback.Hooks;

/**
 * Hides every player except the active RuneTags target while Hide All Others is active.
 *
 * Player models and player UI renderables are filtered; non-player renderables are unchanged.
 */
public class PlayerVisibilityService {
	private final Hooks hooks;
	private final TargetController targetController;

	private final Hooks.RenderableDrawListener drawListener = this::shouldDraw;

	private boolean registered;

	public PlayerVisibilityService(Hooks hooks, TargetController targetController) {
		this.hooks = hooks;
		this.targetController = targetController;
	}

	public void start() {
		if (registered) {
			return;
		}

		hooks.registerRenderableDrawListener(drawListener);
		registered = true;
	}

	public void stop() {
		if (!registered) {
			return;
		}

		hooks.unregisterRenderableDrawListener(drawListener);
		registered = false;
	}

	private boolean shouldDraw(Renderable renderable, boolean drawingUi) {
		// RuneTags only filters Player renderables.
		if (!(renderable instanceof Player)) {
			return true;
		}

		// Leave rendering untouched while Hide All Others is inactive.
		if (!targetController.shouldHideOtherPlayers()) {
			return true;
		}

		final Player player = (Player) renderable;
		final String playerName = player.getName();

		// Leave unidentified players visible.
		if (playerName == null || playerName.isEmpty()) {
			return true;
		}

		/*
		 * Keep only the active target visible. drawingUi is intentionally ignored so
		 * 3D models and 2D player UI follow the same visibility rule.
		 */
		return targetController.isTargetingName(playerName);
	}
}

package com.runetags.target;

import com.runetags.Configurations;
import com.runetags.config.HideOthersMode;
import com.runetags.quickprofile.QuickProfileModel;

import java.util.Locale;

import lombok.extern.slf4j.Slf4j;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.WorldView;

@Slf4j
public class TargetController {
	private final Client client;
	private final Configurations config;

	private volatile String targetName;
	private volatile Player targetPlayer;
	private volatile long targetStartedNanos;
	private volatile long hideOthersStartedNanos;

	public TargetController(Client client, Configurations config) {
		this.client = client;
		this.config = config;
	}

	public boolean toggleTarget(QuickProfileModel model) {
		if (model == null || !model.isNearby() || model.getDisplayName() == null
				|| model.getDisplayName().trim().isEmpty()) {
			return isTargeting();
		}

		return toggleTarget(model.getDisplayName());
	}

	/*
	 * Resolve native player-menu selections by name so all target entry points share
	 * the same nearby-player validation without retaining a stale menu actor.
	 */
	public boolean toggleTarget(Player player) {
		if (player == null || player.getName() == null || player.getName().trim().isEmpty()) {
			return isTargeting();
		}

		return toggleTarget(player.getName());
	}

	/*
	 * Toggle a nearby player by name when no guaranteed-live Player object is available.
	 */
	public boolean toggleTarget(String playerName) {
		if (playerName == null || playerName.trim().isEmpty()) {
			return isTargeting();
		}

		if (!config.targetPlayerOption()) {
			if (isTargeting()) {
				clear("targeting disabled");
			}

			return false;
		}

		final String requestedName = playerName.trim();
		if (isTargetingName(requestedName)) {
			clear("manually untargeted");
			return false;
		}

		final Player resolved = findNearbyPlayer(requestedName);
		if (resolved == null || resolved.getName() == null || resolved.getName().trim().isEmpty()) {
			return isTargeting();
		}

		final long now = System.nanoTime();

		targetName = resolved.getName();
		targetPlayer = resolved;
		targetStartedNanos = now;
		hideOthersStartedNanos = now;

		//log.debug("[RuneTags][Target] Targeted Player='{}'", targetName);

		return true;
	}

	public void refresh() {
		final String currentName = targetName;
		if (currentName == null) {
			targetPlayer = null;
			return;
		}

		if (!config.targetPlayerOption()) {
			clear("targeting disabled");
			return;
		}

		if (client.getGameState() != GameState.LOGGED_IN) {
			clear("not logged in");
			return;
		}

		final int timeoutSeconds = Math.max(0, config.targetTimeout());
		if (timeoutSeconds > 0
				&& targetStartedNanos > 0
				&& System.nanoTime() - targetStartedNanos >= timeoutSeconds * 1_000_000_000L) {
			clear("timeout");
			return;
		}

		final Player resolved = findNearbyPlayer(currentName);
		if (resolved == null) {
			clear("player left scene");
			return;
		}

		targetPlayer = resolved;
	}

	public void clear() {
		clear("cleared");
	}

	public void clear(String reason) {
		final String oldName = targetName;

		targetName = null;
		targetPlayer = null;
		targetStartedNanos = 0L;
		hideOthersStartedNanos = 0L;

		if (oldName != null) {
			//log.debug("[RuneTags][Target] Untargeted Player='{}' | Reason='{}'", oldName, reason);
		}
	}

	public boolean isTargeting() {
		return targetName != null;
	}

	public boolean isTargetingName(String playerName) {
		final String currentName = targetName;

		return currentName != null && normalize(currentName).equals(normalize(playerName));
	}

	public Player getTargetPlayer() {
		return targetPlayer;
	}

	private Player findNearbyPlayer(String playerName) {
		final WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null) {
			return null;
		}

		final String wanted = normalize(playerName);
		for (Player player : worldView.players()) {
			if (player == null || player.getName() == null) {
				continue;
			}

			if (normalize(player.getName()).equals(wanted)) {
				return player;
			}
		}

		return null;
	}

	public boolean shouldHideOtherPlayers() {
		if (!isTargeting()) {
			return false;
		}

		final HideOthersMode mode = config.hideAllOthers();
		if (mode == null || !mode.isEnabled()) {
			return false;
		}

		if (!mode.isTimed() || hideOthersStartedNanos <= 0L) {
			return false;
		}

		final long elapsedNanos = System.nanoTime() - hideOthersStartedNanos;
		final long durationNanos = mode.getDurationSeconds() * 1_000_000_000L;

		return elapsedNanos < durationNanos;
	}

	private static String normalize(String value) {
		return value == null
				? ""
				: value.trim().replace('_', ' ').replace('-', ' ').replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
	}
}

